// Kaizen Files · KF-25 · Retrospectiva (maqueta Retro).
// c2-retro (R056): checklist cumplido, lecciones repetidas, 2 preguntas y
// «Cerrar y enviar a la Biblioteca». c1-r-retro normal (R025): cerrar archiva
// el negocio (proyecto.cerrado) y lo nuevo queda como lección propuesta para
// Validar (retro.enviada). Sin proyecto en la ruta, lista los activos.
import {
  useDataProvider,
  useGetList,
  useGetOne,
  type Identifier,
} from "ra-core";
import { useState, type ReactNode } from "react";
import { Link, useParams } from "react-router";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

import { proyectoCerrado } from "../clientes/filasClientes";
import type { LeccionBiblioteca } from "../lecciones/biblioteca";
import { ValidarPage } from "../lecciones/ValidarPage";
import { registrarEvento } from "../misc/eventos";
import { Cargando, Vacio } from "../misc/Estados";
import type { ItemChecklist } from "../punto/puntoPartida";
import type { Company, Deal } from "../types";
import {
  AVISO_PREGUNTAS,
  PREGUNTAS,
  RUTA_RETRO,
  RUTA_RETRO_UNA,
  cambiosCerrar,
  checklistCumplido,
  leccionDeRetro,
  leccionesRepetidas,
  puntoDelNegocio,
  respuestasLimpias,
  rutaRetro,
} from "./retro";

const TODO = { page: 1, perPage: 1000 };

type Punto = {
  id: Identifier;
  nombre: string;
  tipo_proyecto: string;
  cliente_id?: Identifier | null;
  negocio_id?: Identifier | null;
  checklist?: ItemChecklist[] | null;
};

export const RetroPage = () => {
  const { id } = useParams();
  return (
    <div className="flex flex-col gap-4 py-2 max-w-3xl">
      <h1 className="text-2xl font-semibold">Retrospectiva</h1>
      {id ? <Retro negocioId={id} /> : <ProyectosAbiertos />}
    </div>
  );
};

RetroPage.path = RUTA_RETRO;
RetroPage.pathUna = RUTA_RETRO_UNA;

/** Sin proyecto elegido: los activos, cada uno con su retro. */
const ProyectosAbiertos = () => {
  const negocios = useGetList<Deal>("deals", {
    pagination: TODO,
    sort: { field: "name", order: "ASC" },
    filter: { "archived_at@is": null },
  });
  const activos = (negocios.data ?? []).filter((d) => !proyectoCerrado(d));
  return (
    <Seccion nombre="Elige el proyecto que vas a cerrar">
      {negocios.isError ? (
        <p
          role="alert"
          data-estado="error"
          className="text-sm text-destructive"
        >
          No se pudieron leer los proyectos. Revise la conexión y vuelva a
          intentar.
        </p>
      ) : negocios.isPending ? (
        <Cargando />
      ) : activos.length ? (
        <ul aria-label="Proyectos activos" className="list-none m-0 p-0">
          {activos.map((d) => (
            <li key={d.id} className="border-b last:border-b-0">
              <Link
                to={rutaRetro(d.id)}
                className="flex min-h-11 items-center py-2 font-medium"
              >
                {d.name}
              </Link>
            </li>
          ))}
        </ul>
      ) : (
        <Vacio>No hay proyectos activos para cerrar.</Vacio>
      )}
    </Seccion>
  );
};

const Retro = ({ negocioId }: { negocioId: Identifier }) => {
  const dp = useDataProvider();
  const negocio = useGetOne<Deal>("deals", { id: negocioId });
  const d = negocio.data;
  const cliente = useGetOne<Company>(
    "companies",
    { id: d?.company_id ?? "" },
    { enabled: d != null },
  );
  const puntos = useGetList<Punto>(
    "punto_partida",
    {
      pagination: TODO,
      sort: { field: "id", order: "DESC" },
      filter: { cliente_id: d?.company_id },
    },
    { enabled: d != null },
  );
  const lecciones = useGetList<LeccionBiblioteca>("lecciones", {
    pagination: TODO,
    sort: { field: "id", order: "ASC" },
    filter: { estado: "aprobada" },
  });

  const [respuestas, setRespuestas] = useState<[string, string]>(["", ""]);
  const [aviso, setAviso] = useState<string | null>(null);
  const [trabajando, setTrabajando] = useState(false);
  const [leccionNueva, setLeccionNueva] = useState<Identifier | null>(null);

  if (negocio.isError)
    return (
      <p role="alert" className="text-sm text-destructive">
        No se encontró el proyecto.
      </p>
    );
  if (negocio.isPending || !d)
    return <p className="text-sm text-muted-foreground">Cargando…</p>;

  const punto = puntoDelNegocio(puntos.data ?? [], d);
  const tipo = punto?.tipo_proyecto ?? null;
  const checklist = checklistCumplido(punto?.checklist);
  const repetidas = leccionesRepetidas(lecciones.data ?? [], tipo);
  const cerrado = proyectoCerrado(d) && leccionNueva == null;

  // Lo que se guarda sale del checklist y las lecciones: se espera a leerlos.
  const leyendo = puntos.isPending || lecciones.isPending;

  const cambiar = (i: 0 | 1, v: string) => {
    setAviso(null);
    setRespuestas((r) => (i === 0 ? [v, r[1]] : [r[0], v]));
  };

  const cerrar = async () => {
    if (trabajando || leyendo) return;
    const limpias = respuestasLimpias(respuestas);
    if (!limpias) return setAviso(AVISO_PREGUNTAS);
    setTrabajando(true);
    setAviso(null);
    try {
      await dp.update<Deal>("deals", {
        id: d.id,
        data: cambiosCerrar(new Date()),
        previousData: d,
      });
      registrarEvento("proyecto.cerrado", {
        negocio_id: d.id,
        cliente_id: d.company_id,
        nombre: d.name,
      });
      const { data: leccion } = await dp.create("lecciones", {
        data: leccionDeRetro(limpias, tipo),
      });
      await dp.create("evidencias", {
        data: { leccion_id: leccion.id, tipo: "retro" },
      });
      if (punto)
        await dp.create("retrospectivas", {
          data: {
            punto_partida_id: punto.id,
            respuesta_1: limpias[0],
            respuesta_2: limpias[1],
            checklist_cumplido: checklist.cumplidos,
            lecciones_repetidas: repetidas.length,
          },
        });
      registrarEvento("retro.enviada", {
        negocio_id: d.id,
        leccion_id: leccion.id,
        checklist_cumplido: checklist.cumplidos,
        checklist_total: checklist.total,
        lecciones_repetidas: repetidas.length,
      });
      setLeccionNueva(leccion.id);
      negocio.refetch();
    } catch (e) {
      setAviso(`No se pudo cerrar: ${(e as Error).message}`);
    } finally {
      setTrabajando(false);
    }
  };

  return (
    <>
      <div className="flex flex-col gap-1">
        <p className="m-0 text-lg font-semibold break-words">{d.name}</p>
        <p className="m-0 text-sm text-muted-foreground">
          {cliente.data?.name ?? "…"}
          {tipo ? ` · ${tipo}` : ""}
        </p>
        <Link
          to={`/companies/${d.company_id}/show`}
          className="inline-flex min-h-11 items-center self-start text-sm font-semibold"
        >
          ← Expediente
        </Link>
      </div>

      <Seccion nombre="Checklist cumplido">
        {puntos.isPending ? (
          <p className="text-sm text-muted-foreground">Cargando…</p>
        ) : checklist.total ? (
          <>
            <p className="m-0 text-sm font-semibold">
              {checklist.cumplidos} de {checklist.total} cumplidos
            </p>
            <ul className="list-none m-0 p-0">
              {checklist.items.map((i, n) => (
                <li
                  key={`${i.regla_id ?? "x"}-${n}`}
                  className="flex flex-wrap items-center gap-2 py-1.5 text-sm"
                >
                  <Badge variant={i.hecho ? "default" : "secondary"}>
                    {i.hecho ? "Cumplido" : "Pendiente"}
                  </Badge>
                  <span className="min-w-0 break-words">{i.texto}</span>
                </li>
              ))}
            </ul>
          </>
        ) : (
          <p className="text-sm text-muted-foreground">
            Este proyecto no tiene checklist del Punto de Partida.
          </p>
        )}
      </Seccion>

      <Seccion nombre="Lecciones repetidas">
        {lecciones.isPending ? (
          <p className="text-sm text-muted-foreground">Cargando…</p>
        ) : repetidas.length ? (
          <ul className="list-none m-0 p-0">
            {repetidas.map((l) => (
              <li key={l.id} className="py-1.5 text-sm break-words">
                {l.que_paso} · x{l.repeticiones}
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-sm text-muted-foreground">0 repetidas.</p>
        )}
      </Seccion>

      {leccionNueva != null ? (
        <div
          role="status"
          className="flex flex-col gap-1 rounded-md bg-green-50 p-3 text-sm text-green-900 dark:bg-green-900/30 dark:text-green-100"
        >
          <p className="m-0">
            Proyecto cerrado. Lo nuevo quedó propuesto para la Biblioteca.
          </p>
          <Link
            to={ValidarPage.pathUna.replace(":id", String(leccionNueva))}
            className="inline-flex min-h-11 items-center self-start font-semibold underline"
          >
            Ver en Validar
          </Link>
        </div>
      ) : cerrado ? (
        <p role="status" className="text-sm text-muted-foreground">
          Este proyecto ya está cerrado.
        </p>
      ) : (
        <Seccion nombre="2 preguntas">
          {PREGUNTAS.map((p, i) => (
            <div key={p} className="flex flex-col gap-1.5">
              <Label htmlFor={`retro-p${i + 1}`}>{p}</Label>
              <Textarea
                id={`retro-p${i + 1}`}
                value={respuestas[i]}
                onChange={(e) => cambiar(i as 0 | 1, e.target.value)}
                aria-invalid={
                  aviso === AVISO_PREGUNTAS && !respuestas[i].trim()
                    ? true
                    : undefined
                }
              />
            </div>
          ))}
          {aviso ? (
            <p role="alert" className="m-0 text-sm text-destructive">
              {aviso}
            </p>
          ) : null}
          <Button
            className="min-h-11 self-start"
            onClick={cerrar}
            disabled={trabajando || leyendo}
          >
            Cerrar y enviar a la Biblioteca
          </Button>
        </Seccion>
      )}
    </>
  );
};

const Seccion = ({
  nombre,
  children,
}: {
  nombre: string;
  children: ReactNode;
}) => (
  <section
    aria-label={nombre}
    className="flex min-w-0 flex-col gap-3 rounded-xl border bg-card p-4"
  >
    <h2 className="m-0 text-lg font-semibold">{nombre}</h2>
    {children}
  </section>
);
