// Kaizen Files · KF-21 · c2-cobros-leccion (R055). Funciones puras.
// Un pago es tardío si su fecha cae después del vencimiento de la factura.
// Un cliente con 2 o más facturas pagadas tarde repite la fricción.

type Id = string | number;

export type FacturaTardia = {
  id: Id;
  cliente_id?: Id | null;
  vence?: string | null;
};
export type PagoTardio = { factura_id: Id; fecha?: string | null };

export const MINIMO_TARDIOS = 2;

/** Cliente → facturas suyas pagadas después de vencer (solo los que repiten). */
export function clientesConPagosTardios(
  facturas: FacturaTardia[],
  pagos: PagoTardio[],
  minimo = MINIMO_TARDIOS,
): Map<Id, Id[]> {
  const vence = new Map(facturas.map((f) => [f.id, f]));
  const tarde = new Set<Id>();
  for (const p of pagos) {
    const f = vence.get(p.factura_id);
    // Fechas «YYYY-MM-DD»: el orden del texto es el de la fecha.
    if (f?.vence && p.fecha && p.fecha.slice(0, 10) > f.vence.slice(0, 10))
      tarde.add(f.id);
  }
  const porCliente = new Map<Id, Id[]>();
  for (const f of facturas)
    if (tarde.has(f.id) && f.cliente_id != null)
      porCliente.set(f.cliente_id, [
        ...(porCliente.get(f.cliente_id) ?? []),
        f.id,
      ]);
  for (const [c, ids] of porCliente)
    if (ids.length < minimo) porCliente.delete(c);
  return porCliente;
}
