import { Link } from "react-router";

import { InstalarApp } from "../misc/InstalarApp";
import { SECCIONES_MAS, type Seccion } from "./secciones";

/** Pantalla Más (maqueta CelMas): las 6 secciones que no caben en la barra. */
export const MasPage = () => (
  <div className="flex flex-col gap-4 py-2">
    <h1 className="text-2xl font-semibold">Más</h1>
    <section className="rounded-xl border bg-card px-4">
      <ul aria-label="Más" className="list-none m-0 p-0">
        {SECCIONES_MAS.map((s) => (
          <li key={s.ruta} className="border-b last:border-b-0">
            <Link
              to={s.ruta}
              className="flex flex-col gap-1 py-3 min-h-11 no-underline text-foreground"
            >
              <b className="text-[15px]">{s.nombre}</b>
              <span className="text-[13px] text-muted-foreground">
                {s.detalle}
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
    <InstalarApp />
  </div>
);

/** Lugar de una pantalla que construye otra partida. */
export const PantallaPendiente = ({ seccion }: { seccion: Seccion }) => (
  <div className="flex flex-col gap-2 py-2">
    <h1 className="text-2xl font-semibold">{seccion.nombre}</h1>
    {seccion.detalle ? (
      <p className="text-muted-foreground">{seccion.detalle}</p>
    ) : null}
    <p className="text-sm text-muted-foreground">
      Esta pantalla todavía no está lista
      {seccion.partida ? ` (la construye ${seccion.partida})` : ""}.
    </p>
  </div>
);
