// Kaizen Files · KF-26 · c2-tendencia (R057), maqueta Tendencia (no está en
// disco: se siguió 04-diseno.json y el contrato). ¿Bajan los errores?
// Repetidas por mes y por categoría y el checklist cumplido. La cuenta la hace
// medirTendencia (tendencia.ts); aquí solo se lee y se muestra.
import { useGetList } from "ra-core";
import { useEffect, useMemo, type ReactNode } from "react";

import type { Deal } from "../types";
import { registrarEvento } from "../misc/eventos";
import { Cargando } from "../misc/Estados";
import {
  RUTA_TENDENCIA,
  SIN_DATO,
  medirTendencia,
  nombreMes,
  textoChecklist,
  textoRepetidas,
  type Cumplimiento,
  type PorCategoria,
} from "./tendencia";

const TODO = { page: 1, perPage: 10000 };
const ORDEN = { field: "id", order: "ASC" } as const;

export const TendenciaPage = () => {
  const negocios = useGetList<Deal>("deals", { pagination: TODO, sort: ORDEN });
  const puntos = useGetList("punto_partida", { pagination: TODO, sort: ORDEN });
  const lecciones = useGetList("lecciones", {
    pagination: TODO,
    sort: ORDEN,
    filter: { estado: "aprobada" },
  });
  const retros = useGetList("retrospectivas", {
    pagination: TODO,
    sort: ORDEN,
  });
  const todas = [negocios, puntos, lecciones, retros];
  const error = todas.some((q) => q.isError);
  const cargando = todas.some((q) => q.isPending);

  const m = useMemo(
    () =>
      cargando || error
        ? null
        : medirTendencia({
            negocios: negocios.data ?? [],
            puntos: (puntos.data ?? []) as never[],
            lecciones: (lecciones.data ?? []) as never[],
            retros: (retros.data ?? []) as never[],
          }),
    [cargando, error, negocios.data, puntos.data, lecciones.data, retros.data],
  );

  useEffect(() => {
    if (!m) return;
    registrarEvento("tendencia.medida", {
      estado: m.estado,
      cerrados: m.cerrados,
      repetidas: m.repetidas,
      checklist_porcentaje: m.checklist.porcentaje,
      meses: m.meses.length,
    });
  }, [m]);

  return (
    <div className="flex min-w-0 flex-col gap-4 py-2 max-w-3xl">
      <div>
        <h1 className="text-2xl font-semibold">Tendencia</h1>
        <p className="m-0 text-muted-foreground">¿Bajan los errores?</p>
      </div>
      {error ? (
        <p
          role="alert"
          data-estado="error"
          className="text-sm text-destructive"
        >
          No se pudo medir: no se leyeron los proyectos o las lecciones.
        </p>
      ) : !m ? (
        <Cargando />
      ) : m.estado === SIN_DATO ? (
        <Seccion nombre="Resumen">
          <p className="m-0 text-lg font-semibold">Sin dato</p>
          <p data-estado="vacio" className="m-0 text-sm text-muted-foreground">
            Todavía no hay proyectos cerrados. Cierra uno desde la Retrospectiva
            para empezar a medir.
          </p>
        </Seccion>
      ) : (
        <>
          <Seccion nombre="Resumen">
            <dl className="m-0 grid grid-cols-1 gap-3 sm:grid-cols-3">
              <Dato nombre="Proyectos cerrados" valor={String(m.cerrados)} />
              <Dato nombre="Errores repetidos" valor={textoRepetidas(m)} />
              <Dato
                nombre="Checklist cumplido"
                valor={textoChecklist(m.checklist)}
                nota={notaSinDato(m.checklist)}
              />
            </dl>
          </Seccion>

          <Seccion nombre="Por mes">
            <ul className="list-none m-0 p-0">
              {m.meses.map((mes) => (
                <li
                  key={mes.mes}
                  className="flex flex-col gap-1.5 border-b py-3 first:pt-0 last:border-b-0 last:pb-0"
                >
                  <h3 className="m-0 text-base font-semibold capitalize">
                    {nombreMes(mes.mes)}
                  </h3>
                  <p className="m-0 text-sm">
                    {mes.cerrados} {mes.cerrados === 1 ? "cerrado" : "cerrados"}{" "}
                    · {textoRepetidas(mes)}
                  </p>
                  <p className="m-0 text-sm">
                    Checklist cumplido: {textoChecklist(mes.checklist)}
                    {notaSinDato(mes.checklist)
                      ? ` (${notaSinDato(mes.checklist)})`
                      : ""}
                  </p>
                  <Categorias lista={mes.categorias} />
                </li>
              ))}
            </ul>
          </Seccion>

          <Seccion nombre="Por categoría">
            {m.categorias.length ? (
              <Categorias lista={m.categorias} />
            ) : (
              <p className="m-0 text-sm text-muted-foreground">0 repetidas.</p>
            )}
          </Seccion>
        </>
      )}
    </div>
  );
};

TendenciaPage.path = RUTA_TENDENCIA;

const notaSinDato = (c: Cumplimiento) =>
  c.sinDato ? `${c.sinDato} sin dato` : "";

const Categorias = ({ lista }: { lista: PorCategoria[] }) =>
  lista.length ? (
    <ul className="list-none m-0 flex flex-col gap-1 p-0">
      {lista.map((c) => (
        <li
          key={c.categoria}
          className="flex items-center justify-between gap-3 text-sm"
        >
          <span className="min-w-0 break-words">{c.categoria}</span>
          <span className="font-semibold tabular-nums">{c.repetidas}</span>
        </li>
      ))}
    </ul>
  ) : null;

const Dato = ({
  nombre,
  valor,
  nota,
}: {
  nombre: string;
  valor: string;
  nota?: string;
}) => (
  <div className="flex flex-col gap-0.5">
    <dt className="text-sm text-muted-foreground">{nombre}</dt>
    <dd className="m-0 text-xl font-semibold">{valor}</dd>
    {nota ? (
      <dd className="m-0 text-xs text-muted-foreground">{nota}</dd>
    ) : null}
  </div>
);

const Seccion = ({
  nombre,
  children,
}: {
  nombre: string;
  children: ReactNode;
}) => (
  <section
    aria-label={nombre}
    className="flex min-w-0 flex-col gap-3 rounded-xl border bg-card p-4"
  >
    <h2 className="m-0 text-lg font-semibold">{nombre}</h2>
    {children}
  </section>
);
