// Kaizen Files · KF-26 · c1-r-retro límite (R026) y error (R027), c2-tendencia
// (R057), maqueta Tendencia (no está en disco: se siguió 04-diseno.json y el
// contrato). ¿Bajan los errores? Funciones puras, sin datos nuevos:
// - cerrado: proyectoCerrado de KF-07 (clientes/filasClientes.ts);
// - repetidas: leccionesRepetidas de KF-25 (retro/retro.ts), el mismo cálculo
//   que muestra la Retrospectiva;
// - checklist: la fila de `retrospectivas` (KF-25) del Punto de Partida del
//   proyecto (puntoDelNegocio). Sin esa fila el proyecto es «sin dato», nunca 0 %.
import type { Identifier } from "ra-core";

import { proyectoCerrado } from "../clientes/filasClientes";
import type { ItemChecklist } from "../punto/puntoPartida";
import {
  checklistCumplido,
  leccionesRepetidas,
  puntoDelNegocio,
} from "../retro/retro";
import type { Deal } from "../types";

export const RUTA_TENDENCIA = "/tendencia";
export const SIN_DATO = "sin dato";
export const SIN_CATEGORIA = "Sin categoría";

type Negocio = Pick<
  Deal,
  "id" | "name" | "company_id" | "stage" | "archived_at"
> & { updated_at?: string | null };

type Punto = {
  id: Identifier;
  nombre: string;
  tipo_proyecto: string;
  cliente_id?: Identifier | null;
  negocio_id?: Identifier | null;
  checklist?: ItemChecklist[] | null;
};

type Leccion = {
  id: Identifier;
  categoria?: string | null;
  tipo_proyecto?: string | null;
  repeticiones?: number | null;
  estado: string;
};

type Retro = {
  id: Identifier;
  punto_partida_id: Identifier;
  checklist_cumplido?: number | null;
};

export type Cumplimiento = {
  cumplidos: number;
  total: number;
  /** null = sin dato: ningún proyecto con checklist y retro. */
  porcentaje: number | null;
  conDato: number;
  sinDato: number;
};

export type PorCategoria = { categoria: string; repetidas: number };

export type MesTendencia = {
  /** «AAAA-MM» del cierre. */
  mes: string;
  cerrados: number;
  repetidas: number;
  categorias: PorCategoria[];
  checklist: Cumplimiento;
};

export type Medicion = {
  estado: "medido" | typeof SIN_DATO;
  cerrados: number;
  repetidas: number;
  categorias: PorCategoria[];
  checklist: Cumplimiento;
  meses: MesTendencia[];
};

/** Mes del cierre: archivado o, si se perdió sin archivar, su última fecha. */
export const mesDeCierre = (d: Negocio) =>
  (d.archived_at || d.updated_at || "").slice(0, 7) || SIN_DATO;

type Medido = {
  mes: string;
  categorias: string[];
  checklist: { cumplidos: number; total: number } | null;
};

const medirUno = (
  d: Negocio,
  puntos: Punto[],
  lecciones: Leccion[],
  retros: Retro[],
): Medido => {
  const punto = puntoDelNegocio(puntos, d);
  const categorias = leccionesRepetidas(
    lecciones,
    punto?.tipo_proyecto ?? null,
  ).map((l) => l.categoria?.trim() || SIN_CATEGORIA);
  const retro = punto
    ? retros.find((r) => String(r.punto_partida_id) === String(punto.id))
    : undefined;
  const { total } = checklistCumplido(punto?.checklist);
  const checklist =
    retro && retro.checklist_cumplido != null && total > 0
      ? { cumplidos: Math.min(retro.checklist_cumplido, total), total }
      : null;
  return { mes: mesDeCierre(d), categorias, checklist };
};

const sumar = (medidos: Medido[]) => {
  const conteo = new Map<string, number>();
  for (const c of medidos.flatMap((m) => m.categorias))
    conteo.set(c, (conteo.get(c) ?? 0) + 1);
  const categorias = [...conteo]
    .map(([categoria, repetidas]) => ({ categoria, repetidas }))
    .sort(
      (a, b) =>
        b.repetidas - a.repetidas || a.categoria.localeCompare(b.categoria),
    );
  const conDato = medidos.flatMap((m) => (m.checklist ? [m.checklist] : []));
  const cumplidos = conDato.reduce((s, c) => s + c.cumplidos, 0);
  const total = conDato.reduce((s, c) => s + c.total, 0);
  return {
    cerrados: medidos.length,
    repetidas: categorias.reduce((s, c) => s + c.repetidas, 0),
    categorias,
    checklist: {
      cumplidos,
      total,
      porcentaje: total ? Math.round((100 * cumplidos) / total) : null,
      conDato: conDato.length,
      sinDato: medidos.length - conDato.length,
    },
  };
};

/** ¿Bajan los errores? Repetidas por mes y categoría, y checklist cumplido. */
export function medirTendencia({
  negocios,
  puntos,
  lecciones,
  retros,
}: {
  negocios: Negocio[];
  puntos: Punto[];
  lecciones: Leccion[];
  retros: Retro[];
}): Medicion {
  const medidos = negocios
    .filter((d) => proyectoCerrado(d))
    .map((d) => medirUno(d, puntos, lecciones, retros));
  const porMes = new Map<string, Medido[]>();
  for (const m of medidos) porMes.set(m.mes, [...(porMes.get(m.mes) ?? []), m]);
  const meses = [...porMes]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([mes, lista]) => ({ mes, ...sumar(lista) }));
  return {
    estado: medidos.length ? "medido" : SIN_DATO,
    ...sumar(medidos),
    meses,
  };
}

/** «0 repetidas» si se midió y no hubo; «sin dato» si no hay cerrados. */
export const textoRepetidas = (m: { cerrados: number; repetidas: number }) =>
  m.cerrados === 0
    ? SIN_DATO
    : `${m.repetidas} ${m.repetidas === 1 ? "repetida" : "repetidas"}`;

export const textoChecklist = (c: Cumplimiento) =>
  c.porcentaje == null ? SIN_DATO : `${c.porcentaje} %`;

const MESES = [
  "enero",
  "febrero",
  "marzo",
  "abril",
  "mayo",
  "junio",
  "julio",
  "agosto",
  "septiembre",
  "octubre",
  "noviembre",
  "diciembre",
];

/** «2026-09» → «septiembre 2026». */
export const nombreMes = (mes: string) => {
  const [a, m] = mes.split("-").map(Number);
  return MESES[m - 1] && a ? `${MESES[m - 1]} ${a}` : mes;
};
