// Kaizen Files · KF-22 · c1-r-biblioteca (R019–R021), c2-biblioteca-lista y
// c2-biblioteca-convertir (R052), maqueta Biblioteca.
// Cierra el «entra a la Biblioteca» de KF-20: aquí salen las lecciones que
// Validar dejó «aprobada», con «aprobada por …» de textoDecision() (KF-05).
// «Convertir en regla» solo con 2 o más repeticiones. Abre «De lección a
// regla»: aquí se elige la forma; «Escribir la regla» la lleva a Cláusulas
// (KF-23), que escribe el texto y guarda.
import { useGetList } from "ra-core";
import { useMemo, useState } from "react";
import { Link } from "react-router";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import { fechaCorta } from "../expediente/lineaDeTiempo";
import { registrarEvento } from "../misc/eventos";
import { Cargando, NoCargo, Vacio } from "../misc/Estados";
import {
  FORMAS,
  SIN_FILTRO,
  enBiblioteca,
  filtrar,
  nombreForma,
  opciones,
  puedeConvertir,
  repeticiones,
  type Filtros,
  type Forma,
  type LeccionBiblioteca,
} from "./biblioteca";
import { textoDecision } from "./decision";
import { RUTA_CLAUSULAS, rutaClausulas } from "./reglas";

const TODAS = { pagination: { page: 1, perPage: 1000 } };
const capital = (s?: string | null) =>
  s ? s.charAt(0).toUpperCase() + s.slice(1) : "Sin categoría";

export const BibliotecaPage = () => {
  const aprobadas = useGetList<LeccionBiblioteca>("lecciones", {
    ...TODAS,
    filter: { estado: "aprobada" },
    sort: { field: "repeticiones", order: "DESC" },
  });
  const propuestas = useGetList("lecciones", {
    pagination: { page: 1, perPage: 1 },
    filter: { estado: "propuesta" },
    sort: { field: "id", order: "ASC" },
  });
  const [filtros, setFiltros] = useState<Filtros>(SIN_FILTRO);
  const [convirtiendo, setConvirtiendo] = useState<LeccionBiblioteca | null>(
    null,
  );

  const todas = useMemo(
    () => enBiblioteca(aprobadas.data ?? []),
    [aprobadas.data],
  );
  const vistas = filtrar(todas, filtros);
  const porAprobar = propuestas.total ?? 0;

  return (
    <div className="flex flex-col gap-4 py-2 max-w-3xl">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl font-semibold">Biblioteca</h1>
        <p className="text-muted-foreground">
          Lecciones aprobadas. Las más repetidas, arriba.
        </p>
        <Link
          to="/lecciones/validar"
          className="inline-flex min-h-11 items-center self-start rounded-md bg-primary px-4 font-semibold text-primary-foreground no-underline"
        >
          Validar propuestas{porAprobar ? ` (${porAprobar})` : ""}
        </Link>
        <Link
          to={RUTA_CLAUSULAS}
          className="inline-flex min-h-11 items-center self-start text-sm font-semibold"
        >
          Cláusulas y reglas guardadas
        </Link>
      </div>

      <div className="flex flex-wrap gap-3">
        <Filtro
          nombre="Categoría"
          valor={filtros.categoria}
          valores={opciones(todas, "categoria")}
          texto={capital}
          cambiar={(categoria) => setFiltros({ ...filtros, categoria })}
        />
        <Filtro
          nombre="Tipo de proyecto"
          valor={filtros.tipo_proyecto}
          valores={opciones(todas, "tipo_proyecto")}
          texto={(v) => v}
          cambiar={(tipo_proyecto) => setFiltros({ ...filtros, tipo_proyecto })}
        />
      </div>

      {aprobadas.isError ? (
        <NoCargo que="la Biblioteca" />
      ) : aprobadas.isPending ? (
        <Cargando />
      ) : !todas.length ? (
        <Vacio className="text-base">
          Todavía no hay lecciones aprobadas. Entran al aprobarlas en Validar.
        </Vacio>
      ) : !vistas.length ? (
        <Vacio className="text-base">
          No hay lecciones aprobadas con estos filtros.
        </Vacio>
      ) : null}

      <ul
        aria-label="Biblioteca"
        className="m-0 flex list-none flex-col gap-3 p-0"
      >
        {vistas.map((l) => (
          <li
            key={l.id}
            className="flex flex-col gap-2 rounded-xl border bg-card p-4"
          >
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <span
                className="rounded-full bg-primary px-2 py-0.5 font-bold text-primary-foreground"
                aria-label={`Repetida ${repeticiones(l)} ${
                  repeticiones(l) === 1 ? "vez" : "veces"
                }`}
              >
                x{repeticiones(l)}
              </span>
              <span className="font-semibold">{capital(l.categoria)}</span>
              <span className="text-muted-foreground break-words">
                {l.tipo_proyecto || "Sin tipo de proyecto"}
              </span>
            </div>
            <p className="font-medium break-words">{l.que_paso}</p>
            {l.regla_nueva ? (
              <p className="text-sm break-words">
                <span className="font-semibold">Regla: </span>
                {l.regla_nueva}
              </p>
            ) : null}
            <div className="flex flex-wrap items-center justify-between gap-2">
              <span className="text-sm text-muted-foreground">
                {textoDecision({
                  estado: l.estado,
                  decidido_por: l.decidido_por ?? null,
                })}{" "}
                · {fechaCorta(l.decidido_en)}
              </span>
              {puedeConvertir(l) ? (
                <Button
                  variant="outline"
                  className="min-h-11"
                  onClick={() => setConvirtiendo(l)}
                >
                  Convertir en regla
                </Button>
              ) : null}
            </div>
          </li>
        ))}
      </ul>

      {convirtiendo ? (
        <DeLeccionARegla
          leccion={convirtiendo}
          cerrar={() => setConvirtiendo(null)}
        />
      ) : null}
    </div>
  );
};

BibliotecaPage.path = "/lecciones";

const Filtro = ({
  nombre,
  valor,
  valores,
  texto,
  cambiar,
}: {
  nombre: string;
  valor: string;
  valores: string[];
  texto: (v: string) => string;
  cambiar: (v: string) => void;
}) => (
  <label className="flex min-w-0 flex-col gap-1 text-xs font-semibold text-muted-foreground">
    {nombre}
    <select
      className="min-h-11 max-w-full rounded-md border bg-background px-2 text-sm font-normal text-foreground"
      value={valor}
      onChange={(e) => cambiar(e.target.value)}
    >
      <option value="">Todas</option>
      {valores.map((v) => (
        <option key={v} value={v}>
          {texto(v)}
        </option>
      ))}
    </select>
  </label>
);

/** «De lección a regla»: primero se elige la forma. */
const DeLeccionARegla = ({
  leccion,
  cerrar,
}: {
  leccion: LeccionBiblioteca;
  cerrar: () => void;
}) => {
  const [forma, setForma] = useState<Forma | null>(null);
  const [falta, setFalta] = useState(false);
  const [elegida, setElegida] = useState<Forma | null>(null);

  const continuar = () => {
    if (!forma) return setFalta(true);
    registrarEvento("leccion.convertida", {
      leccion_id: leccion.id,
      forma,
      repeticiones: repeticiones(leccion),
    });
    setElegida(forma);
  };

  return (
    <Dialog open onOpenChange={(abierto) => !abierto && cerrar()}>
      <DialogContent className="max-h-[90dvh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>De lección a regla</DialogTitle>
          <DialogDescription className="break-words">
            x{repeticiones(leccion)} · {leccion.que_paso}
          </DialogDescription>
        </DialogHeader>

        {elegida ? (
          <p
            role="status"
            className="rounded-md bg-green-50 p-3 text-green-900 dark:bg-green-900/30 dark:text-green-100"
          >
            Se convertirá en {nombreForma(elegida)}. El texto se escribe en
            Cláusulas.
          </p>
        ) : (
          <fieldset
            role="radiogroup"
            aria-label="Tipo de regla"
            aria-invalid={falta || undefined}
            className="m-0 flex flex-col gap-2 border-0 p-0"
          >
            {FORMAS.map((f) => (
              <label
                key={f.forma}
                className="flex min-h-11 cursor-pointer items-start gap-3 rounded-md border p-3 has-[:checked]:border-primary"
              >
                <input
                  type="radio"
                  name="forma"
                  value={f.forma}
                  checked={forma === f.forma}
                  onChange={() => {
                    setForma(f.forma);
                    setFalta(false);
                  }}
                  className="mt-1 size-4"
                />
                <span className="flex flex-col">
                  <b className="text-sm">{f.nombre}</b>
                  <span className="text-xs text-muted-foreground">
                    {f.detalle}
                  </span>
                </span>
              </label>
            ))}
          </fieldset>
        )}
        {falta && !elegida ? (
          <p role="alert" className="text-sm text-destructive">
            Elige checklist, cláusula o plantilla.
          </p>
        ) : null}

        <DialogFooter>
          <Button variant="outline" className="min-h-11" onClick={cerrar}>
            Cerrar
          </Button>
          {!elegida ? (
            <Button className="min-h-11" onClick={continuar}>
              Continuar
            </Button>
          ) : (
            <Button asChild className="min-h-11">
              <Link to={rutaClausulas(leccion.id, elegida)}>
                Escribir la regla
              </Link>
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
