import { cn } from "@/lib/utils";
import { Link, useLocation } from "react-router";

import { SECCIONES, SECCIONES_BARRA, seccionDeRuta } from "./secciones";

// Yunque 8 · KF-06 · c2-cel-barra: a 1440 px el menú lateral trae las mismas
// 11 entradas que la barra del celular y la pantalla Más.
export const MenuLateral = () => {
  const { pathname } = useLocation();
  const activa = seccionDeRuta(pathname)?.nombre;
  const ultimaDeBarra = SECCIONES_BARRA.length - 1;

  return (
    <nav
      aria-label="Secciones"
      className="w-56 shrink-0 border-r min-h-[calc(100vh-3rem)] py-4 px-2"
    >
      <ul className="list-none m-0 p-0 flex flex-col gap-0.5">
        {SECCIONES.map((s, i) => (
          <li
            key={s.ruta}
            className={cn(i === ultimaDeBarra && "mb-2 pb-2 border-b")}
          >
            <Link
              to={s.ruta}
              aria-current={activa === s.nombre ? "page" : undefined}
              className={cn(
                "block rounded-md px-3 py-2 text-sm no-underline",
                activa === s.nombre
                  ? "bg-secondary text-secondary-foreground font-semibold"
                  : "text-muted-foreground hover:bg-secondary/60",
              )}
            >
              {s.nombre}
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
};
