// Kaizen Files · KF-07 · c1-r-importar y c2-clientes-lista (R043–R045, R047),
// maqueta Clientes. Reemplaza la pantalla provisional de KF-06 en /clientes.
// Tocar un cliente abre su expediente (companies/:id/show de Atomic CRM).
import { useMemo, useState } from "react";
import {
  useCreatePath,
  useDataProvider,
  useGetIdentity,
  useGetList,
} from "ra-core";
import { Link } from "react-router";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { createEachRow } from "../dataImport/createEachRow";
import { registrarEvento } from "../misc/eventos";
import { EstadoDatos } from "../misc/Estados";
import type { Company, Contact, Deal } from "../types";
import {
  armarFilas,
  estadoFila,
  FILTROS,
  filtrarFilas,
  type Filtro,
} from "./filasClientes";
import {
  ErrorCsvClientes,
  leerClientesCsv,
  textoResultado,
  type FilaCliente,
} from "./leerClientesCsv";

const TODAS = {
  pagination: { page: 1, perPage: 10000 },
  sort: { field: "id", order: "ASC" as const },
};

export const ClientesPage = () => {
  const companies = useGetList<Company>("companies", TODAS);
  const deals = useGetList<Deal>("deals", TODAS);
  const contacts = useGetList<Contact>("contacts", TODAS);
  const createPath = useCreatePath();
  const [texto, setTexto] = useState("");
  const [filtro, setFiltro] = useState<Filtro>("clientes");
  const [importando, setImportando] = useState(false);

  const filas = useMemo(
    () =>
      armarFilas(companies.data ?? [], deals.data ?? [], contacts.data ?? []),
    [companies.data, deals.data, contacts.data],
  );
  const visibles = filtrarFilas(filas, texto, filtro);
  const cargando = companies.isPending || deals.isPending || contacts.isPending;
  const fallo = companies.isError || deals.isError || contacts.isError;

  const refrescar = () => {
    companies.refetch();
    contacts.refetch();
  };

  return (
    <div className="flex flex-col gap-4 py-2">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-2xl font-semibold">Clientes y proyectos</h1>
          <p className="text-sm text-muted-foreground">
            Todos tus clientes, sus proyectos y cómo van
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          {/* KF-24: el proyecto nuevo arranca en el Punto de Partida. */}
          <Button asChild className="min-h-11 sm:min-h-9">
            <Link to="/punto-partida">Nuevo proyecto</Link>
          </Button>
          <Button
            variant="outline"
            className="min-h-11 sm:min-h-9"
            onClick={() => setImportando(true)}
          >
            Importar CSV
          </Button>
        </div>
      </div>

      <div className="flex flex-col gap-3 md:flex-row md:items-end">
        <div className="flex flex-col gap-1.5 md:w-90">
          <Label htmlFor="clientes-buscar">Buscar</Label>
          <Input
            id="clientes-buscar"
            type="search"
            placeholder="Cliente, proyecto o contacto"
            className="min-h-11"
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
          />
        </div>
        <div role="group" aria-label="Filtro" className="flex flex-wrap gap-1">
          {FILTROS.map((f) => (
            <Button
              key={f.id}
              size="sm"
              variant={filtro === f.id ? "secondary" : "outline"}
              aria-pressed={filtro === f.id}
              className="min-h-11 sm:min-h-9"
              onClick={() => setFiltro(f.id)}
            >
              {f.nombre}
            </Button>
          ))}
        </div>
      </div>

      {cargando || fallo ? null : (
        <p
          role="status"
          aria-label="Total"
          className="text-sm text-muted-foreground"
        >
          {visibles.length} {visibles.length === 1 ? "cliente" : "clientes"}
        </p>
      )}

      <section className="rounded-xl border bg-card px-4">
        <EstadoDatos
          consultas={[companies, deals, contacts]}
          que="los clientes"
          hayDatos={visibles.length > 0}
          vacio={
            filas.length
              ? "Ningún cliente coincide con la búsqueda."
              : "Todavía no hay clientes. Toque «Importar CSV» para traerlos."
          }
        >
          {null}
        </EstadoDatos>
        <ul aria-label="Clientes" className="m-0 list-none p-0">
          {visibles.map((f) => (
            <li
              key={f.id}
              className="flex flex-col gap-1 border-b py-3 last:border-b-0 md:flex-row md:items-start md:gap-4"
            >
              <Link
                to={createPath({
                  resource: "companies",
                  id: f.id,
                  type: "show",
                })}
                className="min-h-11 font-semibold md:w-72 md:shrink-0"
              >
                {f.nombre}
              </Link>
              {f.proyectos.length > 0 ? (
                <ul
                  aria-label={`Proyectos de ${f.nombre}`}
                  className="m-0 flex flex-1 list-none flex-wrap gap-x-3 p-0 text-sm text-muted-foreground"
                >
                  {f.proyectos.map((p, i) => (
                    <li key={i} className={p.cerrado ? "line-through" : ""}>
                      {p.nombre}
                    </li>
                  ))}
                </ul>
              ) : (
                <span className="flex-1" />
              )}
              <span className="text-sm md:w-32 md:text-right">
                {estadoFila(f)}
              </span>
            </li>
          ))}
        </ul>
      </section>

      <ImportarClientes
        abierto={importando}
        existentes={filas.map((f) => f.nombre)}
        onCerrar={() => setImportando(false)}
        onImportado={refrescar}
      />
    </div>
  );
};
ClientesPage.path = "/clientes";

type Resultado =
  | { tipo: "listo"; texto: string }
  | { tipo: "error"; texto: string }
  | null;

const ImportarClientes = ({
  abierto,
  existentes,
  onCerrar,
  onImportado,
}: {
  abierto: boolean;
  existentes: string[];
  onCerrar: () => void;
  onImportado: () => void;
}) => {
  const dataProvider = useDataProvider();
  const { identity } = useGetIdentity();
  const [archivo, setArchivo] = useState<File | null>(null);
  const [trabajando, setTrabajando] = useState(false);
  const [resultado, setResultado] = useState<Resultado>(null);

  const cerrar = () => {
    setArchivo(null);
    setResultado(null);
    onCerrar();
  };

  const importar = async () => {
    if (!archivo) return;
    setTrabajando(true);
    try {
      const { nuevos, repetidos } = leerClientesCsv(
        await archivo.text(),
        existentes,
      );
      const creados = await createEachRow(
        nuevos.map((fila) => crearCliente(fila)),
      );
      registrarEvento("cliente.importado", {
        archivo: archivo.name,
        nuevos: creados,
        repetidos,
        fallidos: nuevos.length - creados,
      });
      setResultado({
        tipo: "listo",
        texto: textoResultado(creados, repetidos),
      });
      onImportado();
    } catch (e) {
      setResultado({
        tipo: "error",
        texto:
          e instanceof ErrorCsvClientes
            ? e.message
            : "No se pudo leer el archivo",
      });
    } finally {
      setTrabajando(false);
    }
  };

  const crearCliente = async (fila: FilaCliente) => {
    const hoy = new Date().toISOString();
    const { data: company } = await dataProvider.create<Company>("companies", {
      data: {
        name: fila.nombre,
        tax_identifier: fila.ruc,
        phone_number: fila.telefono,
        address: fila.direccion,
        city: fila.ciudad,
        website: fila.sitio,
        sales_id: identity?.id,
        created_at: hoy,
      } as Partial<Company>,
    });
    if (fila.contacto || fila.correo) {
      const [first_name, ...resto] = (fila.contacto ?? "").split(" ");
      await dataProvider.create("contacts", {
        data: {
          first_name,
          last_name: resto.join(" "),
          email_jsonb: fila.correo
            ? [{ email: fila.correo, type: "Work" }]
            : [],
          phone_jsonb: [],
          first_seen: hoy,
          last_seen: hoy,
          tags: [],
          company_id: company.id,
          sales_id: identity?.id,
        },
      });
    }
    return company;
  };

  return (
    <Dialog open={abierto} onOpenChange={(o) => (o ? null : cerrar())}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Importar clientes</DialogTitle>
        </DialogHeader>
        <p className="text-sm text-muted-foreground">
          CSV de Excel con la columna Nombre. También lee RUC, Teléfono,
          Dirección, Ciudad, Sitio web, Contacto y Correo. Los repetidos no se
          duplican.
        </p>
        {resultado === null ? (
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="clientes-csv">Archivo CSV</Label>
            <Input
              id="clientes-csv"
              type="file"
              accept=".csv,text/csv"
              onChange={(e) => setArchivo(e.target.files?.[0] ?? null)}
            />
          </div>
        ) : resultado.tipo === "listo" ? (
          <p role="status" className="font-medium">
            {resultado.texto}
          </p>
        ) : (
          <Alert variant="destructive">
            <AlertDescription>{resultado.texto}</AlertDescription>
          </Alert>
        )}
        <DialogFooter>
          {resultado === null ? (
            <Button onClick={importar} disabled={!archivo || trabajando}>
              Importar
            </Button>
          ) : null}
          <Button variant="outline" onClick={cerrar} disabled={trabajando}>
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
