// KF-05 · c1-r-usuarios (R031). Texto de quién decidió una lección.
// La pantalla Lecciones lo usa: «aprobada por Caro», «descartada por Cesar».
export const textoDecision = ({
  estado,
  decidido_por,
}: {
  estado: string;
  decidido_por: string | null;
}): string => {
  if (estado === "propuesta") return "por aprobar";
  return decidido_por ? `${estado} por ${decidido_por}` : estado;
};
