// c2-marca: la palabra «Kaizen Files · DPB» del mockup Main.dc.html
// (Space Grotesk 700, #1D2125; «· DPB» en #5B6168). Es texto, no imagen:
// así se lee igual en PC y celular y no depende de la config guardada.
import { cn } from "@/lib/utils";

export const NOMBRE_APP = "Kaizen Files";

export const Marca = ({
  className,
  sobreOscuro = false,
}: {
  className?: string;
  sobreOscuro?: boolean;
}) => (
  <h1
    className={cn(
      "text-xl font-bold tracking-tight whitespace-nowrap",
      sobreOscuro ? "text-white" : "text-[#1D2125] dark:text-white",
      className,
    )}
    style={{
      fontFamily: "'Space Grotesk', ui-sans-serif, system-ui, sans-serif",
    }}
  >
    {NOMBRE_APP}{" "}
    <span
      className={
        sobreOscuro ? "text-zinc-400" : "text-[#5B6168] dark:text-zinc-400"
      }
    >
      · DPB
    </span>
  </h1>
);
