import { useGetIdentity } from "ra-core";
import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";

/** KF-05 · c2-usuario (R046): arriba de cada pantalla, quién está dentro. */
export const QuienSoy = ({ className = "" }: { className?: string }) => {
  const { identity } = useGetIdentity();
  if (!identity?.fullName) return null;
  return (
    <div
      role="group"
      aria-label="Quién soy"
      className={`flex items-center gap-2 text-sm font-medium ${className}`}
    >
      {identity.avatar ? (
        <img
          src={identity.avatar}
          alt=""
          className="size-6 rounded-full object-cover"
        />
      ) : null}
      <span>{identity.fullName}</span>
    </div>
  );
};

// En el celular algunas pantallas traen su propio encabezado fijo
// (MobileHeader). Ahí «quién soy» va dentro de él; si no hay, va en la franja
// de arriba del MobileLayout. Así siempre se ve una sola vez y sin tapar nada.
const EncabezadoMovil = createContext<(hay: boolean) => void>(() => {});

export const QuienSoyMovil = ({ children }: { children: ReactNode }) => {
  const [hayEncabezado, setHayEncabezado] = useState(false);
  return (
    <EncabezadoMovil.Provider value={setHayEncabezado}>
      {hayEncabezado ? null : (
        <div className="flex justify-end px-4 pt-3">
          <QuienSoy />
        </div>
      )}
      {children}
    </EncabezadoMovil.Provider>
  );
};

export const QuienSoyEnEncabezado = () => {
  const avisar = useContext(EncabezadoMovil);
  useEffect(() => {
    avisar(true);
    return () => avisar(false);
  }, [avisar]);
  return <QuienSoy className="ml-auto mr-2" />;
};
