// Kaizen Files · KF-23 · c2-regla-elegir y c2-regla-clausula (R053),
// maqueta Clausulas.
// Llega desde «De lección a regla» (KF-22) con la forma ya elegida en la
// ruta: aquí no se vuelve a preguntar ni se registra leccion.convertida.
// El texto propuesto se edita y Guardar escribe en `reglas` el texto editado,
// con su lección y su tipo de proyecto. Registra regla.creada una vez.
import { useCreate, useGetList, useGetOne } from "ra-core";
import { useEffect, useState } from "react";
import { Link, useNavigate, useParams, useSearchParams } from "react-router";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

import { fechaCorta } from "../expediente/lineaDeTiempo";
import { registrarEvento } from "../misc/eventos";
import { Cargando, NoCargo, Vacio } from "../misc/Estados";
import {
  nombreForma,
  repeticiones,
  type LeccionBiblioteca,
} from "./biblioteca";
import {
  RUTA_CLAUSULAS,
  filaRegla,
  formaDeRuta,
  textoPropuesto,
  type Regla,
} from "./reglas";

export const ClausulasPage = () => {
  const { id } = useParams();
  const [busqueda] = useSearchParams();
  const forma = formaDeRuta(busqueda.get("forma"));
  const guardada = busqueda.get("guardada");

  return (
    <div className="flex flex-col gap-4 py-2 max-w-3xl">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl font-semibold">Cláusulas</h1>
        <p className="text-muted-foreground">
          Reglas que salen de las lecciones repetidas.
        </p>
        <Link
          to="/lecciones"
          className="inline-flex min-h-11 items-center self-start text-sm font-semibold"
        >
          ← Biblioteca
        </Link>
      </div>

      {guardada ? (
        <p
          role="status"
          className="rounded-md bg-green-50 p-3 text-green-900 dark:bg-green-900/30 dark:text-green-100"
        >
          Regla guardada. Queda lista para el Punto de Partida.
        </p>
      ) : null}

      {id ? (
        forma ? (
          <NuevaRegla leccionId={id} forma={forma} />
        ) : (
          <p role="alert" className="text-sm text-destructive">
            Falta la forma de la regla. Vuelve a la Biblioteca y usa «Convertir
            en regla».
          </p>
        )
      ) : null}

      <ReglasGuardadas />
    </div>
  );
};

ClausulasPage.path = RUTA_CLAUSULAS;
ClausulasPage.pathNueva = `${RUTA_CLAUSULAS}/:id`;

const NuevaRegla = ({
  leccionId,
  forma,
}: {
  leccionId: string;
  forma: NonNullable<ReturnType<typeof formaDeRuta>>;
}) => {
  const navigate = useNavigate();
  const { data: leccion, isPending } = useGetOne<LeccionBiblioteca>(
    "lecciones",
    { id: leccionId },
  );
  const [texto, setTexto] = useState("");
  const [vacio, setVacio] = useState(false);
  const [create, { isPending: guardando }] = useCreate<Regla>();

  useEffect(() => {
    if (leccion) setTexto(textoPropuesto(leccion, forma));
  }, [leccion, forma]);

  if (isPending) return <Cargando />;
  if (!leccion)
    return (
      <p role="alert" className="text-sm text-destructive">
        No se encontró la lección.
      </p>
    );

  const guardar = () => {
    if (guardando) return;
    if (!texto.trim()) return setVacio(true);
    const fila = filaRegla(leccion, forma, texto);
    create(
      "reglas",
      { data: fila },
      {
        onSuccess: (regla) => {
          registrarEvento("regla.creada", {
            regla_id: regla.id,
            leccion_id: fila.leccion_id,
            forma: fila.forma,
            tipo_proyecto: fila.tipo_proyecto,
          });
          navigate(`${RUTA_CLAUSULAS}?guardada=${regla.id}`, {
            replace: true,
          });
        },
      },
    );
  };

  return (
    <section
      aria-label="Nueva regla"
      className="flex flex-col gap-3 rounded-xl border bg-card p-4"
    >
      <div className="flex flex-wrap items-center gap-2 text-xs">
        <span className="rounded-full bg-primary px-2 py-0.5 font-bold text-primary-foreground">
          x{repeticiones(leccion)}
        </span>
        <span className="text-muted-foreground break-words">
          {leccion.tipo_proyecto || "Sin tipo de proyecto"}
        </span>
      </div>
      <p className="font-medium break-words">{leccion.que_paso}</p>
      <p className="text-sm">
        <span className="font-semibold">Forma: </span>
        {nombreForma(forma)}
      </p>
      <label className="flex flex-col gap-1 text-sm font-semibold">
        Texto de la regla
        <Textarea
          value={texto}
          onChange={(e) => {
            setTexto(e.target.value);
            setVacio(false);
          }}
          rows={4}
          className="font-normal"
          aria-invalid={vacio || undefined}
        />
      </label>
      {vacio ? (
        <p role="alert" className="text-sm text-destructive">
          Escribe el texto de la regla.
        </p>
      ) : null}
      <Button
        className="min-h-11 self-start"
        onClick={guardar}
        disabled={guardando}
      >
        Guardar
      </Button>
    </section>
  );
};

const ReglasGuardadas = () => {
  const {
    data: reglas = [],
    isPending,
    isError,
  } = useGetList<Regla>("reglas", {
    pagination: { page: 1, perPage: 1000 },
    sort: { field: "id", order: "DESC" },
  });
  const { data: lecciones = [] } = useGetList<LeccionBiblioteca>(
    "lecciones",
    {
      pagination: { page: 1, perPage: 1000 },
      filter: { estado: "aprobada" },
    },
    { enabled: reglas.length > 0 },
  );
  const deLeccion = (id: Regla["leccion_id"]) =>
    lecciones.find((l) => String(l.id) === String(id));

  return (
    <section className="flex flex-col gap-2">
      <h2 className="text-lg font-semibold">Reglas guardadas</h2>
      {isError ? (
        <NoCargo que="las reglas guardadas" />
      ) : isPending ? (
        <Cargando />
      ) : !reglas.length ? (
        <Vacio className="text-base">
          Todavía no hay reglas. Se crean con «Convertir en regla» en la
          Biblioteca.
        </Vacio>
      ) : null}
      <ul
        aria-label="Reglas guardadas"
        className="m-0 flex list-none flex-col gap-3 p-0"
      >
        {reglas.map((r) => {
          const origen = deLeccion(r.leccion_id);
          return (
            <li
              key={r.id}
              className="flex flex-col gap-1 rounded-xl border bg-card p-4"
            >
              <div className="flex flex-wrap items-center gap-2 text-xs">
                <span className="font-semibold">{nombreForma(r.forma)}</span>
                <span className="text-muted-foreground break-words">
                  {r.tipo_proyecto || "Sin tipo de proyecto"}
                </span>
              </div>
              <p className="break-words whitespace-pre-line">{r.texto}</p>
              <p className="text-xs text-muted-foreground break-words">
                De la lección #{r.leccion_id ?? "—"}
                {origen ? ` · ${origen.que_paso}` : ""}
                {r.creado_en ? ` · ${fechaCorta(r.creado_en)}` : ""}
              </p>
            </li>
          );
        })}
      </ul>
    </section>
  );
};
