/** Base de la app como URL absoluta, sin ruta interna (#/…) ni consulta. */
export const urlDeRegreso = (base: string, href: string) => {
  const url = new URL(base, href);
  url.hash = "";
  url.search = "";
  return url.toString();
};

/** Adónde vuelven el correo y Google: la base publicada (/kaizen-files/). */
export const regresoDeLaApp = () =>
  urlDeRegreso(import.meta.env.BASE_URL, window.location.href);
