// Copiado del prototipo gris: prototipo/src/lectores.mjs:133-151 (leerClientesCsv)
// y prototipo/src/comun.mjs:11-19 (norm). El CSV lo parte papaparse, el mismo
// que usa el importador de Atomic CRM (misc/usePapaParse.tsx), que detecta
// solo el separador («,» o «;» de Excel en español) y respeta las comillas.
import * as Papa from "papaparse";

/** Quita acentos, pasa a minúsculas y junta espacios, para comparar nombres. */
export function norm(s: unknown): string {
  return String(s ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

/** Columnas de DPB que se leen. Solo Nombre es obligatoria. */
export type FilaCliente = {
  nombre: string;
  ruc?: string;
  telefono?: string;
  direccion?: string;
  ciudad?: string;
  sitio?: string;
  contacto?: string;
  correo?: string;
};

const COLUMNAS: Record<string, keyof FilaCliente> = {
  nombre: "nombre",
  ruc: "ruc",
  telefono: "telefono",
  direccion: "direccion",
  ciudad: "ciudad",
  "sitio web": "sitio",
  contacto: "contacto",
  correo: "correo",
};

export class ErrorCsvClientes extends Error {}

export const FALTA_NOMBRE = "falta la columna Nombre";

/**
 * Lee el CSV de clientes. No duplica repetidos dentro del CSV ni contra los
 * `existentes` (nombres ya en la base). Sin la columna Nombre, lanza.
 */
export function leerClientesCsv(
  texto: string,
  existentes: string[] = [],
): { nuevos: FilaCliente[]; repetidos: number } {
  const { data, meta } = Papa.parse<Record<string, string>>(
    texto.replace(/^\uFEFF/, ""),
    { header: true, skipEmptyLines: "greedy", transformHeader: norm },
  );
  if (!(meta.fields ?? []).includes("nombre")) {
    throw new ErrorCsvClientes(`CSV de clientes: ${FALTA_NOMBRE}`);
  }
  const vistos = new Set(existentes.map(norm));
  const nuevos: FilaCliente[] = [];
  let repetidos = 0;
  for (const crudo of data) {
    const fila = {} as FilaCliente;
    for (const [titulo, campo] of Object.entries(COLUMNAS)) {
      const valor = (crudo[titulo] ?? "").trim();
      if (valor) fila[campo] = valor;
    }
    if (!fila.nombre) continue;
    const clave = norm(fila.nombre);
    if (vistos.has(clave)) {
      repetidos++;
      continue;
    }
    vistos.add(clave);
    nuevos.push(fila);
  }
  return { nuevos, repetidos };
}

/** «2 nuevos, 1 repetido». */
export const textoResultado = (nuevos: number, repetidos: number) =>
  `${nuevos} ${nuevos === 1 ? "nuevo" : "nuevos"}, ${repetidos} ${
    repetidos === 1 ? "repetido" : "repetidos"
  }`;
