// Kaizen Files · KF-28 · c2-minuta-enviar (R050, P1 opción a). Va en la
// pantalla Minuta y en la pestaña Minutas del expediente (sin pestañas nuevas).
// - «borrador» (la cola de KF-27): no hay Enviar y dice por qué.
// - «ordenada»: Enviar abre el correo ya armado (mailto) para los contactos del
//   cliente y deja la minuta «enviada» con enviada_en. decidido_por lo pone el
//   disparador kf_poner_autor (20261111130000_kf_usuarios.sql:70) al cambiar el
//   estado; la demo lo imita.
// - «enviada»: dice cuándo y quién.
import { useQueryClient } from "@tanstack/react-query";
import { Send } from "lucide-react";
import { useGetList, useGetOne, useUpdate, type Identifier } from "ra-core";
import { useState } from "react";

import { fechaCorta, type Pendiente } from "../expediente/lineaDeTiempo";
import { registrarEvento } from "../misc/eventos";
import type { Company, Contact } from "../types";
import {
  armarCorreo,
  destinatarios,
  listaAcuerdos,
  mailto,
  MINUTA_EN_COLA_NO_ENVIA,
  SIN_CORREO_CLIENTE,
} from "./correoMinuta";

export type MinutaParaEnviar = {
  id: Identifier;
  cliente_id?: Identifier | null;
  punto_partida_id?: Identifier | null;
  acuerdos?: string | null;
  estado?: "borrador" | "ordenada" | "enviada";
  creado_en?: string | null;
  enviada_en?: string | null;
  decidido_por?: string | null;
};

const TODO = { page: 1, perPage: 1000 };

export const EnviarMinuta = ({ minuta }: { minuta: MinutaParaEnviar }) => {
  const estado = minuta.estado ?? "borrador";
  if (estado === "borrador")
    return (
      <p className="m-0 text-sm text-muted-foreground">
        {MINUTA_EN_COLA_NO_ENVIA}
      </p>
    );
  if (estado === "enviada")
    return (
      <p className="m-0 text-sm text-muted-foreground">
        Enviada el {fechaCorta(minuta.enviada_en)} por{" "}
        {minuta.decidido_por || "sin autor"}
      </p>
    );
  return <BotonEnviar minuta={minuta} />;
};

const BotonEnviar = ({ minuta }: { minuta: MinutaParaEnviar }) => {
  const clienteId = minuta.cliente_id;
  const [actualizar, { isPending }] = useUpdate();
  const queryClient = useQueryClient();
  const [aviso, setAviso] = useState<string | null>(null);

  const cliente = useGetOne<Company>(
    "companies",
    { id: clienteId! },
    { enabled: clienteId != null },
  );
  const proyecto = useGetOne<{ id: Identifier; nombre: string }>(
    "punto_partida",
    { id: minuta.punto_partida_id! },
    { enabled: minuta.punto_partida_id != null },
  );
  const contactos = useGetList<Contact>(
    "contacts",
    {
      filter: { company_id: clienteId },
      pagination: TODO,
      sort: { field: "id", order: "ASC" },
    },
    { enabled: clienteId != null },
  );
  const pendientes = useGetList<Pendiente>("pendientes", {
    filter: { minuta_id: minuta.id },
    pagination: TODO,
    sort: { field: "id", order: "ASC" },
  });

  if (cliente.isPending || contactos.isPending || pendientes.isPending)
    return null;

  const para = destinatarios(contactos.data);
  if (!para.length)
    return <p className="m-0 text-sm text-destructive">{SIN_CORREO_CLIENTE}</p>;

  const lista = pendientes.data ?? [];
  const nombre = proyecto.data?.nombre || cliente.data?.name || "Cliente";
  const correo = armarCorreo({
    proyecto: nombre,
    fecha: minuta.creado_en,
    acuerdos: minuta.acuerdos,
    pendientes: lista,
  });

  const marcarEnviada = () => {
    setAviso(null);
    actualizar(
      "minutas",
      {
        id: minuta.id,
        data: { estado: "enviada", enviada_en: new Date().toISOString() },
        previousData: minuta,
      },
      {
        onSuccess: () => {
          registrarEvento("minuta.enviada", {
            minuta_id: minuta.id,
            cliente_id: clienteId,
            destinatarios: para.length,
            acuerdos: listaAcuerdos(minuta.acuerdos).length,
            pendientes: lista.length,
          });
          queryClient.invalidateQueries({ queryKey: ["kf-expediente"] });
        },
        onError: () =>
          setAviso("No se pudo marcar como enviada. Prueba otra vez."),
      },
    );
  };

  return (
    <span className="flex flex-col gap-1">
      <span className="text-sm text-muted-foreground break-words">
        Para: {para.join(", ")}
      </span>
      <a
        href={mailto(para, correo.asunto, correo.cuerpo)}
        onClick={marcarEnviada}
        aria-disabled={isPending || undefined}
        className="inline-flex items-center justify-center gap-2 self-start min-h-11 px-4 rounded-md bg-primary text-primary-foreground text-sm font-medium"
      >
        <Send className="size-4" aria-hidden />
        Enviar
      </a>
      {aviso ? (
        <span role="alert" className="text-sm text-destructive">
          {aviso}
        </span>
      ) : null}
    </span>
  );
};
