// Yunque 8 · KF-30 · c2-estados (R060): cada pantalla dice en lenguaje claro
// cuando está leyendo, cuando no hay nada y cuando algo falló.
// data-estado marca cada aviso para la prueba e2e de las 15 pantallas.
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

type Props = { children?: ReactNode; className?: string };

/**
 * «Cargando…» mientras llegan los datos. aria-live y no role="status": así no
 * se confunde con los avisos de cada pantalla (Regla guardada, En cola…).
 */
export const Cargando = ({ children = "Cargando…", className }: Props) => (
  <p
    aria-live="polite"
    data-estado="cargando"
    className={cn("m-0 py-2 text-sm text-muted-foreground", className)}
  >
    {children}
  </p>
);

/** Lo que se ve cuando no hay nada que mostrar (contenido fijo, sin rol). */
export const Vacio = ({ children, className }: Props) => (
  <p
    data-estado="vacio"
    className={cn("m-0 py-2 text-sm text-muted-foreground", className)}
  >
    {children}
  </p>
);

/**
 * El aviso cuando una lectura falla. `que` dice qué no se pudo leer
 * («las lecciones»). Nunca muestra el mensaje técnico del error.
 */
export const NoCargo = ({
  que,
  className,
}: {
  que: string;
  className?: string;
}) => (
  <p
    role="alert"
    data-estado="error"
    className={cn("m-0 py-2 text-sm text-destructive", className)}
  >
    No se pudo cargar {que}. Revise la conexión y vuelva a intentar.
  </p>
);

type Consulta = { isPending: boolean; isError: boolean };

/**
 * Los tres estados de una lectura: si alguna falló, el aviso de error; si
 * alguna sigue leyendo, «Cargando…»; si no hay datos, el texto de vacío. Si
 * hay datos, lo de adentro.
 */
export const EstadoDatos = ({
  consultas,
  que,
  vacio,
  hayDatos,
  cargando,
  children,
}: {
  consultas: Consulta[];
  que: string;
  vacio: ReactNode;
  hayDatos: boolean;
  cargando?: ReactNode;
  children: ReactNode;
}) => {
  if (consultas.some((q) => q.isError)) return <NoCargo que={que} />;
  if (consultas.some((q) => q.isPending))
    return <Cargando>{cargando}</Cargando>;
  if (!hayDatos) return <Vacio>{vacio}</Vacio>;
  return <>{children}</>;
};
