// Kaizen Files · KF-20 · c1-r-validar (R016–R018), c2-validar-campos,
// c2-validar-aprobar, c2-validar-editar y c2-validar-descartar (R051),
// maqueta Validar. Cierra en pantalla el C1 pendiente de KF-05 (R031):
// «aprobada por Caro» sale de textoDecision() con el decidido_por que pone
// la base.
// Aprobar, Editar y Descartar tienen Deshacer. Descartar no borra: la lección
// queda «descartada» con sus filas de evidencias, que es lo que lee el
// detector (pc/detector.mjs) para no volver a proponerla.
import { useDataProvider, useGetList, type Identifier } from "ra-core";
import { useEffect, useMemo, useRef, useState } from "react";
import { Link, useParams } from "react-router";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Textarea } from "@/components/ui/textarea";

import { dinero, fechaCorta } from "../expediente/lineaDeTiempo";
import { registrarEvento } from "../misc/eventos";
import { Cargando, NoCargo, Vacio } from "../misc/Estados";
import { textoDecision } from "./decision";
import {
  cambiosAprobar,
  cambiosDescartar,
  cambiosDeshacer,
  cambiosEditar,
  type Leccion,
} from "./validar";

type Evidencia = {
  id: Identifier;
  leccion_id: Identifier;
  tipo: string;
  correo_id?: Identifier | null;
  minuta_id?: Identifier | null;
  factura_id?: Identifier | null;
  enlace?: string | null;
};
type Correo = {
  id: Identifier;
  de?: string | null;
  asunto?: string | null;
  fecha?: string | null;
};

type Accion = "aprobada" | "editada" | "descartada";
type Hecho = {
  accion: Accion;
  antes: Leccion;
  cambios: Record<string, unknown>;
  despues: Leccion;
};

const TODAS = { pagination: { page: 1, perPage: 1000 } };
const capital = (s?: string | null) =>
  s ? s.charAt(0).toUpperCase() + s.slice(1) : "Sin dato";

export const ValidarPage = () => {
  const dp = useDataProvider();
  const { id: idRuta } = useParams();
  const propuestas = useGetList<Leccion>("lecciones", {
    ...TODAS,
    filter: { estado: "propuesta" },
    sort: { field: "id", order: "ASC" },
  });

  // La lección en pantalla se fija al abrir: no salta al decidirla.
  const [actual, setActual] = useState<Leccion | null>(null);
  const [hecho, setHecho] = useState<Hecho | null>(null);
  const [editando, setEditando] = useState(false);
  const [regla, setRegla] = useState("");
  const [trabajando, setTrabajando] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // En el celular la barra inferior tapa lo último: el aviso sube a la vista.
  const avisoRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (hecho) avisoRef.current?.scrollIntoView({ block: "nearest" });
  }, [hecho]);

  useEffect(() => {
    if (actual || !propuestas.data) return;
    const l = idRuta
      ? propuestas.data.find((p) => String(p.id) === idRuta)
      : propuestas.data[0];
    if (l) {
      setActual(l);
      setRegla(l.regla_nueva ?? "");
    }
  }, [actual, idRuta, propuestas.data]);

  const evidencias = useGetList<Evidencia>(
    "evidencias",
    {
      ...TODAS,
      filter: { leccion_id: actual?.id },
      sort: { field: "id", order: "ASC" },
    },
    { enabled: actual != null },
  );
  const idsCorreo = useMemo(
    () =>
      (evidencias.data ?? [])
        .map((e) => e.correo_id)
        .filter((x): x is Identifier => x != null),
    [evidencias.data],
  );
  const correos = useGetList<Correo>(
    "correos",
    {
      ...TODAS,
      filter: { "id@in": `(${idsCorreo.join(",")})` },
      sort: { field: "id", order: "ASC" },
    },
    { enabled: idsCorreo.length > 0 },
  );

  const total = propuestas.total ?? propuestas.data?.length ?? 0;
  const posicion =
    actual && propuestas.data
      ? propuestas.data.findIndex((p) => p.id === actual.id) + 1
      : 0;

  const guardar = async (
    accion: Accion,
    cambios: Record<string, unknown>,
    deshacer = false,
  ) => {
    if (!actual) return;
    setTrabajando(true);
    setError(null);
    try {
      const { data } = await dp.update<Leccion>("lecciones", {
        id: actual.id,
        data: cambios,
        previousData: actual,
      });
      const despues = { ...actual, ...data } as Leccion;
      const tipo = `leccion.${accion}`;
      if (!deshacer && "regla_nueva" in cambios && accion === "aprobada")
        registrarEvento("leccion.editada", {
          leccion_id: actual.id,
          campos: ["regla_nueva"],
        });
      registrarEvento(tipo, {
        leccion_id: actual.id,
        ...(deshacer ? { deshecho: true } : {}),
        ...(accion === "editada" ? { campos: Object.keys(cambios) } : {}),
      });
      setHecho(deshacer ? null : { accion, antes: actual, cambios, despues });
      setActual(despues);
      setRegla(despues.regla_nueva ?? "");
      setEditando(false);
      propuestas.refetch();
    } catch (e) {
      setError(`No se pudo guardar: ${(e as Error).message}`);
    } finally {
      setTrabajando(false);
    }
  };

  const aprobar = () =>
    guardar(
      "aprobada",
      cambiosAprobar(actual!, { regla_nueva: regla }, new Date()),
    );
  const descartar = () => guardar("descartada", cambiosDescartar(new Date()));
  const guardarEdicion = () => {
    const c = cambiosEditar(actual!, { regla_nueva: regla });
    if (!Object.keys(c).length) return setEditando(false);
    return guardar("editada", c);
  };
  const deshacer = () =>
    hecho &&
    guardar(hecho.accion, cambiosDeshacer(hecho.antes, hecho.cambios), true);

  const siguiente = () => {
    const otra = (propuestas.data ?? []).find((p) => p.id !== actual?.id);
    setHecho(null);
    setEditando(false);
    setActual(otra ?? null);
    setRegla(otra?.regla_nueva ?? "");
  };

  const mensaje = (h: Hecho) => {
    if (h.accion === "aprobada")
      return `Aprobada: entra a la Biblioteca · ${textoDecision({
        estado: h.despues.estado,
        decidido_por: h.despues.decidido_por ?? null,
      })} · ${fechaCorta(h.despues.decidido_en)}.`;
    if (h.accion === "descartada")
      return `Descartada (${textoDecision({
        estado: h.despues.estado,
        decidido_por: h.despues.decidido_por ?? null,
      })}). No vuelve a proponerse con esta evidencia.`;
    return "Editada: se guardó tu versión de la regla.";
  };

  const decidida = hecho && hecho.accion !== "editada";
  const porDecidir = propuestas.data?.filter((p) => p.id !== actual?.id) ?? [];

  return (
    <div className="flex flex-col gap-4 py-2 max-w-3xl">
      <div>
        <h1 className="text-2xl font-semibold">Validar lección</h1>
        <p className="text-muted-foreground">
          {actual && actual.estado === "propuesta" && posicion > 0
            ? `${posicion} de ${total} propuestas por aprobar`
            : `${total} propuestas por aprobar`}
        </p>
      </div>

      {propuestas.isError ? (
        <NoCargo que="las lecciones por aprobar" />
      ) : propuestas.isPending ? (
        <Cargando />
      ) : !actual ? (
        <Vacio>
          No hay lecciones por aprobar. El detector propone nuevas cada noche.
        </Vacio>
      ) : (
        <Card>
          <CardContent>
            <section
              aria-label="Lección propuesta"
              className="flex flex-col gap-3"
            >
              <p>
                <span className="inline-block rounded-full bg-amber-100 px-2 py-0.5 text-xs font-semibold text-amber-800 dark:bg-amber-900/40 dark:text-amber-200">
                  Lección{" "}
                  {actual.estado === "propuesta" ? "propuesta" : actual.estado}
                </span>
              </p>
              <dl className="grid gap-3 [&_dt]:text-xs [&_dt]:font-semibold [&_dt]:text-muted-foreground [&_dd]:break-words">
                <Campo nombre="Categoría">{capital(actual.categoria)}</Campo>
                <Campo nombre="Qué pasó">{actual.que_paso}</Campo>
                <Campo nombre="Causa raíz">
                  {actual.causa_raiz || "Sin dato"}
                </Campo>
                <Campo nombre="Costo / impacto">
                  {actual.costo_centavos != null
                    ? dinero(actual.costo_centavos)
                    : "Sin dato"}
                </Campo>
                <Campo nombre="Solución">{actual.solucion || "Sin dato"}</Campo>
                <Campo nombre="Regla nueva">
                  {editando ? (
                    <Textarea
                      aria-label="Regla nueva"
                      rows={3}
                      value={regla}
                      onChange={(e) => setRegla(e.target.value)}
                    />
                  ) : (
                    actual.regla_nueva || "Sin dato"
                  )}
                </Campo>
                <Campo nombre="Tipo de proyecto">
                  {actual.tipo_proyecto || "Sin dato"}
                </Campo>
                <Campo nombre="Evidencia">
                  {(evidencias.data ?? []).length ? (
                    <ul className="flex flex-col gap-1">
                      {(evidencias.data ?? []).map((e) => (
                        <li key={e.id}>
                          <TextoEvidencia
                            e={e}
                            correo={(correos.data ?? []).find(
                              (c) => c.id === e.correo_id,
                            )}
                          />
                        </li>
                      ))}
                    </ul>
                  ) : evidencias.isPending ? (
                    "Cargando…"
                  ) : (
                    "Sin evidencia"
                  )}
                </Campo>
              </dl>

              {!decidida ? (
                <div className="flex flex-wrap gap-2">
                  <Button
                    className="min-h-12"
                    onClick={aprobar}
                    disabled={trabajando}
                  >
                    Aprobar
                  </Button>
                  {editando ? (
                    <>
                      <Button
                        className="min-h-12"
                        variant="outline"
                        onClick={guardarEdicion}
                        disabled={trabajando}
                      >
                        Guardar
                      </Button>
                      <Button
                        className="min-h-12"
                        variant="ghost"
                        onClick={() => {
                          setEditando(false);
                          setRegla(actual.regla_nueva ?? "");
                        }}
                        disabled={trabajando}
                      >
                        Cancelar
                      </Button>
                    </>
                  ) : (
                    <Button
                      className="min-h-12"
                      variant="outline"
                      onClick={() => setEditando(true)}
                      disabled={trabajando}
                    >
                      Editar
                    </Button>
                  )}
                  <Button
                    className="min-h-12 text-destructive"
                    variant="outline"
                    onClick={descartar}
                    disabled={trabajando}
                  >
                    Descartar
                  </Button>
                </div>
              ) : null}

              <div
                ref={avisoRef}
                role="status"
                aria-live="polite"
                className="scroll-mb-28"
              >
                {hecho ? (
                  <div className="flex flex-wrap items-center gap-3 rounded-md bg-green-50 p-3 text-green-900 dark:bg-green-900/30 dark:text-green-100">
                    <span>{mensaje(hecho)}</span>
                    <Button
                      variant="link"
                      className="min-h-11 px-1"
                      onClick={deshacer}
                      disabled={trabajando}
                    >
                      Deshacer
                    </Button>
                    {decidida && porDecidir.length ? (
                      <Button
                        variant="outline"
                        className="min-h-11"
                        onClick={siguiente}
                        disabled={trabajando}
                      >
                        Siguiente
                      </Button>
                    ) : null}
                  </div>
                ) : null}
              </div>
              {error ? (
                <p role="alert" className="text-destructive text-sm">
                  {error}
                </p>
              ) : null}
            </section>
          </CardContent>
        </Card>
      )}
      <Link to="/lecciones" className="text-sm underline">
        Volver a Lecciones
      </Link>
    </div>
  );
};

ValidarPage.path = "/lecciones/validar";
ValidarPage.pathUna = "/lecciones/validar/:id";

const Campo = ({
  nombre,
  children,
}: {
  nombre: string;
  children: React.ReactNode;
}) => (
  <div className="flex flex-col gap-0.5">
    <dt>{nombre}</dt>
    <dd>{children}</dd>
  </div>
);

const TextoEvidencia = ({ e, correo }: { e: Evidencia; correo?: Correo }) => {
  const texto =
    e.tipo === "correo" && correo
      ? `Correo de ${correo.de ?? "remitente sin dato"}${
          correo.asunto ? ` · ${correo.asunto}` : ""
        } · ${fechaCorta(correo.fecha)}`
      : `${capital(e.tipo)} ${e[`${e.tipo}_id` as keyof Evidencia] ?? ""}`.trim();
  return e.enlace ? (
    <a href={e.enlace} target="_blank" rel="noreferrer" className="underline">
      {texto}
    </a>
  ) : (
    <>{texto}</>
  );
};
