// prototipo/src/comun.mjs:3-9
export class ErrorLector extends Error {
  faltan: string[];
  constructor(mensaje: string, faltan: string[] = []) {
    super(mensaje);
    this.name = "ErrorLector";
    this.faltan = faltan;
  }
}

/** -0 → 0. Un monto en cero nunca se muestra «-0.00». */
const sinMenosCero = (c: number) => (c === 0 ? 0 : c);

/**
 * "1,234.56" | "B/. 1,234.56" | "-45.00" | número → centavos enteros. Vacío → 0.
 * prototipo/src/comun.mjs:21-30
 */
export function centavos(v: unknown): number {
  if (v === null || v === undefined || v === "") return 0;
  if (typeof v === "number") return sinMenosCero(Math.round(v * 100));
  const limpio = String(v).replace(/B\/\.|\$|\s|,/g, "");
  if (limpio === "" || limpio === "-") return 0;
  const n = Number(limpio);
  if (Number.isNaN(n)) throw new ErrorLector(`monto que no reconozco: «${v}»`);
  return sinMenosCero(Math.round(n * 100));
}

/** Suma montos pasando cada uno a centavos primero: nunca en decimales. */
export function sumarCentavos(montos: unknown[]): number {
  return sinMenosCero(montos.reduce<number>((s, m) => s + centavos(m), 0));
}

/** Centavos → "1,234.56". prototipo/src/comun.mjs:32 */
export const dinero = (c: number) =>
  (sinMenosCero(c) / 100).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

// KF-30: el estado de cuenta real de DPB trae «13-nov-2025».
const MESES = [
  "ene",
  "feb",
  "mar",
  "abr",
  "may",
  "jun",
  "jul",
  "ago",
  "sep",
  "oct",
  "nov",
  "dic",
];
/** Fecha de estado de cuenta: "01/10/2026" o "01-oct-2026". */
export const RE_FECHA = /^(\d{1,2})(?:\/(\d{1,2})\/|-([a-z]{3})-)(\d{4})$/i;

/**
 * "01/10/2026" (día/mes/año) o "01-oct-2026" → "2026-10-01".
 * prototipo/src/comun.mjs:34-40
 */
export function fechaIso(v: unknown): string {
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  const m = String(v ?? "")
    .trim()
    .match(RE_FECHA);
  const mes = m && (m[2] ?? String(MESES.indexOf(m[3].toLowerCase()) + 1));
  if (!m || mes === "0")
    throw new ErrorLector(`fecha que no reconozco: «${v}»`);
  return `${m[4]}-${mes!.padStart(2, "0")}-${m[1].padStart(2, "0")}`;
}

/** prototipo/src/comun.mjs:42-46 */
export function sumarDias(iso: string, dias: number): string {
  const d = new Date(`${iso}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + dias);
  return d.toISOString().slice(0, 10);
}

/** Días de a hasta b (ISO). KF-15. prototipo/src/comun.mjs:48-50 */
export function diasEntre(a: string, b: string): number {
  return Math.round(
    (Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86400000,
  );
}
