// Yunque 8 · eventos de la app («objeto.acción»).
// La app todavía no tiene tabla de eventos (no entró en KF-03), así que el
// evento queda en memoria en window.__kfEventos y sale como CustomEvent
// «kf:evento». Cuando exista la tabla, solo cambia esta función.

export type EventoKf = {
  tipo: string;
  datos: Record<string, unknown>;
  en: string;
};

declare global {
  interface Window {
    __kfEventos?: EventoKf[];
  }
}

export const registrarEvento = (
  tipo: string,
  datos: Record<string, unknown> = {},
  ahora: () => Date = () => new Date(),
): EventoKf => {
  const evento: EventoKf = { tipo, datos, en: ahora().toISOString() };
  if (typeof window !== "undefined") {
    (window.__kfEventos ??= []).push(evento);
    window.dispatchEvent(new CustomEvent("kf:evento", { detail: evento }));
  }
  return evento;
};
