// Kaizen Files · KF-13 · c1-r-cobros (R010–R012), c2-cobros-tabla y
// c2-cobros-subir (R055), maqueta Cobros. Reemplaza la pantalla provisional
// de KF-06 en /cobros.
// «Leer facturas» lee PDF de la DGI y los guarda en la tabla facturas (la que
// usa el expediente de KF-08). «Leer estado del banco» lee el PDF del banco,
// lo cruza (kaizen/lectores/cruce.ts) y guarda lo pagado en facturas y pagos.
// pdf.js y SheetJS llegan solo con cargar.ts (KF-12): nunca import estático.
// KF-14 · c1-r-empresas, c2-cobros-empresa: filtro por empresa; la factura va
// a su empresa por el RUC emisor; sin cuenta de banco queda «sin cruzar».
// KF-21 · c2-cobros-leccion: un cliente con 2 pagos tardíos (en las facturas
// del filtro) muestra la lección propuesta con evidencia en esas facturas y
// la abre en Validar (KF-20). La búsqueda por evidencia es la del expediente.
import { useQuery } from "@tanstack/react-query";
import {
  useDataProvider,
  useGetIdentity,
  useGetList,
  type Identifier,
} from "ra-core";
import { useMemo, useRef, useState, type RefObject } from "react";
import { Link } from "react-router";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

import { leerArchivo, type TipoArchivo } from "@/kaizen/lectores/archivo";
import { cargarLibrerias } from "@/kaizen/lectores/cargar";
import { dinero } from "@/kaizen/lectores/comun";
import {
  cruzar,
  estadoGuardado,
  mencionaCliente,
  type SinAsignar,
} from "@/kaizen/lectores/cruce";
import type {
  Empresa,
  Factura as FacturaLeida,
  Movimiento,
} from "@/kaizen/lectores/lectores";
import {
  fechaCorta,
  leccionesDelCliente,
  type Evidencia,
  type Leccion,
} from "../expediente/lineaDeTiempo";
import { ValidarPage } from "../lecciones/ValidarPage";
import { registrarEvento } from "../misc/eventos";
import { Cargando, NoCargo, Vacio } from "../misc/Estados";
import type { Company } from "../types";
import { estadoCobro, hoyLocal, rucsConCuenta } from "./estadoCobro";
import { clientesConPagosTardios } from "./tardios";

type Fila = {
  id: Identifier;
  empresa_ruc: string;
  numero: string;
  cliente_id?: Identifier | null;
  fecha?: string | null;
  vence?: string | null;
  monto_centavos: number;
  pagado_centavos?: number;
  estado?: string;
};
type Pago = {
  id: Identifier;
  factura_id: Identifier;
  fecha?: string | null;
  monto_centavos: number;
};
type EmpresaFila = { id: Identifier; nombre: string; ruc?: string | null };
type CuentaFila = { id: Identifier; tipo: string; empresa_ruc?: string | null };
type Aviso = { archivo: string; motivo: string };

const TODAS = { pagination: { page: 1, perPage: 10000 } };

const bytesDe = async (f: File) => new Uint8Array(await f.arrayBuffer());

export const CobrosPage = () => {
  const dp = useDataProvider();
  const { identity } = useGetIdentity();
  const autor = identity?.fullName ?? null;
  const facturas = useGetList<Fila>("facturas", {
    ...TODAS,
    sort: { field: "vence", order: "ASC" },
  });
  const pagos = useGetList<Pago>("pagos", {
    ...TODAS,
    sort: { field: "fecha", order: "ASC" },
  });
  const companies = useGetList<Company>("companies", {
    ...TODAS,
    sort: { field: "id", order: "ASC" },
  });
  const empresasQ = useGetList<EmpresaFila>("empresas", {
    ...TODAS,
    sort: { field: "id", order: "ASC" },
  });
  // Solo las empresas con RUC: la factura DGI se reconoce por el RUC emisor.
  const empresas: Empresa[] = useMemo(
    () =>
      (empresasQ.data ?? [])
        .filter((e) => e.ruc)
        .map((e) => ({ nombre: e.nombre, ruc: String(e.ruc) })),
    [empresasQ.data],
  );
  const cuentas = useGetList<CuentaFila>("cuentas", {
    ...TODAS,
    sort: { field: "id", order: "ASC" },
  });
  // RUC de las empresas con cuenta de banco: solo esas tienen estado que cruzar.
  const conCuenta = useMemo(
    () => rucsConCuenta(cuentas.data ?? []),
    [cuentas.data],
  );
  // Filtro: "" son todas las empresas; si no, el RUC de una.
  const [rucFiltro, setRucFiltro] = useState<string>("");
  const empresaFiltro = empresas.find((e) => e.ruc === rucFiltro) ?? null;

  const [trabajando, setTrabajando] = useState(false);
  // Sin empresas ni clientes cargados no se puede reconocer nada todavía.
  const cargando = [facturas, pagos, companies, empresasQ, cuentas].some(
    (q) => q.isPending,
  );
  const ocupado = trabajando || cargando;
  const [avisos, setAvisos] = useState<Aviso[]>([]);
  const [sinFactura, setSinFactura] = useState<SinAsignar[]>([]);
  const entradaFacturas = useRef<HTMLInputElement>(null);
  const entradaBanco = useRef<HTMLInputElement>(null);

  const nombreCliente = (id?: Identifier | null) =>
    (companies.data ?? []).find((c) => c.id === id)?.name ?? "";

  const leer = async (archivo: File, tipo: TipoArchivo, cuenta?: string) =>
    leerArchivo(
      {
        nombre: archivo.name,
        tipo,
        bytes: await bytesDe(archivo),
        empresas,
        cuenta,
      },
      { libs: await cargarLibrerias(), registrar: registrarEvento },
    );

  const todasLasFacturas = async () =>
    (
      await dp.getList<Fila>("facturas", {
        ...TODAS,
        sort: { field: "id", order: "ASC" },
        filter: {},
      })
    ).data;

  const leerFacturas = async (archivos: File[]) => {
    const nuevos: Aviso[] = [];
    const existentes = await todasLasFacturas();
    for (const archivo of archivos) {
      const r = await leer(archivo, "factura-dgi");
      if (!r.ok) {
        nuevos.push({ archivo: archivo.name, motivo: r.motivo });
        continue;
      }
      const f = r.datos as FacturaLeida;
      const ruc = empresas.find((e) => e.nombre === f.empresa)?.ruc ?? "";
      if (
        existentes.some((x) => x.empresa_ruc === ruc && x.numero === f.numero)
      ) {
        nuevos.push({
          archivo: archivo.name,
          motivo: `la factura ${f.numero} ya estaba`,
        });
        continue;
      }
      const cliente = (companies.data ?? []).find((c) =>
        mencionaCliente(f.cliente, c.name),
      );
      if (!cliente) {
        nuevos.push({
          archivo: archivo.name,
          motivo: `factura ${f.numero}: el cliente «${f.cliente}» no está en Clientes`,
        });
        continue;
      }
      const creada = (
        await dp.create<Fila>("facturas", {
          data: {
            empresa_ruc: ruc,
            numero: f.numero,
            cliente_id: cliente.id,
            fecha: f.fecha,
            vence: f.vence,
            monto_centavos: f.total,
            pagado_centavos: 0,
            estado: "pendiente",
            archivo_origen: archivo.name,
            autor,
          },
        })
      ).data;
      existentes.push(creada);
      registrarEvento("factura.leida", {
        factura_id: creada.id,
        numero: f.numero,
        empresa: f.empresa,
        cliente_id: cliente.id,
        total: f.total,
        archivo: archivo.name,
      });
    }
    return nuevos;
  };

  const leerBanco = async (archivos: File[]) => {
    const nuevos: Aviso[] = [];
    // El estado es de la empresa del filtro; con «Todas», de la única con cuenta.
    const candidatas = empresaFiltro
      ? [empresaFiltro]
      : empresas.filter((e) => conCuenta.has(e.ruc));
    const motivo = !candidatas.length
      ? "ninguna empresa tiene cuenta de banco: agréguela en Puesta en marcha"
      : candidatas.length > 1
        ? "elija en el filtro la empresa del estado"
        : !conCuenta.has(candidatas[0].ruc)
          ? `${candidatas[0].nombre} no tiene cuenta de banco: agréguela en Puesta en marcha`
          : null;
    if (motivo) return archivos.map((a) => ({ archivo: a.name, motivo }));
    const empresaBanco = candidatas[0];
    const movs: Movimiento[] = [];
    for (const archivo of archivos) {
      const r = await leer(archivo, "banco-pdf", empresaBanco.nombre);
      if (!r.ok) nuevos.push({ archivo: archivo.name, motivo: r.motivo });
      else movs.push(...(r.datos as Movimiento[]));
    }
    if (!movs.length) return nuevos;

    // En orden de lectura (id); el cruce las reparte por vencimiento.
    const deEmpresa = (await todasLasFacturas()).filter(
      (f) => f.empresa_ruc === empresaBanco.ruc,
    );
    const { facturas: cruzadas, sinAsignar } = cruzar(
      deEmpresa.map((f) => ({
        fila: f,
        empresa: empresaBanco.nombre,
        numero: f.numero,
        cliente: nombreCliente(f.cliente_id),
        vence: f.vence ?? f.fecha ?? "",
        total: f.monto_centavos,
        pagado: f.pagado_centavos ?? 0,
      })),
      { [empresaBanco.nombre]: movs },
      hoyLocal,
    );
    const conPago = cruzadas
      .filter((f) => f.pagos.length)
      .sort(
        (a, b) =>
          a.pagos[0].fecha.localeCompare(b.pagos[0].fecha) ||
          a.vence.localeCompare(b.vence),
      );
    for (const f of conPago) {
      const estado = estadoGuardado(f);
      await dp.update<Fila>("facturas", {
        id: f.fila.id,
        data: { pagado_centavos: f.pagado, estado },
        previousData: f.fila,
      });
      for (const p of f.pagos) {
        await dp.create("pagos", {
          data: {
            factura_id: f.fila.id,
            fecha: p.fecha,
            monto_centavos: p.monto,
            autor,
          },
        });
        registrarEvento("pago.cruzado", {
          factura_id: f.fila.id,
          numero: f.numero,
          monto: p.monto,
          fecha: p.fecha,
          referencia: p.referencia,
          estado,
        });
      }
    }
    setSinFactura(sinAsignar);
    return nuevos;
  };

  const correr = async (
    entrada: RefObject<HTMLInputElement | null>,
    accion: (a: File[]) => Promise<Aviso[]>,
  ) => {
    const archivos = [...(entrada.current?.files ?? [])];
    if (entrada.current) entrada.current.value = "";
    if (!archivos.length) return;
    setTrabajando(true);
    setAvisos([]);
    try {
      setAvisos(await accion(archivos));
    } catch (e) {
      setAvisos([
        {
          archivo: archivos.map((a) => a.name).join(", "),
          motivo: (e as Error).message,
        },
      ]);
    } finally {
      await Promise.all([facturas.refetch(), pagos.refetch()]);
      setTrabajando(false);
    }
  };

  const ultimoPago = useMemo(() => {
    const m = new Map<Identifier, string>();
    for (const p of pagos.data ?? []) if (p.fecha) m.set(p.factura_id, p.fecha);
    return m;
  }, [pagos.data]);

  const hoy = hoyLocal();
  const todas = facturas.data ?? [];
  const filas = rucFiltro
    ? todas.filter((f) => f.empresa_ruc === rucFiltro)
    : todas;

  // Pagos tardíos repetidos, sobre las facturas del filtro de empresa.
  const tardios = clientesConPagosTardios(filas, pagos.data ?? []);
  const idsTardias = [...tardios.values()]
    .flat()
    .map(Number)
    .sort((a, b) => a - b);
  const leccionesTardias = useQuery({
    queryKey: ["kf-cobros-lecciones", idsTardias.join(",")],
    enabled: idsTardias.length > 0,
    retry: false,
    queryFn: async () => {
      const lista = async <T,>(recurso: string, filter: object) =>
        (
          await dp.getList(recurso, {
            ...TODAS,
            filter,
            sort: { field: "id", order: "ASC" },
          })
        ).data as T[];
      const evidencias = await lista<Evidencia>("evidencias", {
        "factura_id@in": `(${idsTardias.join(",")})`,
      });
      const ids = leccionesDelCliente(evidencias, {
        correos: [],
        minutas: [],
        facturas: idsTardias,
      });
      if (!ids.length) return [];
      return (
        await lista<Leccion>("lecciones", { "id@in": `(${ids.join(",")})` })
      ).map((l) => ({
        ...l,
        evidencias: evidencias.filter((e) => e.leccion_id === l.id),
      }));
    },
  });
  /** La lección propuesta con evidencia en las facturas tardías del cliente. */
  const leccionDe = (facturasTarde: Identifier[]) =>
    (leccionesTardias.data ?? []).find(
      (l) =>
        l.estado === "propuesta" &&
        l.evidencias?.some((e) =>
          facturasTarde.map(Number).includes(Number(e.factura_id)),
        ),
    );

  return (
    <div className="flex flex-col gap-5 py-2">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl md:text-[28px] font-bold m-0">Cobros</h1>
        <p className="text-sm text-muted-foreground m-0">
          Facturas × estado del banco
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <Button
          className="min-h-11"
          disabled={ocupado}
          onClick={() => entradaFacturas.current?.click()}
        >
          Leer facturas
        </Button>
        <input
          ref={entradaFacturas}
          type="file"
          accept=".pdf,application/pdf"
          multiple
          hidden
          onChange={() => correr(entradaFacturas, leerFacturas)}
        />
        <Button
          variant="outline"
          className="min-h-11"
          disabled={ocupado}
          onClick={() => entradaBanco.current?.click()}
        >
          Leer estado del banco
        </Button>
        <input
          ref={entradaBanco}
          type="file"
          accept=".pdf,application/pdf"
          multiple
          hidden
          onChange={() => correr(entradaBanco, leerBanco)}
        />
        <select
          aria-label="Empresa"
          className="min-h-11 max-w-full rounded-md border bg-background px-2 text-sm"
          value={rucFiltro}
          onChange={(e) => setRucFiltro(e.target.value)}
        >
          <option value="">Todas las empresas</option>
          {empresas.map((e) => (
            <option key={e.ruc} value={e.ruc}>
              {e.nombre}
            </option>
          ))}
        </select>
        {trabajando ? (
          <span className="text-sm text-muted-foreground">Leyendo…</span>
        ) : null}
      </div>

      {avisos.length ? (
        <div
          role="alert"
          className="rounded-lg border border-amber-300 bg-amber-50 text-amber-900 dark:bg-amber-950 dark:text-amber-100 px-4 py-3 text-sm"
        >
          <p className="m-0 font-semibold">No se reconoció:</p>
          <ul className="m-0 pl-5">
            {avisos.map((a, i) => (
              <li key={i}>
                {a.archivo}: {a.motivo}
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      <Card>
        <CardContent>
          {facturas.isError ? (
            <NoCargo que="las facturas" />
          ) : facturas.isPending ? (
            <Cargando />
          ) : !todas.length ? (
            <Vacio>Aún no hay facturas. Toque «Leer facturas».</Vacio>
          ) : !filas.length ? (
            <Vacio>{empresaFiltro?.nombre} no tiene facturas.</Vacio>
          ) : (
            <table
              role="table"
              aria-label="Cobros"
              className="w-full text-sm border-collapse"
            >
              <thead role="rowgroup" className="max-md:sr-only">
                <tr role="row" className="border-b text-left">
                  {["Factura", "Cliente", "Monto", "Estado", "Pago"].map(
                    (c) => (
                      <th
                        key={c}
                        role="columnheader"
                        className="py-2 pr-3 font-semibold"
                      >
                        {c}
                      </th>
                    ),
                  )}
                </tr>
              </thead>
              <tbody role="rowgroup">
                {filas.map((f) => {
                  const pagado = f.pagado_centavos ?? 0;
                  const fechaPago = ultimoPago.get(f.id);
                  // Sin cuenta de banco no hay estado que cruzar (c1-r-empresas límite).
                  const estado = estadoCobro(f, conCuenta, hoy);
                  return (
                    <tr
                      key={f.id}
                      role="row"
                      className="border-b last:border-b-0 max-md:grid max-md:grid-cols-[1fr_auto] max-md:gap-x-3 max-md:gap-y-1 max-md:py-3"
                    >
                      <td
                        role="cell"
                        className="md:py-2.5 md:pr-3 font-semibold"
                      >
                        <span data-col="factura">{f.numero}</span>
                      </td>
                      <td
                        role="cell"
                        className="md:py-2.5 md:pr-3 max-md:col-start-1 max-md:row-start-2 min-w-0"
                      >
                        <span data-col="cliente">
                          {nombreCliente(f.cliente_id)}
                        </span>
                      </td>
                      <td
                        role="cell"
                        className="md:py-2.5 md:pr-3 tabular-nums max-md:col-start-2 max-md:row-start-1 max-md:text-right font-medium"
                      >
                        <span data-col="monto">{dinero(f.monto_centavos)}</span>
                      </td>
                      <td
                        role="cell"
                        className="md:py-2.5 md:pr-3 max-md:col-start-2 max-md:row-start-2 max-md:text-right"
                      >
                        <span data-col="estado">
                          <Badge
                            variant={
                              estado === "Vencida" || estado === "Revisar"
                                ? "destructive"
                                : "secondary"
                            }
                          >
                            {estado}
                          </Badge>
                        </span>
                      </td>
                      <td
                        role="cell"
                        className="md:py-2.5 tabular-nums text-muted-foreground max-md:col-span-2"
                      >
                        <span data-col="pago">
                          {`${dinero(pagado)} de ${dinero(f.monto_centavos)}`}
                          {fechaPago ? ` · ${fechaCorta(fechaPago)}` : ""}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </CardContent>
      </Card>

      {tardios.size ? (
        <Card>
          <CardContent>
            <section aria-label="Pagos tardíos" className="flex flex-col gap-2">
              <h2 className="text-lg font-semibold m-0">Pagos tardíos</h2>
              <ul className="list-none m-0 p-0 text-sm">
                {[...tardios].map(([clienteId, ids]) => {
                  const l = leccionDe(ids);
                  return (
                    <li
                      key={clienteId}
                      className="flex flex-col gap-1 py-2 border-b last:border-b-0"
                    >
                      <span>
                        <b>{nombreCliente(clienteId)}</b>
                        {` · ${ids.length} pagos tardíos`}
                      </span>
                      {l ? (
                        <span className="flex flex-wrap items-center gap-x-2">
                          <span className="text-muted-foreground min-w-0 break-words">
                            {l.que_paso}
                          </span>
                          <Link
                            to={ValidarPage.pathUna.replace(
                              ":id",
                              String(l.id),
                            )}
                            className="inline-flex items-center min-h-11 font-medium underline"
                            onClick={() =>
                              registrarEvento("leccion.abierta", {
                                leccion_id: l.id,
                                desde: "cobros",
                                cliente_id: clienteId,
                              })
                            }
                          >
                            Ver lección propuesta
                          </Link>
                        </span>
                      ) : (
                        <span className="text-muted-foreground">
                          {leccionesTardias.isPending
                            ? "Cargando…"
                            : "Aún sin lección propuesta: el detector la propone de noche."}
                        </span>
                      )}
                    </li>
                  );
                })}
              </ul>
            </section>
          </CardContent>
        </Card>
      ) : null}

      {sinFactura.length ? (
        <Card>
          <CardContent className="flex flex-col gap-2">
            <h2 className="text-lg font-semibold m-0">
              Entró al banco sin factura
            </h2>
            <ul aria-label="Sin factura" className="list-none m-0 p-0 text-sm">
              {sinFactura.map((m, i) => (
                <li key={i} className="py-1.5 border-b last:border-b-0">
                  {fechaCorta(m.fecha)} · {m.descripcion} ·{" "}
                  <span className="tabular-nums">{dinero(m.monto)}</span>
                  {m.nota ? ` (${m.nota})` : ""}
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      ) : null}
    </div>
  );
};

CobrosPage.path = "/cobros";
