// Kaizen Files · KF-09 · c1-r-negocios y c2-negocios-embudo (R028–R030, R049),
// maqueta Negocios. Reemplaza la pantalla provisional de KF-06 en /negocios.
// Usa el tablero de deals de Atomic CRM (deals/DealListContent.tsx) con su
// arrastre (@hello-pangea/dnd), ajustado a 4 etapas. En la PC se arrastra;
// en el celular cada tarjeta trae «Mover a». Pasar a perdida pide motivo:
// queda como nota del negocio (deal_notes de Atomic), sin columnas nuevas.
import {
  DragDropContext,
  Draggable,
  Droppable,
  type OnDragEndResponder,
} from "@hello-pangea/dnd";
import { GripVertical } from "lucide-react";
import {
  useDataProvider,
  useGetIdentity,
  useGetList,
  type Identifier,
} from "ra-core";
import { useMemo, useState, type CSSProperties } from "react";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useIsMobile } from "@/hooks/use-mobile";

import { registrarEvento } from "../misc/eventos";
import { EstadoDatos } from "../misc/Estados";
import type { Company, Deal, DealNote } from "../types";
import {
  bloqueoBorrar,
  ETAPAS,
  etapaDe,
  PREFIJO_MOTIVO,
  ReglaNegocio,
  stageDe,
  validarMovida,
  type EtapaId,
} from "./etapasNegocio";

const TODAS = {
  pagination: { page: 1, perPage: 10000 },
  sort: { field: "index", order: "ASC" as const },
};

type Pendiente = { deal: Deal; a: EtapaId };

export const NegociosPage = () => {
  const deals = useGetList<Deal>("deals", {
    ...TODAS,
    filter: { "archived_at@is": null },
  });
  const companies = useGetList<Company>("companies", {
    ...TODAS,
    sort: { field: "id", order: "ASC" },
  });
  const notas = useGetList<DealNote>("deal_notes", {
    ...TODAS,
    sort: { field: "id", order: "ASC" },
  });
  const dataProvider = useDataProvider();
  const { identity } = useGetIdentity();
  const isMobile = useIsMobile();

  // Etapa puesta a mano mientras se guarda, para que el arrastre no rebote.
  const [movidas, setMovidas] = useState<Record<string, EtapaId>>({});
  const [pidiendoMotivo, setPidiendoMotivo] = useState<Pendiente | null>(null);
  const [aviso, setAviso] = useState<string | null>(null);

  const nombreCliente = useMemo(() => {
    const m = new Map<Identifier, string>();
    for (const c of companies.data ?? []) m.set(c.id, c.name);
    return (id: Identifier) => m.get(id) ?? "";
  }, [companies.data]);

  const motivoDe = useMemo(() => {
    const m = new Map<Identifier, string>();
    for (const n of notas.data ?? []) {
      if (n.text?.startsWith(PREFIJO_MOTIVO)) {
        m.set(n.deal_id, n.text.slice(PREFIJO_MOTIVO.length));
      }
    }
    return m;
  }, [notas.data]);

  const etapaActual = (d: Deal) => movidas[String(d.id)] ?? etapaDe(d.stage);

  const porEtapa = useMemo(() => {
    const cols = Object.fromEntries(
      ETAPAS.map((e) => [e.id, [] as Deal[]]),
    ) as Record<EtapaId, Deal[]>;
    for (const d of deals.data ?? []) cols[etapaActual(d)].push(d);
    return cols;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [deals.data, movidas]);

  /** Único camino para cambiar de etapa: valida, guarda y deja el evento. */
  const mover = async (deal: Deal, a: EtapaId, motivo?: string) => {
    const de = etapaDe(deal.stage);
    if (de === a) return;
    const limpio = validarMovida(a, motivo);
    setAviso(null);
    setMovidas((m) => ({ ...m, [String(deal.id)]: a }));
    try {
      const destino = (deals.data ?? []).filter((d) => etapaDe(d.stage) === a);
      const index = Math.max(0, ...destino.map((d) => d.index ?? 0)) + 1;
      await dataProvider.update<Deal>("deals", {
        id: deal.id,
        data: { stage: stageDe(a), index },
        previousData: deal,
      });
      if (limpio) {
        await dataProvider.create("deal_notes", {
          data: {
            deal_id: deal.id,
            text: `${PREFIJO_MOTIVO}${limpio}`,
            date: new Date().toISOString(),
            sales_id: identity?.id,
          },
        });
      }
      registrarEvento("negocio.movido", {
        negocio: deal.id,
        cliente: nombreCliente(deal.company_id),
        de,
        a,
        ...(limpio ? { motivo: limpio } : {}),
      });
      await Promise.all([deals.refetch(), notas.refetch()]);
    } catch (e) {
      setAviso(`No se pudo mover «${deal.name}»: ${(e as Error).message}`);
    } finally {
      setMovidas((m) => {
        const { [String(deal.id)]: _, ...resto } = m;
        return resto;
      });
    }
  };

  /** Pasar a perdida abre el diálogo; lo demás se mueve directo. */
  const pedirMover = (deal: Deal, a: EtapaId) => {
    if (a === "perdida") setPidiendoMotivo({ deal, a });
    else void mover(deal, a);
  };

  const borrar = async (deal: Deal) => {
    const bloqueo = bloqueoBorrar(deal);
    if (bloqueo) {
      setAviso(bloqueo);
      return;
    }
    if (!window.confirm(`¿Borrar «${deal.name}»?`)) return;
    setAviso(null);
    try {
      await dataProvider.delete<Deal>("deals", {
        id: deal.id,
        previousData: deal,
      });
      await deals.refetch();
    } catch (e) {
      setAviso(`No se pudo borrar «${deal.name}»: ${(e as Error).message}`);
    }
  };

  const onDragEnd: OnDragEndResponder = ({ destination, draggableId }) => {
    if (!destination) return;
    const deal = (deals.data ?? []).find((d) => String(d.id) === draggableId);
    if (!deal) return;
    pedirMover(deal, destination.droppableId as EtapaId);
  };

  const cargando = deals.isPending || companies.isPending;

  return (
    <div className="flex flex-col gap-4 py-2">
      <div>
        <h1 className="text-2xl font-semibold">Negocios</h1>
        <p className="text-sm text-muted-foreground">
          Embudo de cotizaciones
          {isMobile ? "" : ": arrastra cada tarjeta a su etapa"}
        </p>
      </div>

      {aviso ? (
        <Alert variant="destructive">
          <AlertDescription>{aviso}</AlertDescription>
        </Alert>
      ) : null}

      <EstadoDatos
        consultas={[deals, companies]}
        que="los negocios"
        hayDatos={(deals.data ?? []).length > 0}
        vacio="Todavía no hay negocios. Empiece uno con «Nuevo proyecto» en Clientes."
      >
        {null}
      </EstadoDatos>

      {cargando || deals.isError || companies.isError ? null : (
        <DragDropContext onDragEnd={onDragEnd}>
          <div className="flex flex-col gap-4 md:grid md:grid-cols-4 md:items-start">
            {ETAPAS.map((etapa) => (
              <Columna
                key={etapa.id}
                etapa={etapa}
                deals={porEtapa[etapa.id]}
                arrastrable={!isMobile}
                cliente={nombreCliente}
                motivo={(d) => motivoDe.get(d.id)}
                onMover={pedirMover}
                onBorrar={borrar}
              />
            ))}
          </div>
        </DragDropContext>
      )}

      <DialogoMotivo
        pendiente={pidiendoMotivo}
        onCerrar={() => setPidiendoMotivo(null)}
        onGuardar={async (motivo) => {
          // validarMovida lanza ReglaNegocio si falta el motivo.
          await mover(pidiendoMotivo!.deal, pidiendoMotivo!.a, motivo);
          setPidiendoMotivo(null);
        }}
      />
    </div>
  );
};

NegociosPage.path = "/negocios";

const dinero = (n: number) =>
  n.toLocaleString("es-PA", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  });

const Columna = ({
  etapa,
  deals,
  arrastrable,
  cliente,
  motivo,
  onMover,
  onBorrar,
}: {
  etapa: (typeof ETAPAS)[number];
  deals: Deal[];
  arrastrable: boolean;
  cliente: (id: Identifier) => string;
  motivo: (d: Deal) => string | undefined;
  onMover: (d: Deal, a: EtapaId) => void;
  onBorrar: (d: Deal) => void;
}) => {
  const total = deals.reduce((s, d) => s + (d.amount ?? 0), 0);
  return (
    <section className="flex flex-col gap-2 rounded-xl border bg-muted/30 p-3">
      <div className="flex items-baseline justify-between gap-2">
        <h2 className="text-base font-semibold">{etapa.nombre}</h2>
        <span className="text-xs text-muted-foreground">
          {deals.length} · {dinero(total)}
        </span>
      </div>
      <Droppable droppableId={etapa.id}>
        {(drop, snapshot) => (
          <ul
            aria-label={etapa.nombre}
            ref={drop.innerRef}
            {...drop.droppableProps}
            className={`m-0 flex min-h-16 list-none flex-col gap-2 rounded-lg p-0 ${
              snapshot.isDraggingOver ? "bg-muted" : ""
            }`}
          >
            {deals.map((d, i) => (
              <Draggable
                key={d.id}
                draggableId={String(d.id)}
                index={i}
                isDragDisabled={!arrastrable}
              >
                {(drag) => (
                  <li
                    ref={drag.innerRef}
                    {...drag.draggableProps}
                    style={drag.draggableProps.style as CSSProperties}
                    className="flex flex-col gap-2 rounded-lg border bg-card p-3 shadow-sm"
                  >
                    <div className="flex items-start gap-2">
                      {arrastrable ? (
                        <span
                          {...drag.dragHandleProps}
                          role="button"
                          aria-label={`Arrastrar ${d.name}`}
                          className="mt-0.5 cursor-grab text-muted-foreground"
                        >
                          <GripVertical className="size-4" />
                        </span>
                      ) : null}
                      <div className="flex min-w-0 flex-1 flex-col">
                        <span className="font-medium">{d.name}</span>
                        <span className="text-sm text-muted-foreground">
                          {cliente(d.company_id)}
                        </span>
                        <span className="text-xs text-muted-foreground">
                          {dinero(d.amount ?? 0)}
                        </span>
                        {etapa.id === "perdida" && motivo(d) ? (
                          <span className="text-xs">{motivo(d)}</span>
                        ) : null}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <select
                        aria-label="Mover a"
                        className="min-h-11 min-w-0 flex-1 rounded-md border bg-background px-2 text-sm md:min-h-8"
                        value=""
                        onChange={(e) => {
                          if (e.target.value)
                            onMover(d, e.target.value as EtapaId);
                        }}
                      >
                        <option value="">Mover a…</option>
                        {ETAPAS.filter((e) => e.id !== etapa.id).map((e) => (
                          <option key={e.id} value={e.id}>
                            {e.nombre}
                          </option>
                        ))}
                      </select>
                      <Button
                        variant="outline"
                        size="sm"
                        className="min-h-11 md:min-h-8"
                        onClick={() => onBorrar(d)}
                      >
                        Borrar
                      </Button>
                    </div>
                  </li>
                )}
              </Draggable>
            ))}
            {drop.placeholder}
          </ul>
        )}
      </Droppable>
    </section>
  );
};

const DialogoMotivo = ({
  pendiente,
  onCerrar,
  onGuardar,
}: {
  pendiente: Pendiente | null;
  onCerrar: () => void;
  onGuardar: (motivo: string) => Promise<void>;
}) => {
  const [motivo, setMotivo] = useState("");
  const [error, setError] = useState<string | null>(null);
  const cerrar = () => {
    setMotivo("");
    setError(null);
    onCerrar();
  };
  return (
    <Dialog open={!!pendiente} onOpenChange={(o) => (o ? null : cerrar())}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>¿Por qué se perdió?</DialogTitle>
        </DialogHeader>
        <p className="text-sm text-muted-foreground">
          «{pendiente?.deal.name}» pasa a Perdida. Sin motivo no se guarda.
        </p>
        <div className="flex flex-col gap-1.5">
          <Label htmlFor="negocio-motivo">Motivo</Label>
          <Textarea
            id="negocio-motivo"
            value={motivo}
            onChange={(e) => setMotivo(e.target.value)}
          />
        </div>
        {error ? (
          <Alert variant="destructive">
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        ) : null}
        <DialogFooter>
          <Button variant="outline" onClick={cerrar}>
            Cancelar
          </Button>
          <Button
            onClick={async () => {
              try {
                await onGuardar(motivo);
                setMotivo("");
                setError(null);
              } catch (e) {
                if (e instanceof ReglaNegocio) setError(e.message);
                else throw e;
              }
            }}
          >
            Guardar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
