// Kaizen Files · KF-12 · R075. pdf.js (1,4 MB) y SheetJS (2,2 MB con el
// worker) se cargan solo cuando Cobros o Presupuesto los piden, nunca en el
// arranque. Solo import() dinámico aquí: Vite los deja en chunks aparte.
import type { Libs } from "./archivo";

let promesa: Promise<Libs> | undefined;

/** Carga pdf.js y SheetJS una sola vez. Lo llaman Cobros (KF-13) y Presupuesto (KF-16). */
export function cargarLibrerias(): Promise<Libs> {
  promesa ??= (async () => {
    const [pdfjs, worker, XLSX] = await Promise.all([
      import("pdfjs-dist"),
      import("pdfjs-dist/build/pdf.worker.mjs?url"),
      import("xlsx"),
    ]);
    pdfjs.GlobalWorkerOptions.workerSrc = worker.default;
    return { getDocument: pdfjs.getDocument, XLSX };
  })();
  return promesa;
}
