import type * as XLSXTipo from "xlsx";
import {
  ErrorLector,
  norm,
  centavos,
  fechaIso,
  sumarDias,
  RE_FECHA,
} from "./comun";
import type { Fila, Paginas, Pieza } from "./leer_pdf";

export type XLSX = typeof XLSXTipo;

export type Movimiento = {
  cuenta: string;
  fecha: string;
  referencia: string;
  descripcion: string;
  /** Centavos: + entra, − sale. */
  monto: number;
  saldo?: number;
  categoria_banco?: string;
};

export type Factura = {
  empresa: string;
  numero: string;
  cliente: string;
  fecha: string;
  vence: string;
  /** Centavos. */
  total: number;
};

export type Empresa = { nombre: string; ruc: string };

// ---------- Estado de cuenta en PDF ---------- prototipo/src/lectores.mjs:5-51
export const COLUMNAS_BANCO_PDF = [
  "Fecha",
  "Referencia",
  "Descripción",
  "Débito",
  "Crédito",
  "Total",
];

export function leerEstadoCuentaPdf(
  paginas: Paginas,
  cuenta: string,
): Movimiento[] {
  const movimientos: Movimiento[] = [];
  // KF-30: el estado real de DPB pone los títulos solo en la página 1; las
  // siguientes usan las mismas columnas.
  let cols: ReturnType<typeof columnasBanco> | null = null;
  for (const filas of paginas) {
    const iTitulos = filas.findIndex(
      (f) =>
        f.piezas.some((p) => norm(p.t) === "fecha") &&
        f.piezas.some((p) => norm(p.t).startsWith("descripci")),
    );
    if (iTitulos >= 0) cols = columnasBanco(filas[iTitulos].piezas);
    if (!cols) continue;
    for (const fila of filas.slice(iTitulos + 1)) {
      const celdas: Record<string, string> = {};
      for (const p of fila.piezas) {
        const centro = p.x + (p.ancho ?? 0) / 2;
        // Texto: la columna cuyo inicio queda justo a la izquierda. Números: la más cercana por centro.
        // KF-30: el banco real escribe «$45,000.00» y el débito «-$942.00».
        const esNumero = /^-?\$?-?[\d,]+\.\d{2}$/.test(p.t);
        let col: string;
        if (esNumero)
          col = cols.reduce((a, b) =>
            Math.abs(b.centro - centro) < Math.abs(a.centro - centro) ? b : a,
          ).c;
        else col = cols.filter((k) => p.x >= k.x0 - 3).at(-1)?.c ?? cols[0].c;
        celdas[col] = ((celdas[col] ?? "") + " " + p.t).trim();
      }
      if (!RE_FECHA.test(celdas.Fecha ?? "")) continue; // pie de página, saldo anterior…
      // El débito sale, venga con signo o sin él.
      const debito = Math.abs(centavos(celdas["Débito"]));
      const credito = centavos(celdas["Crédito"]);
      movimientos.push({
        cuenta,
        fecha: fechaIso(celdas.Fecha),
        referencia: celdas.Referencia ?? "",
        descripcion: celdas["Descripción"] ?? "",
        monto: credito - debito, // + entra, − sale
        saldo: centavos(celdas.Total),
      });
    }
  }
  if (!cols)
    throw new ErrorLector(
      "estado de cuenta: no encontré la fila de títulos",
      COLUMNAS_BANCO_PDF,
    );
  return movimientos;
}

/** Columnas del estado de cuenta a partir de su fila de títulos. */
function columnasBanco(titulos: Pieza[]) {
  const faltan = COLUMNAS_BANCO_PDF.filter(
    (c) => !titulos.some((p) => norm(p.t) === norm(c)),
  );
  if (faltan.length)
    throw new ErrorLector(
      `estado de cuenta: faltan las columnas ${faltan.join(", ")}`,
      faltan,
    );
  // Centro de cada título: los montos vienen alineados a la derecha, así que se asigna por cercanía.
  return COLUMNAS_BANCO_PDF.map((c) => {
    const p = titulos.find((x) => norm(x.t) === norm(c))!;
    return { c, x0: p.x, centro: p.x + (p.ancho ?? 0) / 2 };
  });
}

// ---------- Cuenta de ahorros en PDF (KF-32) ----------
// El estado real de las cuentas de casa trae «Fecha | Descripción | Monto |
// Saldo total», sin Referencia ni Débito/Crédito. Cuando la descripción no
// cabe en una línea, el banco la parte arriba y abajo de la línea con la
// fecha. Lector aparte: el de banco sigue rechazando este formato (KF-30).
export const COLUMNAS_AHORRO_PDF = [
  "Fecha",
  "Descripción",
  "Monto",
  "Saldo total",
];

/** «$1,234.56», «-$45.00», «45.00-», «.50». */
const RE_MONTO_PDF = /^-?\$?-?[\d,]*\.\d{2}-?$/;

/** Monto como viene impreso, con el signo delante o detrás, en centavos. */
function montoImpreso(t: string): number {
  const negativo = t.startsWith("-") || t.endsWith("-");
  const c = Math.abs(centavos(t.replace(/-/g, "")));
  return negativo ? 0 - c : c;
}

const centro = (p: Pieza) => p.x + (p.ancho ?? 0) / 2;
const masCerca = <T extends { centro: number }>(cols: T[], p: Pieza) =>
  cols.reduce((a, b) =>
    Math.abs(b.centro - centro(p)) < Math.abs(a.centro - centro(p)) ? b : a,
  );

export function leerAhorroPdf(paginas: Paginas, cuenta: string): Movimiento[] {
  const movimientos: Movimiento[] = [];
  let vioTitulos = false;
  for (const filas of paginas) {
    const iTitulos = filas.findIndex(
      (f) =>
        f.piezas.some((p) => norm(p.t) === "fecha") &&
        f.piezas.some((p) => norm(p.t) === "saldo total"),
    );
    if (iTitulos < 0) continue;
    vioTitulos = true;
    const titulos = filas[iTitulos].piezas;
    const faltan = COLUMNAS_AHORRO_PDF.filter(
      (c) => !titulos.some((p) => norm(p.t) === norm(c)),
    );
    if (faltan.length)
      throw new ErrorLector(
        `cuenta de ahorros: faltan las columnas ${faltan.join(", ")}`,
        faltan,
      );
    const col = (c: string) => titulos.find((p) => norm(p.t) === norm(c))!;
    const xDesc = col("Descripción").x;
    const montos = [
      { c: "monto", centro: centro(col("Monto")) },
      { c: "saldo", centro: centro(col("Saldo total")) },
    ];
    const conFecha: {
      y: number;
      mov: Movimiento;
      partes: [number, string][];
    }[] = [];
    const sueltas: { y: number; texto: string }[] = [];
    for (const f of filas.slice(iTitulos + 1)) {
      const [p0] = f.piezas;
      if (RE_FECHA.test(p0.t)) {
        const celdas: Record<string, string> = {};
        const desc: string[] = [];
        for (const p of f.piezas.slice(1)) {
          if (RE_MONTO_PDF.test(p.t)) celdas[masCerca(montos, p).c] = p.t;
          else desc.push(p.t);
        }
        if (celdas.monto === undefined) continue;
        conFecha.push({
          y: f.y,
          partes: desc.length ? [[f.y, desc.join(" ")]] : [],
          mov: {
            cuenta,
            fecha: fechaIso(p0.t),
            referencia: "",
            descripcion: "",
            monto: montoImpreso(celdas.monto),
            saldo: montoImpreso(celdas.saldo ?? ""),
          },
        });
      } else if (
        f.piezas.every((p) => p.x >= xDesc - 3 && !RE_MONTO_PDF.test(p.t))
      )
        sueltas.push({ y: f.y, texto: f.texto });
    }
    // Cada línea suelta va con la línea de fecha más cercana que no trae
    // descripción propia (arriba o abajo).
    const sinDesc = conFecha.filter((c) => !c.partes.length);
    for (const s of sueltas) {
      if (!sinDesc.length) break;
      const c = sinDesc.reduce((a, b) =>
        Math.abs(b.y - s.y) < Math.abs(a.y - s.y) ? b : a,
      );
      c.partes.push([s.y, s.texto]);
    }
    for (const c of conFecha) {
      c.mov.descripcion = c.partes
        .sort((a, b) => b[0] - a[0])
        .map(([, t]) => t)
        .join(" ");
      if (c.mov.monto !== 0) movimientos.push(c.mov);
    }
  }
  if (!vioTitulos)
    throw new ErrorLector(
      "cuenta de ahorros: no encontré la fila de títulos",
      COLUMNAS_AHORRO_PDF,
    );
  return movimientos;
}

// ---------- Tarjeta de crédito en PDF (KF-32) ----------
// Seis formatos reales: cada uno trae Fecha, Descripción y el monto en una
// columna «Monto» o en dos, «Cargos» y «Pagos». Se lee por la fila de
// títulos más reciente, como el estado de banco. Signo del Movimiento:
// cargo −, pago a la tarjeta + (igual que leerTarjetaExcel).
//  - «Monto» con columna «Categoría»: el banco imprime el cargo con «-».
//  - «Monto» sin «Categoría»: el cargo va sin signo y el pago con «-»
//    (delante o detrás).
//  - «Cargos» / «Pagos»: la columna dice cuál es.
// Fechas: «6/AGO/2026», «06-ago-2026», «06/08/2026» o sin año («06/08»);
// sin año, el orden día/mes sale del propio estado y el año de su última
// fecha completa. Si hay fecha de transacción y de proceso, vale la de
// transacción.
export const COLUMNAS_TARJETA_PDF = ["Fecha", "Descripción", "Monto"];

const MESES_PDF = [
  "ene",
  "feb",
  "mar",
  "abr",
  "may",
  "jun",
  "jul",
  "ago",
  "sep",
  "oct",
  "nov",
  "dic",
];
const RE_FECHA_TARJETA = /^(\d{1,2})[/-]([a-z]{3}|\d{1,2})(?:[/-](\d{4}))?$/i;
const RE_FECHA_COMPLETA = /\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/g;

type ColumnasTarjeta = {
  fechas: number[];
  transaccion: number | null;
  montos: { c: "monto" | "cargos" | "pagos"; centro: number }[];
  cargoImpreso: boolean;
};

function titulosTarjeta(filas: Fila[], i: number): ColumnasTarjeta | null {
  const zona = filas.slice(Math.max(0, i - 1), i + 2).flatMap((f) => f.piezas);
  const propias = filas[i].piezas;
  if (!propias.some((p) => /^fecha/.test(norm(p.t)))) return null;
  if (!zona.some((p) => norm(p.t).startsWith("descripci"))) return null;
  const montos = zona
    .filter((p) => ["monto", "cargos", "pagos"].includes(norm(p.t)))
    .map((p) => ({
      c: norm(p.t) as "monto" | "cargos" | "pagos",
      centro: centro(p),
    }));
  if (!montos.length) return null;
  const tr = zona.find((p) =>
    /^(transaccion|fecha transaccion)/.test(norm(p.t)),
  );
  return {
    fechas: propias.filter((p) => /^fecha/.test(norm(p.t))).map((p) => p.x),
    transaccion: tr ? tr.x : null,
    montos,
    cargoImpreso: zona.some((p) => norm(p.t) === "categoria"),
  };
}

export function leerTarjetaPdf(paginas: Paginas, cuenta: string): Movimiento[] {
  const filas = paginas.flat();
  // Año y orden día/mes de las fechas sin año.
  const completas = filas
    .flatMap((f) => [...f.texto.matchAll(RE_FECHA_COMPLETA)])
    .map((m) => `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`)
    .filter((f) => Number(f.slice(5, 7)) <= 12)
    .sort();
  const ultima = completas.at(-1) ?? null;
  // Solo lo que puede ser fecha: «36/60» es la cuota 36 de 60, no una fecha.
  const sinAnio = filas
    .map((f) => f.piezas[0]?.t.match(/^(\d{1,2})\/(\d{1,2})$/))
    .filter(
      (m): m is RegExpMatchArray =>
        !!m && Number(m[1]) <= 31 && Number(m[2]) <= 31,
    );
  const mesPrimero =
    sinAnio.some((m) => Number(m[2]) > 12) &&
    !sinAnio.some((m) => Number(m[1]) > 12);

  const fecha = (t: string): string | null => {
    const m = t.match(RE_FECHA_TARJETA);
    if (!m) return null;
    let dia = Number(m[1]);
    let mes = /\d/.test(m[2])
      ? Number(m[2])
      : MESES_PDF.indexOf(m[2].toLowerCase()) + 1;
    if (!m[3] && mesPrimero) [dia, mes] = [mes, dia];
    if (mes < 1 || mes > 12 || dia < 1 || dia > 31) return null;
    const md = `${String(mes).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
    if (m[3]) return `${m[3]}-${md}`;
    if (!ultima) return null;
    const anio = Number(ultima.slice(0, 4));
    return `${anio}-${md}` > ultima ? `${anio - 1}-${md}` : `${anio}-${md}`;
  };

  // Fecha de corte: la de la fila «Fecha de corte».
  const corte = (() => {
    const f = filas.find((x) =>
      x.piezas.some((p) => norm(p.t) === "fecha de corte"),
    );
    const m = f && [...f.texto.matchAll(RE_FECHA_COMPLETA)][0];
    return m
      ? `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`
      : null;
  })();

  const movimientos: Movimiento[] = [];
  let cols: ColumnasTarjeta | null = null;
  // Tabla del plan de intra/extrafinanciamiento con «MONTO DE CUOTA»: la cuota
  // del mes no sale como movimiento; se carga en la fecha de corte.
  let cuotaPlan: number | null = null;
  filas.forEach((f, i) => {
    const t = titulosTarjeta(filas, i);
    if (t) {
      cols = t;
      cuotaPlan = null;
      return;
    }
    const montoDe = f.piezas.find((p) => norm(p.t) === "monto de");
    if (montoDe && f.piezas.some((p) => norm(p.t) === "saldo")) {
      cuotaPlan = centro(montoDe);
      return;
    }
    if (cuotaPlan !== null && corte && /^[IE]$/.test(f.piezas[0]?.t ?? "")) {
      const nums = f.piezas.filter((p) => RE_MONTO_PDF.test(p.t));
      if (!nums.length) return;
      const x = cuotaPlan;
      const p = nums.reduce((a, b) =>
        Math.abs(centro(b) - x) < Math.abs(centro(a) - x) ? b : a,
      );
      const cuota = Math.abs(montoImpreso(p.t));
      if (cuota)
        movimientos.push({
          cuenta,
          fecha: corte,
          referencia: f.piezas.find((q) => /^\d{5,}$/.test(q.t))?.t ?? "",
          descripcion: `CUOTA PLAN ${f.piezas[1]?.t ?? ""}`.trim(),
          monto: 0 - cuota,
        });
      return;
    }
    if (!cols) return;
    const c: ColumnasTarjeta = cols;
    const fechas = f.piezas.filter(
      (p) => fecha(p.t) && c.fechas.some((x) => Math.abs(x - p.x) <= 25),
    );
    if (!fechas.length || f.piezas[0] !== fechas[0]) return;
    const usar =
      c.transaccion !== null && fechas.length > 1
        ? fechas.reduce((a, b) =>
            Math.abs(b.x - c.transaccion!) < Math.abs(a.x - c.transaccion!)
              ? b
              : a,
          )
        : fechas[0];
    let monto = 0;
    let vioMonto = false;
    const desc: string[] = [];
    for (const p of f.piezas) {
      if (fechas.includes(p)) continue;
      if (!RE_MONTO_PDF.test(p.t)) {
        if (!/^\d+$/.test(p.t)) desc.push(p.t);
        continue;
      }
      vioMonto = true;
      const v = montoImpreso(p.t);
      const col = masCerca(c.montos, p).c;
      if (col === "cargos") monto -= Math.abs(v);
      else if (col === "pagos") monto += Math.abs(v);
      else if (c.cargoImpreso) monto += v;
      else monto += v < 0 ? Math.abs(v) : 0 - v;
    }
    if (!vioMonto || monto === 0) return;
    // Banesco marca con «*» lo que ya está dentro del pago («El monto ya está
    // considerado en el total de su pago»): no es un movimiento nuevo.
    if (desc.at(-1)?.endsWith("*")) return;
    movimientos.push({
      cuenta,
      fecha: fecha(usar.t)!,
      referencia: f.piezas.find((p) => /^\d{5,}$/.test(p.t))?.t ?? "",
      descripcion: desc.join(" "),
      monto,
    });
  });
  if (!movimientos.length)
    throw new ErrorLector(
      "tarjeta: no encontré movimientos con Fecha, Descripción y Monto (o Cargos y Pagos)",
      COLUMNAS_TARJETA_PDF,
    );
  return movimientos;
}

// ---------- Factura electrónica DGI en PDF ---------- prototipo/src/lectores.mjs:53-88
// KF-30: el comprobante auxiliar real de la DGI dice «Número:», «Cliente:»,
// «Valor Total 1,984.85» (sin B/.) y pone «RUC:» en la línea debajo de
// «Emisor:» (la primera línea que empieza con «RUC:»; la del cliente es
// «RUC/Cédula/Pasaporte:»). «Tipo de Receptor:» no es el cliente.
const CAMPOS_FACTURA: Record<string, RegExp> = {
  numero: /(?:No\.?\s*(?:de\s*)?Factura|^N[úu]mero)\s*:?\s*0*(\d+)/i,
  ruc_emisor:
    /(?:RUC\s*(?:del\s*)?Emisor|^RUC)\s*:?\s*([\d-]+(?:\s*DV\s*\d+)?)/i,
  receptor: /^(?:Receptor|Cliente)\s*:?\s*(.+)/i,
  fecha: /Fecha\s*de\s*Emisi[oó]n\s*:?\s*(\d{1,2}\/\d{1,2}\/\d{4})/i,
  total:
    /(?:\bTotal\s*(?:a\s*pagar)?\s*:?\s*B\/\.|^Valor\s+Total\s*:?)\s*([\d,]+\.\d{2})/i,
};

export function leerFacturaDgi(paginas: Paginas, empresas: Empresa[]): Factura {
  const lineas = paginas.flat().map((f) => f.texto);
  const datos: Record<string, string> = {};
  const faltan: string[] = [];
  for (const [campo, re] of Object.entries(CAMPOS_FACTURA)) {
    const linea = lineas.find((l) => re.test(l));
    if (!linea) faltan.push(campo);
    else datos[campo] = linea.match(re)![1].trim();
  }
  if (faltan.length)
    throw new ErrorLector(
      `factura DGI: no encontré ${faltan.join(", ")}`,
      faltan,
    );
  // «Vencimiento: 31/10/2026», o (DGI real, pago a plazo) la tabla
  // «Cuota | Fecha de Vencimiento | Valor» con la fecha en la fila siguiente.
  const iTabla = lineas.findIndex((l) => /Fecha\s*de\s*Vencimiento/i.test(l));
  const vence =
    lineas
      .map((l) => l.match(/Vencimiento\s*:?\s*(\d{1,2}\/\d{1,2}\/\d{4})/i))
      .find(Boolean) ??
    (iTabla < 0
      ? undefined
      : lineas
          .slice(iTabla + 1)
          .map((l) => l.match(/\b(\d{1,2}\/\d{1,2}\/\d{4})\b/))
          .find(Boolean));
  const fecha = fechaIso(datos.fecha);
  const rucLimpio = datos.ruc_emisor.replace(/\s*DV.*/i, "");
  const empresa = empresas.find((e) => e.ruc === rucLimpio);
  if (!empresa) {
    // c1-r-empresas (error): no se mezcla con otra empresa.
    throw new ErrorLector(
      `factura ${datos.numero}: el RUC emisor ${rucLimpio} no es de ninguna empresa configurada`,
      ["empresa"],
    );
  }
  return {
    empresa: empresa.nombre,
    numero: datos.numero.padStart(4, "0"),
    cliente: datos.receptor,
    fecha,
    vence: vence ? fechaIso(vence[1]) : sumarDias(fecha, 30),
    total: centavos(datos.total),
  };
}

// ---------- Excel (SheetJS inyectado) ---------- prototipo/src/lectores.mjs:90-106
/**
 * Primera hoja: busca la fila de títulos y rechaza nombrando las columnas que
 * faltan. Devuelve los títulos tal cual y las filas con algún dato debajo.
 * KF-15 la exporta para el Excel PRESUPUESTO (categorías en columnas).
 */
export function tablaExcelCruda(
  XLSX: XLSX,
  bytes: Uint8Array,
  requeridas: string[],
  nombre: string,
): { titulos: unknown[]; filas: unknown[][] } {
  const libro = XLSX.read(bytes, { type: "array", cellDates: true });
  const hoja = libro.Sheets[libro.SheetNames[0]];
  const filas = XLSX.utils.sheet_to_json<unknown[]>(hoja, {
    header: 1,
    raw: true,
    defval: "",
  });
  const iTitulos = filas
    .slice(0, 15)
    .findIndex((f) =>
      requeridas.some((c) => f.some((v) => norm(v) === norm(c))),
    );
  if (iTitulos < 0)
    throw new ErrorLector(
      `${nombre}: no encontré la fila de títulos`,
      requeridas,
    );
  const titulos = filas[iTitulos];
  const normales = titulos.map(norm);
  const faltan = requeridas.filter((c) => !normales.includes(norm(c)));
  if (faltan.length)
    throw new ErrorLector(
      `${nombre}: faltan las columnas ${faltan.join(", ")}`,
      faltan,
    );
  return {
    titulos,
    filas: filas.slice(iTitulos + 1).filter((f) => f.some((v) => v !== "")),
  };
}

function tablaExcel(
  XLSX: XLSX,
  bytes: Uint8Array,
  requeridas: string[],
  nombre: string,
): Record<string, unknown>[] {
  const { titulos, filas } = tablaExcelCruda(XLSX, bytes, requeridas, nombre);
  const normales = titulos.map(norm);
  return filas.map((f) =>
    Object.fromEntries(
      requeridas.map((c) => [c, f[normales.indexOf(norm(c))]]),
    ),
  );
}

export const fechaCelda = (v: unknown) =>
  v instanceof Date ? v.toISOString().slice(0, 10) : fechaIso(v);

// prototipo/src/lectores.mjs:108-118
export const COLUMNAS_AHORRO = [
  "Fecha",
  "Referencia",
  "Descripción",
  "Monto",
  "Saldo total",
];
export function leerAhorroExcel(
  XLSX: XLSX,
  bytes: Uint8Array,
  cuenta: string,
): Movimiento[] {
  return tablaExcel(XLSX, bytes, COLUMNAS_AHORRO, "cuenta de ahorro").map(
    (r) => ({
      cuenta,
      fecha: fechaCelda(r.Fecha),
      referencia: String(r.Referencia),
      descripcion: String(r["Descripción"]),
      monto: centavos(r.Monto),
      saldo: centavos(r["Saldo total"]),
    }),
  );
}

// prototipo/src/lectores.mjs:120-131
export const COLUMNAS_TARJETA = [
  "Cuenta",
  "Tarjeta",
  "Fecha transacción",
  "Fecha proceso",
  "Descripción",
  "Referencia",
  "Categoría",
  "Cargos",
];
export function leerTarjetaExcel(
  XLSX: XLSX,
  bytes: Uint8Array,
  cuenta: string,
): Movimiento[] {
  return tablaExcel(XLSX, bytes, COLUMNAS_TARJETA, "tarjeta").map((r) => ({
    cuenta,
    fecha: fechaCelda(r["Fecha transacción"]),
    referencia: String(r.Referencia),
    descripcion: String(r["Descripción"]),
    categoria_banco: String(r["Categoría"]),
    // En la tarjeta un cargo es salida (positivo en el Excel); un pago recibido viene negativo.
    // 0 - x y no -x: un cargo de 0 no da -0.
    monto: 0 - centavos(r.Cargos),
  }));
}
