import { cn } from "@/lib/utils";
import {
  BookOpen,
  Home,
  Menu,
  NotebookPen,
  Users,
  type LucideIcon,
} from "lucide-react";
import { Link, useLocation } from "react-router";

import { entradaActivaBarra, SECCIONES_BARRA } from "./secciones";

// Yunque 8 · KF-06 · c2-cel-barra: barra inferior de la maqueta CelMas.
const ICONOS: Record<string, LucideIcon> = {
  Hoy: Home,
  Clientes: Users,
  Minuta: NotebookPen,
  Lecciones: BookOpen,
  Más: Menu,
};

export const MobileNavigation = () => {
  const location = useLocation();
  const activa = entradaActivaBarra(location.pathname);

  // Check if the app is running as a PWA (standalone mode)
  const isPwa = window.matchMedia("(display-mode: standalone)").matches;
  // Check if it's iOS on the web
  const isWebiOS = /iPad|iPod|iPhone/.test(window.navigator.userAgent);

  return (
    <nav
      aria-label="Secciones"
      className="fixed bottom-0 left-0 right-0 z-50 bg-secondary border-t grid grid-cols-5"
      style={{
        // iOS bug: even though viewport is set correctly, the bottom safe area inset is not accounted for
        // So we manually add some padding to avoid the navigation being too close to the home bar
        paddingBottom: isPwa && isWebiOS ? 15 : undefined,
      }}
    >
      {SECCIONES_BARRA.map((s) => {
        const Icon = ICONOS[s.nombre];
        const isActive = activa === s.nombre;
        return (
          <Link
            key={s.ruta}
            to={s.ruta}
            aria-current={isActive ? "page" : undefined}
            className={cn(
              "flex flex-col items-center justify-center gap-0.5 min-h-14 text-xs no-underline",
              isActive
                ? "text-primary font-semibold"
                : "text-muted-foreground font-medium",
            )}
          >
            <Icon aria-hidden="true" className="size-5" />
            <span>{s.nombre}</span>
          </Link>
        );
      })}
    </nav>
  );
};
