// Kaizen Files · KF-13 · c1-r-cobros (R010–R012).
// Copiado de prototipo/src/cruce.mjs:1-58: cruce de facturas con el estado de
// cuenta de la empresa. Montos en centavos enteros (comun.ts, KF-12).
// Cambios frente al prototipo:
// - Cada factura arranca con lo que ya tenía pagado (`pagado`), no en 0: así
//   leer el banco de noviembre no borra lo cruzado en octubre.
// - Estados de P3 y P4 (Puerta 3, hoy): con abono y vencida queda «parcial»;
//   sin pago y sin vencer queda «pendiente». «Vencida» no se guarda (la tabla
//   facturas no la tiene): se calcula al mostrar con `estadoVisible`.
import { norm } from "./comun";

export type FacturaCruce = {
  empresa: string;
  numero: string;
  cliente: string;
  vence: string;
  /** Centavos. */
  total: number;
  /** Centavos ya pagados antes de este cruce. */
  pagado?: number;
};

export type MovimientoCruce = {
  cuenta?: string;
  fecha: string;
  referencia: string;
  descripcion: string;
  /** Centavos: + entra, − sale. Solo cuentan las entradas. */
  monto: number;
};

export type PagoCruce = {
  cuenta?: string;
  fecha: string;
  monto: number;
  referencia: string;
};

export type EstadoCruce =
  | "sin cruzar"
  | "pagada"
  | "parcial"
  | "vencida"
  | "pendiente";

export type Cruzada<F extends FacturaCruce> = F & {
  pagado: number;
  /** Solo los pagos de este cruce. */
  pagos: PagoCruce[];
  revisar: boolean;
  estado: EstadoCruce;
};

export type SinAsignar = MovimientoCruce & { empresa: string; nota?: string };

// prototipo/src/cruce.mjs:4-5
const RUIDO = new Set([
  "sa",
  "s.a.",
  "s",
  "a",
  "de",
  "la",
  "el",
  "y",
  "inc",
  "corp",
  "pago",
  "ach",
  "transf",
]);
const palabras = (s: unknown) =>
  norm(s)
    .replace(/[^a-z0-9 ]/g, " ")
    .split(" ")
    .filter((w) => w.length > 1 && !RUIDO.has(w));

/**
 * El cliente aparece en el texto si sus dos primeras palabras significativas están.
 * prototipo/src/cruce.mjs:7-12
 */
export function mencionaCliente(texto: string, cliente: string): boolean {
  const d = new Set(palabras(texto));
  const c = palabras(cliente).slice(0, 2);
  return c.length > 0 && c.every((w) => d.has(w));
}

// prototipo/src/cruce.mjs:14-17
function facturasCitadas<F extends { numero: string }>(
  texto: string,
  abiertas: F[],
): F[] {
  const nums = [...String(texto).matchAll(/\b0*(\d{2,10})\b/g)].map(
    (m) => m[1],
  );
  return abiertas.filter((f) => nums.includes(String(Number(f.numero))));
}

/**
 * prototipo/src/cruce.mjs:19-58
 * @param movimientos por empresa: { [empresa]: Movimiento[] }
 * @param hoy reloj inyectable → "YYYY-MM-DD"
 */
export function cruzar<F extends FacturaCruce>(
  facturas: F[],
  movimientos: Record<string, MovimientoCruce[]>,
  hoy: () => string,
): { facturas: Cruzada<F>[]; sinAsignar: SinAsignar[] } {
  const fs: Cruzada<F>[] = facturas.map((f) => ({
    ...f,
    pagado: f.pagado ?? 0,
    pagos: [],
    revisar: false,
    estado: "pendiente",
  }));
  const sinAsignar: SinAsignar[] = [];
  for (const [empresa, movs] of Object.entries(movimientos)) {
    // Por vencimiento: el pago va primero a la que vence antes (R011).
    const deEmpresa = fs
      .filter((f) => f.empresa === empresa)
      .sort((a, b) => a.vence.localeCompare(b.vence));
    const entradas = movs
      .filter((x) => x.monto > 0)
      .sort((a, b) => a.fecha.localeCompare(b.fecha));
    for (const m of entradas) {
      const abiertas = deEmpresa.filter((f) => f.pagado < f.total);
      const texto = `${m.referencia} ${m.descripcion}`;
      let destino = facturasCitadas(texto, abiertas);
      if (!destino.length) {
        const delCliente = abiertas.filter((f) =>
          mencionaCliente(texto, f.cliente),
        );
        const exacta = delCliente.find((f) => f.total - f.pagado === m.monto);
        destino = exacta ? [exacta] : delCliente;
      }
      if (!destino.length) {
        sinAsignar.push({ empresa, ...m });
        continue;
      }
      let resto = m.monto;
      for (const f of destino) {
        if (resto <= 0) break;
        const aplica = Math.min(resto, f.total - f.pagado);
        f.pagado += aplica;
        f.pagos.push({
          cuenta: m.cuenta,
          fecha: m.fecha,
          monto: aplica,
          referencia: m.referencia,
        });
        resto -= aplica;
        if (destino.length > 1) f.revisar = true; // un pago repartido en varias facturas se revisa
      }
      if (resto > 0)
        sinAsignar.push({
          empresa,
          ...m,
          monto: resto,
          nota: "sobrante del pago",
        });
    }
  }
  const conCuenta = new Set(Object.keys(movimientos));
  for (const f of fs) {
    if (!conCuenta.has(f.empresa)) f.estado = "sin cruzar";
    else if (f.pagado >= f.total) f.estado = "pagada";
    else if (f.pagado > 0) f.estado = "parcial";
    else if (f.vence < hoy()) f.estado = "vencida";
    else f.estado = "pendiente";
  }
  return { facturas: fs, sinAsignar };
}

/** Valores de la columna facturas.estado (KF-03). */
export type EstadoGuardado =
  | "pendiente"
  | "parcial"
  | "pagada"
  | "revisar"
  | "sin_cruzar";

/** Estado que se guarda: «revisar» manda; «vencida» se guarda como «pendiente». */
export function estadoGuardado(f: {
  estado: EstadoCruce;
  revisar: boolean;
}): EstadoGuardado {
  if (f.revisar) return "revisar";
  if (f.estado === "sin cruzar") return "sin_cruzar";
  if (f.estado === "vencida") return "pendiente";
  return f.estado;
}

/** Lo que ve Cesar: una pendiente sin pago y con el vencimiento pasado es «Vencida». */
export function estadoVisible(
  f: { estado?: string | null; vence?: string | null; pagado?: number },
  hoy: string,
): string {
  const e = f.estado ?? "pendiente";
  if (e === "pendiente" && !f.pagado && f.vence && f.vence < hoy)
    return "Vencida";
  return (
    {
      pendiente: "Pendiente",
      parcial: "Parcial",
      pagada: "Pagada",
      revisar: "Revisar",
      sin_cruzar: "Sin cruzar",
    }[e] ?? e
  );
}
