// Kaizen Files · KF-16 · c1-r-presupuesto, c2-presupuesto-mes/-resumen/
// -categorias/-clasificar (R040–R042, R059).
// Pasa las tablas (cuentas, movimientos, categorias, reglas_categoria,
// presupuestos) a lo que piden clasificar() y resumenMes() de
// kaizen/lectores/presupuesto.ts (KF-15). Aquí no se empareja nada ni se
// decide qué es neutro: eso lo hace presupuesto.ts.
import {
  clasificar,
  resumenMes,
  type Clasificado,
  type Cuenta,
  type Fijo,
  type Regla,
  type ReglaIngreso,
} from "../../../kaizen/lectores/presupuesto";

export type Vista = "todo" | "casa" | "empresa";
export type Ambito = Cuenta["ambito"];

export type CuentaFila = {
  id: number | string;
  nombre?: string;
  dueno: string;
  tipo: string;
  /** KF-14: la empresa dueña de la cuenta, por su RUC. */
  empresa_ruc?: string | null;
};
export type MovimientoFila = {
  id: number | string;
  cuenta_id: number | string;
  fecha: string;
  referencia?: string | null;
  descripcion?: string | null;
  debito_centavos?: number | null;
  credito_centavos?: number | null;
  categoria_id?: number | string | null;
  estado?: "por_clasificar" | "clasificado" | "transferencia_interna" | null;
};
export type CategoriaFila = {
  id: number | string;
  nombre: string;
  ambito: Ambito;
};
export type ReglaFila = {
  id: number | string;
  patron: string;
  categoria_id: number | string;
};
export type PresupuestoFila = {
  mes: string;
  categoria_id: number | string;
  tope_centavos: number;
};
/** KF-17: tabla pagos_fijos (KF-03). */
export type PagoFijoFila = {
  id: number | string;
  nombre: string;
  dia_mes: number | null;
  monto_centavos: number;
  cuenta_id?: number | string | null;
  categoria_id?: number | string | null;
};

/**
 * KF-17 · «De dónde entró» (c2-presupuesto-ingresos): transferencias de las
 * empresas (las empareja presupuesto.ts), alquileres por patrón y el resto
 * «otros». No hay tabla de reglas de ingreso en KF-03: la regla es fija.
 */
export const INGRESOS: ReglaIngreso[] = [
  { patron: "ALQUILER", origen: "alquileres" },
];

/** «transferencia de DPB» → «Transferencia de DPB». */
export const nombreOrigen = (o: string) =>
  o.charAt(0).toUpperCase() + o.slice(1);

/** Empresa si la cuenta está ligada a una empresa por el RUC o es de DPB; si no, casa. */
export const ambitoDe = (c: CuentaFila): Ambito =>
  c.empresa_ruc || c.dueno === "DPB" ? "empresa" : "casa";

/** La cuenta de la tabla en la forma de presupuesto.ts. */
const cuentaP = (c: CuentaFila): Cuenta => ({
  id: String(c.id),
  titular: c.dueno,
  ambito: ambitoDe(c),
  clase: c.tipo === "tarjeta" ? "tarjeta" : "cuenta",
});

export const GRUPO: Record<Ambito, string> = {
  casa: "Casa",
  empresa: "Empresa",
};

const MESES = [
  "enero",
  "febrero",
  "marzo",
  "abril",
  "mayo",
  "junio",
  "julio",
  "agosto",
  "septiembre",
  "octubre",
  "noviembre",
  "diciembre",
];
/** "2026-11" → "noviembre 2026". */
export const nombreMes = (mes: string) =>
  `${MESES[Number(mes.slice(5, 7)) - 1]} ${mes.slice(0, 4)}`;

/** Meses con movimientos, del más nuevo al más viejo; sin movimientos, el de hoy. */
export const mesesDe = (movs: MovimientoFila[], hoy: string) => {
  const meses = [...new Set(movs.map((m) => m.fecha.slice(0, 7)))].sort(
    (a, b) => b.localeCompare(a),
  );
  return meses.length ? meses : [hoy.slice(0, 7)];
};

/** «XYZ COMERCIO 123» → «XYZ COMERCIO»: sin los números sueltos del final. */
export const patronDe = (descripcion: string) => {
  const palabras = descripcion.trim().split(/\s+/);
  while (palabras.length > 1 && /\d/.test(palabras[palabras.length - 1]))
    palabras.pop();
  return palabras.join(" ");
};

/** El tope de cada categoría para el mes: el de ese mes o el último anterior. */
export const topesDelMes = (
  presupuestos: PresupuestoFila[],
  mes: string,
): Map<string, number> => {
  const inicio = `${mes}-01`;
  const tope = new Map<string, { mes: string; tope: number }>();
  for (const p of presupuestos) {
    const desde = String(p.mes).slice(0, 10);
    const id = String(p.categoria_id);
    if (desde > inicio) continue;
    const previo = tope.get(id);
    if (!previo || desde > previo.mes)
      tope.set(id, { mes: desde, tope: p.tope_centavos });
  }
  return new Map([...tope].map(([id, t]) => [id, t.tope]));
};

export type Datos = {
  cuentas: CuentaFila[];
  movimientos: MovimientoFila[];
  categorias: CategoriaFila[];
  reglas: ReglaFila[];
  presupuestos: PresupuestoFila[];
  /** KF-17: opcional para que KF-16 siga igual. */
  fijos?: PagoFijoFila[];
};

export type MovimientoVisto = Clasificado & { fila: MovimientoFila };

/** Clasifica todos los movimientos con presupuesto.ts y aplica lo que Cesar eligió a mano. */
export function clasificarTablas({
  cuentas,
  movimientos,
  categorias,
  reglas,
}: Omit<Datos, "presupuestos" | "fijos">): MovimientoVisto[] {
  const cats = new Map(categorias.map((c) => [String(c.id), c]));
  const reglasP: Regla[] = reglas.flatMap((r) => {
    const c = cats.get(String(r.categoria_id));
    return c
      ? [{ patron: r.patron, categoria: c.nombre, grupo: GRUPO[c.ambito] }]
      : [];
  });
  const cuentasP = cuentas.map(cuentaP);
  const clasificados = clasificar(
    movimientos.map((m) => ({
      cuenta: String(m.cuenta_id),
      fecha: String(m.fecha).slice(0, 10),
      referencia: m.referencia ?? String(m.id),
      descripcion: m.descripcion ?? "",
      monto: (m.credito_centavos ?? 0) - (m.debito_centavos ?? 0),
    })),
    cuentasP,
    reglasP,
    INGRESOS,
  );
  return clasificados.map((m) => {
    const fila = movimientos[m.i];
    // Lo elegido a mano solo cambia un gasto o un «por clasificar»: los pares
    // entre cuentas propias los decide presupuesto.ts.
    if (m.tipo === "por clasificar" || m.tipo === "gasto") {
      const c = cats.get(String(fila.categoria_id));
      if (fila.estado === "clasificado" && c)
        return {
          ...m,
          fila,
          tipo: "gasto",
          categoria: c.nombre,
          grupo: GRUPO[c.ambito],
        };
      if (fila.estado === "transferencia_interna" && m.monto < 0)
        return { ...m, fila, tipo: "entre mis cuentas" };
    }
    return { ...m, fila };
  });
}

/** Resumen del mes en la vista pedida, con resumenMes() de presupuesto.ts. */
export function verMes(
  datos: Datos,
  { mes, vista, hoy }: { mes: string; vista: Vista; hoy: string },
) {
  const ms = clasificarTablas(datos);
  const topes = topesDelMes(datos.presupuestos, mes);
  const visibles = [...datos.categorias]
    .filter((c) => vista === "todo" || c.ambito === vista)
    .sort((a, b) => Number(a.id) - Number(b.id));
  const presupuestos = Object.fromEntries(
    visibles.map((c) => [c.nombre, topes.get(String(c.id)) ?? 0]),
  );
  const porId = new Map(datos.cuentas.map((c) => [String(c.id), c]));
  // Pagos fijos de la vista: los de cuentas de ese ámbito. Uno sin cuenta
  // solo se ve en Todo (no puede quedar Pagado hasta que tenga cuenta).
  const filasFijas = (datos.fijos ?? []).filter((f) => {
    const c = f.cuenta_id == null ? undefined : porId.get(String(f.cuenta_id));
    return vista === "todo" || (!!c && ambitoDe(c) === vista);
  });
  const fijos: Fijo[] = filasFijas.map((f) => ({
    pago: f.nombre,
    dia: f.dia_mes ?? 1,
    cuenta: f.cuenta_id == null ? "" : String(f.cuenta_id),
  }));
  const r = resumenMes(ms, {
    mes,
    vista,
    cuentas: datos.cuentas.map(cuentaP),
    presupuestos,
    fijos,
    hoy: () => hoy,
  });
  const porClasificar = ms.filter(
    (m) =>
      m.tipo === "por clasificar" &&
      m.fecha.startsWith(mes) &&
      (vista === "todo" || ambitoDe(porId.get(m.cuenta)!) === vista),
  );
  const grupoDe = new Map(visibles.map((c) => [c.nombre, GRUPO[c.ambito]]));
  return {
    ...r,
    categorias: r.categorias.map((c) => ({
      ...c,
      grupo: grupoDe.get(c.categoria) ?? "",
    })),
    porClasificarLista: porClasificar,
    pagosFijos: r.pagosFijos.map((p, i) => ({
      ...p,
      fila: filasFijas[i],
      cuentaFila: porId.get(p.cuenta),
    })),
  };
}
