import { useState, type ReactNode } from "react";
import { Link } from "react-router";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { leerArchivo, type TipoArchivo } from "@/kaizen/lectores/archivo";
import { cargarLibrerias } from "@/kaizen/lectores/cargar";
import { centavos, norm } from "@/kaizen/lectores/comun";
import type { Movimiento } from "@/kaizen/lectores/lectores";
import type {
  SemillaFijo,
  SemillaPresupuesto,
} from "@/kaizen/lectores/presupuesto";
import { registrarEvento } from "../misc/eventos";
import { PuestaEnMarchaPage } from "../puesta/PuestaEnMarchaPage";
import {
  GRUPO,
  nombreMes,
  topesDelMes,
  type Ambito,
  type CategoriaFila,
  type CuentaFila,
  type MovimientoFila,
  type PagoFijoFila,
  type PresupuestoFila,
} from "./vistaPresupuesto";

type Accion = "leer" | "excel" | "editar" | null;

export type DatosAcciones = {
  mes: string;
  cuentas: CuentaFila[];
  categorias: CategoriaFila[];
  presupuestos: (PresupuestoFila & { id: number | string })[];
  fijos: PagoFijoFila[];
};

const claseSelect =
  "min-h-11 w-full rounded-md border bg-background px-2 text-sm";
const bytesDe = async (f: File) => new Uint8Array(await f.arrayBuffer());
const nombreCuenta = (c: CuentaFila) => c.nombre ?? c.dueno;
const plural = (n: number, uno: string, varios: string) =>
  `${n} ${n === 1 ? uno : varios}`;

/**
 * Al guardar se leen las tablas otra vez: lo que está en pantalla puede ser
 * de la caché, de antes de que termine de recargar.
 */
const todas = async <T,>(dp: DataProvider, recurso: string) =>
  (
    await dp.getList(recurso, {
      pagination: { page: 1, perPage: 10000 },
      sort: { field: "id", order: "ASC" },
      filter: {},
    })
  ).data as T[];

/** Tarjeta → Excel de tarjeta; cuenta: PDF del banco o Excel de ahorro. */
const tipoDe = (cuenta: CuentaFila, archivo: File): TipoArchivo =>
  cuenta.tipo === "tarjeta"
    ? "tarjeta-excel"
    : /\.pdf$/i.test(archivo.name)
      ? "banco-pdf"
      : "ahorro-excel";

/** La cuenta que nombra la lista de pagos fijos: por nombre, número final o id. */
const cuentaPorTexto = (cuentas: CuentaFila[], texto: string) => {
  const t = norm(texto);
  return cuentas.find(
    (c) =>
      norm(nombreCuenta(c)) === t ||
      String(c.id) === texto.trim() ||
      (!!(c as { numero_final?: string }).numero_final &&
        norm((c as { numero_final?: string }).numero_final) === t),
  );
};

export const AccionesPresupuesto = ({
  datos,
  alGuardar,
}: {
  datos: DatosAcciones;
  alGuardar: () => Promise<unknown>;
}) => {
  const [abierta, setAbierta] = useState<Accion>(null);
  const [aviso, setAviso] = useState<string | null>(null);

  const terminar = async (texto: string) => {
    await alGuardar();
    setAviso(texto);
    setAbierta(null);
  };

  return (
    <div className="flex flex-col gap-2">
      <div
        role="group"
        aria-label="Acciones"
        className="flex flex-wrap items-center gap-2"
      >
        <Button className="min-h-11" onClick={() => setAbierta("leer")}>
          Leer estados de cuenta
        </Button>
        <Button
          variant="outline"
          className="min-h-11"
          onClick={() => setAbierta("excel")}
        >
          Traer mi Excel
        </Button>
        <Button
          variant="outline"
          className="min-h-11"
          onClick={() => setAbierta("editar")}
        >
          Editar presupuesto
        </Button>
        <EnlaceCuentas />
      </div>
      {aviso ? (
        <p role="status" className="text-sm m-0">
          {aviso}
        </p>
      ) : null}

      {abierta === "leer" ? (
        <LeerEstados
          datos={datos}
          cerrar={() => setAbierta(null)}
          terminar={terminar}
        />
      ) : null}
      {abierta === "excel" ? (
        <TraerExcel
          datos={datos}
          cerrar={() => setAbierta(null)}
          terminar={terminar}
        />
      ) : null}
      {abierta === "editar" ? (
        <EditarPresupuesto
          datos={datos}
          cerrar={() => setAbierta(null)}
          terminar={terminar}
        />
      ) : null}
    </div>
  );
};

const EnlaceCuentas = () => (
  <Link
    to={PuestaEnMarchaPage.path}
    className="inline-flex items-center min-h-11 px-1 text-sm underline underline-offset-4"
  >
    Cuentas y tarjetas
  </Link>
);

/** Ventana común: título, cuerpo, error y Guardar / Cancelar. */
const Ventana = ({
  titulo,
  descripcion,
  cerrar,
  guardar,
  puedeGuardar,
  children,
}: {
  titulo: string;
  descripcion: string;
  cerrar: () => void;
  guardar: () => Promise<void>;
  puedeGuardar: boolean;
  children: ReactNode;
}) => {
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const alGuardar = async () => {
    setGuardando(true);
    setError(null);
    try {
      await guardar();
    } catch (e) {
      setError((e as Error).message);
      setGuardando(false);
    }
  };
  return (
    <Dialog open onOpenChange={(o) => (o ? null : cerrar())}>
      <DialogContent className="max-h-[90dvh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{titulo}</DialogTitle>
          <DialogDescription>{descripcion}</DialogDescription>
        </DialogHeader>
        <div className="flex flex-col gap-4">{children}</div>
        {error ? (
          <p role="alert" className="text-sm text-destructive m-0">
            No se guardó: {error}
          </p>
        ) : null}
        <DialogFooter>
          <Button variant="outline" className="min-h-11" onClick={cerrar}>
            Cancelar
          </Button>
          <Button
            className="min-h-11"
            disabled={!puedeGuardar || guardando}
            onClick={alGuardar}
          >
            Guardar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

const Campo = ({
  id,
  etiqueta,
  children,
}: {
  id: string;
  etiqueta: string;
  children: ReactNode;
}) => (
  <div className="flex flex-col gap-1.5 min-w-0">
    <Label htmlFor={id}>{etiqueta}</Label>
    {children}
  </div>
);

type PropsVentana = {
  datos: DatosAcciones;
  cerrar: () => void;
  terminar: (aviso: string) => Promise<void>;
};

/** Lee el archivo con su lector; si lo rechaza, el motivo sube a la ventana. */
async function leer(
  archivo: File,
  tipo: TipoArchivo,
  cuenta?: string,
): Promise<unknown> {
  const r = await leerArchivo(
    { nombre: archivo.name, tipo, bytes: await bytesDe(archivo), cuenta },
    { libs: await cargarLibrerias(), registrar: registrarEvento },
  );
  if (!r.ok) throw new Error(`${archivo.name}: ${r.motivo}`);
  return r.datos;
}

/** Guarda el tope de una categoría para el mes: cambia el del mes o lo crea. */
function useGuardarTope(datos: DatosAcciones) {
  const dp = useDataProvider();
  return async (categoriaId: number | string, tope: number) => {
    const inicio = `${datos.mes}-01`;
    const presupuestos = await todas<DatosAcciones["presupuestos"][number]>(
      dp,
      "presupuestos",
    );
    const previo = presupuestos.find(
      (p) =>
        String(p.mes).slice(0, 10) === inicio &&
        String(p.categoria_id) === String(categoriaId),
    );
    if (previo)
      await dp.update("presupuestos", {
        id: previo.id,
        data: { tope_centavos: tope },
        previousData: previo,
      });
    else
      await dp.create("presupuestos", {
        data: { mes: inicio, categoria_id: categoriaId, tope_centavos: tope },
      });
  };
}

// ---------- Leer estados de cuenta ----------

const LeerEstados = ({ datos, cerrar, terminar }: PropsVentana) => {
  const dp = useDataProvider();
  const { identity } = useGetIdentity();
  const [cuentaId, setCuentaId] = useState("");
  const [archivos, setArchivos] = useState<File[]>([]);
  const cuenta = datos.cuentas.find((c) => String(c.id) === cuentaId);

  const guardar = async () => {
    if (!cuenta) return;
    const movimientos = await todas<MovimientoFila>(dp, "movimientos");
    const vistos = new Set(
      movimientos
        .filter((m) => String(m.cuenta_id) === cuentaId)
        .map(
          (m) =>
            `${String(m.fecha).slice(0, 10)}|${norm(m.descripcion)}|${
              (m.credito_centavos ?? 0) - (m.debito_centavos ?? 0)
            }`,
        ),
    );
    let nuevos = 0;
    let repetidos = 0;
    for (const archivo of archivos) {
      const movs = (await leer(
        archivo,
        tipoDe(cuenta, archivo),
        cuentaId,
      )) as Movimiento[];
      for (const m of movs) {
        const clave = `${m.fecha}|${norm(m.descripcion)}|${m.monto}`;
        if (vistos.has(clave)) {
          repetidos++;
          continue;
        }
        vistos.add(clave);
        await dp.create("movimientos", {
          data: {
            cuenta_id: cuenta.id,
            fecha: m.fecha,
            referencia: m.referencia || null,
            descripcion: m.descripcion,
            debito_centavos: m.monto < 0 ? -m.monto : 0,
            credito_centavos: m.monto > 0 ? m.monto : 0,
            saldo_centavos: m.saldo ?? null,
            estado: "por_clasificar",
            archivo_origen: archivo.name,
            autor: identity?.fullName ?? null,
          },
        });
        nuevos++;
      }
    }
    await terminar(
      `${nombreCuenta(cuenta)}: ${plural(nuevos, "movimiento nuevo", "movimientos nuevos")}, ${plural(repetidos, "ya estaba", "ya estaban")}.`,
    );
  };

  return (
    <Ventana
      titulo="Leer estados de cuenta"
      descripcion="Lee lo nuevo de una cuenta o tarjeta: PDF del banco, Excel de ahorro o Excel de tarjeta. Lo que ya estaba no se repite."
      cerrar={cerrar}
      guardar={guardar}
      puedeGuardar={!!cuenta && archivos.length > 0}
    >
      {datos.cuentas.length ? (
        <Campo id="leer-cuenta" etiqueta="Cuenta">
          <select
            id="leer-cuenta"
            className={claseSelect}
            value={cuentaId}
            onChange={(e) => setCuentaId(e.target.value)}
          >
            <option value="">Elegir cuenta…</option>
            {datos.cuentas.map((c) => (
              <option key={String(c.id)} value={String(c.id)}>
                {nombreCuenta(c)}
              </option>
            ))}
          </select>
        </Campo>
      ) : (
        <p className="text-sm m-0">Todavía no hay cuentas ni tarjetas.</p>
      )}
      <p className="text-sm text-muted-foreground m-0">
        ¿Falta una cuenta o tarjeta? Se agrega en <EnlaceCuentas />.
      </p>
      <Campo id="leer-archivo" etiqueta="Archivo">
        <Input
          id="leer-archivo"
          type="file"
          multiple
          accept=".pdf,.xlsx,.xls,application/pdf"
          onChange={(e) => setArchivos([...(e.target.files ?? [])])}
        />
      </Campo>
    </Ventana>
  );
};

// ---------- Traer mi Excel ----------

const TraerExcel = ({ datos, cerrar, terminar }: PropsVentana) => {
  const dp = useDataProvider();
  const { identity } = useGetIdentity();
  const guardarTope = useGuardarTope(datos);
  const [tipo, setTipo] = useState<"presupuesto-excel" | "fijos-excel">(
    "presupuesto-excel",
  );
  const [archivo, setArchivo] = useState<File | null>(null);
  const autor = identity?.fullName ?? null;

  const traerPresupuesto = async (a: File) => {
    const semilla = (await leer(a, "presupuesto-excel")) as SemillaPresupuesto;
    const categorias = await todas<CategoriaFila>(dp, "categorias");
    const porNombre = new Map(categorias.map((c) => [norm(c.nombre), c]));
    const nuevas: string[] = [];
    const topes: Record<string, number> = {};
    for (const s of semilla.categorias) {
      let cat = porNombre.get(norm(s.nombre));
      if (!cat) {
        cat = (
          await dp.create<CategoriaFila>("categorias", {
            data: { nombre: s.nombre, ambito: "casa", autor },
          })
        ).data;
        porNombre.set(norm(s.nombre), cat);
        nuevas.push(s.nombre);
      }
      if (s.monto !== null) {
        await guardarTope(cat.id, s.monto);
        topes[cat.nombre] = s.monto;
      }
    }
    registrarEvento("presupuesto.editado", {
      mes: datos.mes,
      desde: "excel",
      archivo: a.name,
      topes,
      categorias_nuevas: nuevas,
      fijos_nuevos: [],
    });
    const sinFecha = semilla.sinFecha.length
      ? ` ${plural(semilla.sinFecha.length, "fila sin fecha no entró", "filas sin fecha no entraron")}.`
      : "";
    return `${a.name}: ${plural(nuevas.length, "categoría nueva", "categorías nuevas")}, ${plural(Object.keys(topes).length, "monto", "montos")} de ${nombreMes(datos.mes)}.${sinFecha}`;
  };

  const traerFijos = async (a: File) => {
    const semilla = (await leer(a, "fijos-excel")) as SemillaFijo[];
    const [fijos, cuentas] = await Promise.all([
      todas<PagoFijoFila>(dp, "pagos_fijos"),
      todas<CuentaFila>(dp, "cuentas"),
    ]);
    const ya = new Set(fijos.map((f) => norm(f.nombre)));
    const nuevos: string[] = [];
    const sinCuenta: string[] = [];
    for (const s of semilla) {
      if (ya.has(norm(s.pago))) continue;
      const cuenta = cuentaPorTexto(cuentas, s.cuenta);
      if (!cuenta) sinCuenta.push(`${s.pago} («${s.cuenta}»)`);
      await dp.create("pagos_fijos", {
        data: {
          nombre: s.pago,
          dia_mes: s.dia,
          monto_centavos: s.monto,
          cuenta_id: cuenta?.id ?? null,
          categoria_id: null,
          autor,
        },
      });
      ya.add(norm(s.pago));
      nuevos.push(s.pago);
    }
    registrarEvento("presupuesto.editado", {
      mes: datos.mes,
      desde: "excel",
      archivo: a.name,
      topes: {},
      categorias_nuevas: [],
      fijos_nuevos: nuevos,
    });
    const falta = sinCuenta.length
      ? ` Sin cuenta: ${sinCuenta.join(", ")}; agréguela en Puesta en marcha.`
      : "";
    return `${a.name}: ${plural(nuevos.length, "pago fijo nuevo", "pagos fijos nuevos")}.${falta}`;
  };

  const guardar = async () => {
    if (!archivo) return;
    await terminar(
      tipo === "presupuesto-excel"
        ? await traerPresupuesto(archivo)
        : await traerFijos(archivo),
    );
  };

  return (
    <Ventana
      titulo="Traer mi Excel"
      descripcion="El Excel PRESUPUESTO trae categorías y montos del mes; la lista de pagos fijos trae pago, día, cuenta y monto."
      cerrar={cerrar}
      guardar={guardar}
      puedeGuardar={!!archivo}
    >
      <Campo id="excel-tipo" etiqueta="¿Qué Excel es?">
        <select
          id="excel-tipo"
          className={claseSelect}
          value={tipo}
          onChange={(e) => setTipo(e.target.value as typeof tipo)}
        >
          <option value="presupuesto-excel">PRESUPUESTO</option>
          <option value="fijos-excel">Pagos fijos</option>
        </select>
      </Campo>
      <Campo id="excel-archivo" etiqueta="Archivo">
        <Input
          id="excel-archivo"
          type="file"
          accept=".xlsx,.xls"
          onChange={(e) => setArchivo(e.target.files?.[0] ?? null)}
        />
      </Campo>
    </Ventana>
  );
};

// ---------- Editar presupuesto ----------

/** Centavos → "450.00" para un campo; vacío si no hay tope. */
const enCampo = (c: number | undefined) =>
  c === undefined ? "" : (c / 100).toFixed(2);

const EditarPresupuesto = ({ datos, cerrar, terminar }: PropsVentana) => {
  const dp = useDataProvider();
  const { identity } = useGetIdentity();
  const guardarTope = useGuardarTope(datos);
  const autor = identity?.fullName ?? null;
  const topes = topesDelMes(datos.presupuestos, datos.mes);
  const [valores, setValores] = useState<Record<string, string>>(() =>
    Object.fromEntries(
      datos.categorias.map((c) => [
        String(c.id),
        enCampo(topes.get(String(c.id))),
      ]),
    ),
  );
  const [catNueva, setCatNueva] = useState({
    nombre: "",
    ambito: "casa" as Ambito,
    monto: "",
  });
  const [fijoNuevo, setFijoNuevo] = useState({
    nombre: "",
    dia: "",
    cuenta: "",
    monto: "",
  });

  const guardar = async () => {
    const cambios: Record<string, number> = {};
    for (const c of datos.categorias) {
      const texto = valores[String(c.id)] ?? "";
      if (texto === enCampo(topes.get(String(c.id)))) continue;
      const tope = centavos(texto);
      await guardarTope(c.id, tope);
      cambios[c.nombre] = tope;
    }
    const nuevas: string[] = [];
    const nombre = catNueva.nombre.trim();
    if (nombre) {
      const categorias = await todas<CategoriaFila>(dp, "categorias");
      if (categorias.some((c) => norm(c.nombre) === norm(nombre)))
        throw new Error(`la categoría ${nombre} ya existe`);
      const tope = centavos(catNueva.monto);
      const cat = (
        await dp.create<CategoriaFila>("categorias", {
          data: { nombre, ambito: catNueva.ambito, autor },
        })
      ).data;
      if (catNueva.monto.trim()) {
        await guardarTope(cat.id, tope);
        cambios[nombre] = tope;
      }
      nuevas.push(nombre);
    }
    const fijos: string[] = [];
    const pago = fijoNuevo.nombre.trim();
    if (pago) {
      const dia = Number(fijoNuevo.dia);
      if (!Number.isInteger(dia) || dia < 1 || dia > 31)
        throw new Error(`${pago}: el día va de 1 a 31`);
      await dp.create("pagos_fijos", {
        data: {
          nombre: pago,
          dia_mes: dia,
          monto_centavos: centavos(fijoNuevo.monto),
          cuenta_id: fijoNuevo.cuenta || null,
          categoria_id: null,
          autor,
        },
      });
      fijos.push(pago);
    }
    registrarEvento("presupuesto.editado", {
      mes: datos.mes,
      desde: "app",
      topes: cambios,
      categorias_nuevas: nuevas,
      fijos_nuevos: fijos,
    });
    await terminar(
      `Presupuesto de ${nombreMes(datos.mes)} guardado: ${plural(Object.keys(cambios).length, "monto", "montos")}, ${plural(nuevas.length, "categoría nueva", "categorías nuevas")}, ${plural(fijos.length, "pago fijo nuevo", "pagos fijos nuevos")}.`,
    );
  };

  const grupos = (["casa", "empresa"] as const).map((a) => ({
    ambito: a,
    lista: datos.categorias.filter((c) => c.ambito === a),
  }));

  return (
    <Ventana
      titulo="Editar presupuesto"
      descripcion={`Montos de ${nombreMes(datos.mes)}, una categoría nueva y un pago fijo nuevo.`}
      cerrar={cerrar}
      guardar={guardar}
      puedeGuardar
    >
      {grupos.map((g) =>
        g.lista.length ? (
          <fieldset key={g.ambito} className="flex flex-col gap-2 min-w-0">
            <legend className="text-sm font-semibold mb-1">
              {GRUPO[g.ambito]}
            </legend>
            {g.lista.map((c) => {
              const id = `tope-${c.id}`;
              return (
                <div
                  key={String(c.id)}
                  className="grid grid-cols-[1fr_8rem] items-center gap-3"
                >
                  <Label htmlFor={id} className="min-w-0 break-words">
                    {c.nombre}
                  </Label>
                  <Input
                    id={id}
                    inputMode="decimal"
                    className="min-h-11 text-right tabular-nums"
                    value={valores[String(c.id)] ?? ""}
                    onChange={(e) =>
                      setValores((v) => ({
                        ...v,
                        [String(c.id)]: e.target.value,
                      }))
                    }
                  />
                </div>
              );
            })}
          </fieldset>
        ) : null,
      )}

      <fieldset className="flex flex-col gap-2 min-w-0">
        <legend className="text-sm font-semibold mb-1">
          Agregar categoría
        </legend>
        <Campo id="cat-nombre" etiqueta="Categoría nueva">
          <Input
            id="cat-nombre"
            className="min-h-11"
            value={catNueva.nombre}
            onChange={(e) =>
              setCatNueva((v) => ({ ...v, nombre: e.target.value }))
            }
          />
        </Campo>
        <div className="grid grid-cols-2 gap-3">
          <Campo id="cat-grupo" etiqueta="Grupo de la categoría nueva">
            <select
              id="cat-grupo"
              className={claseSelect}
              value={catNueva.ambito}
              onChange={(e) =>
                setCatNueva((v) => ({
                  ...v,
                  ambito: e.target.value as Ambito,
                }))
              }
            >
              <option value="casa">Casa</option>
              <option value="empresa">Empresa</option>
            </select>
          </Campo>
          <Campo id="cat-monto" etiqueta="Monto de la categoría nueva">
            <Input
              id="cat-monto"
              inputMode="decimal"
              className="min-h-11"
              value={catNueva.monto}
              onChange={(e) =>
                setCatNueva((v) => ({ ...v, monto: e.target.value }))
              }
            />
          </Campo>
        </div>
      </fieldset>

      <fieldset className="flex flex-col gap-2 min-w-0">
        <legend className="text-sm font-semibold mb-1">
          Agregar pago fijo
        </legend>
        <Campo id="fijo-nombre" etiqueta="Pago fijo nuevo">
          <Input
            id="fijo-nombre"
            className="min-h-11"
            value={fijoNuevo.nombre}
            onChange={(e) =>
              setFijoNuevo((v) => ({ ...v, nombre: e.target.value }))
            }
          />
        </Campo>
        <div className="grid grid-cols-2 gap-3">
          <Campo id="fijo-dia" etiqueta="Día del pago">
            <Input
              id="fijo-dia"
              type="number"
              min={1}
              max={31}
              className="min-h-11"
              value={fijoNuevo.dia}
              onChange={(e) =>
                setFijoNuevo((v) => ({ ...v, dia: e.target.value }))
              }
            />
          </Campo>
          <Campo id="fijo-monto" etiqueta="Monto del pago">
            <Input
              id="fijo-monto"
              inputMode="decimal"
              className="min-h-11"
              value={fijoNuevo.monto}
              onChange={(e) =>
                setFijoNuevo((v) => ({ ...v, monto: e.target.value }))
              }
            />
          </Campo>
        </div>
        <Campo id="fijo-cuenta" etiqueta="Cuenta del pago">
          <select
            id="fijo-cuenta"
            className={claseSelect}
            value={fijoNuevo.cuenta}
            onChange={(e) =>
              setFijoNuevo((v) => ({ ...v, cuenta: e.target.value }))
            }
          >
            <option value="">Elegir cuenta…</option>
            {datos.cuentas.map((c) => (
              <option key={String(c.id)} value={String(c.id)}>
                {nombreCuenta(c)}
              </option>
            ))}
          </select>
        </Campo>
      </fieldset>
    </Ventana>
  );
};
