// KF-23 · c2-regla-elegir y c2-regla-clausula (R053), maqueta Clausulas.
// La forma se elige en «De lección a regla» (KF-22) y llega por la ruta;
// aquí solo se arma el texto propuesto y la fila de `reglas`
// (20261111120000_kf_tablas.sql:200-209).
import type { Identifier } from "ra-core";

import { FORMAS, type Forma, type LeccionBiblioteca } from "./biblioteca";

export type Regla = {
  id: Identifier;
  leccion_id: Identifier | null;
  forma: Forma;
  tipo_proyecto: string | null;
  texto: string;
  creado_en?: string | null;
};

export const RUTA_CLAUSULAS = "/lecciones/clausulas";

/** Ruta a Cláusulas con la forma ya elegida. */
export const rutaClausulas = (leccionId: Identifier, forma: Forma) =>
  `${RUTA_CLAUSULAS}/${leccionId}?forma=${forma}`;

/** La forma que llega por la ruta, si es una de las 3. */
export const formaDeRuta = (valor: string | null): Forma | null =>
  FORMAS.find((f) => f.forma === valor)?.forma ?? null;

const sinPunto = (s: string) => s.trim().replace(/[.\s]+$/, "");

/** Texto propuesto: la regla nueva de la lección, o lo que pasó, según la forma. */
export const textoPropuesto = (
  l: Pick<LeccionBiblioteca, "regla_nueva" | "que_paso">,
  forma: Forma,
) => {
  const base = sinPunto(l.regla_nueva || `Evitar: ${l.que_paso ?? ""}`);
  if (forma === "checklist") return `Revisar antes de empezar: ${base}.`;
  if (forma === "clausula") return `El cliente acepta que: ${base}.`;
  return `Estimado cliente: le recordamos que ${base}.`;
};

/** La fila que se guarda en `reglas`: siempre con el texto que quedó escrito. */
export const filaRegla = (
  l: Pick<LeccionBiblioteca, "id" | "tipo_proyecto">,
  forma: Forma,
  texto: string,
) => ({
  leccion_id: l.id,
  forma,
  tipo_proyecto: l.tipo_proyecto ?? null,
  texto: texto.trim(),
});
