import { useEffect } from "react";
import { useLocation } from "react-router";

import { registrarEvento } from "../misc/eventos";
import { seccionDeRuta } from "./secciones";

/** Registra pantalla.abierta cada vez que se entra a una de las 11 secciones. */
export const usePantallaAbierta = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    const seccion = seccionDeRuta(pathname);
    if (seccion) {
      registrarEvento("pantalla.abierta", {
        pantalla: seccion.nombre,
        ruta: pathname,
      });
    }
  }, [pathname]);
};
