// Kaizen Files · KF-13/KF-14 · el estado que muestra Cobros, en un solo lugar.
// KF-29: Hoy cuenta sus «Facturas vencidas» con esta misma función, sin
// recalcular nada. Sin cuenta de banco (o con un RUC desconocido) la factura
// queda «Sin cruzar» y no vence (c1-r-empresas límite).
// Ruta relativa: el proyecto vitest «node» no tiene el alias @/ (KF-30).
import { estadoVisible } from "../../../kaizen/lectores/cruce";

export type FacturaCobro = {
  empresa_ruc: string;
  vence?: string | null;
  pagado_centavos?: number;
  estado?: string;
};

/** RUC de las empresas con cuenta de banco: solo esas tienen estado que cruzar. */
export const rucsConCuenta = (
  cuentas: { tipo: string; empresa_ruc?: string | null }[],
) =>
  new Set(
    cuentas
      .filter((c) => c.tipo === "banco" && c.empresa_ruc)
      .map((c) => String(c.empresa_ruc)),
  );

/** «Vencida», «Pendiente», «Parcial», «Pagada», «Revisar» o «Sin cruzar». */
export const estadoCobro = (
  f: FacturaCobro,
  conCuenta: Set<string>,
  hoy: string,
) => {
  const pagado = f.pagado_centavos ?? 0;
  const sinCuenta =
    !conCuenta.has(f.empresa_ruc) &&
    (f.estado ?? "pendiente") === "pendiente" &&
    !pagado;
  return estadoVisible(
    { estado: sinCuenta ? "sin_cruzar" : f.estado, vence: f.vence, pagado },
    hoy,
  );
};

/** Hoy en la zona de la PC, «YYYY-MM-DD». */
export const hoyLocal = () => {
  const d = new Date();
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
};
