// Yunque 8 · KF-06 · c2-cel-barra (R060, maqueta CelMas).
// Una sola lista para la barra del celular, la pantalla Más y el menú
// lateral de la PC: así las tres no se separan.

export type Seccion = {
  nombre: string;
  ruta: string;
  /** Línea corta que se muestra en Más. */
  detalle?: string;
  /** Partida que construye la pantalla de verdad. Sin partida: ya está construida. */
  partida?: string;
};

export const SECCIONES_BARRA: Seccion[] = [
  { nombre: "Hoy", ruta: "/" },
  { nombre: "Clientes", ruta: "/clientes" },
  { nombre: "Minuta", ruta: "/minuta" },
  { nombre: "Lecciones", ruta: "/lecciones" },
  { nombre: "Más", ruta: "/mas" },
];

export const SECCIONES_MAS: Seccion[] = [
  {
    nombre: "Cobros",
    ruta: "/cobros",
    detalle: "Facturas × banco",
  },
  {
    nombre: "Presupuesto",
    ruta: "/presupuesto",
    detalle: "Cuánto entra y cuánto se gasta al mes",
  },
  {
    nombre: "Negocios",
    ruta: "/negocios",
    detalle: "Embudo de cotizaciones",
  },
  {
    nombre: "Tendencia",
    ruta: "/tendencia",
    detalle: "¿Bajan los errores repetidos?",
  },
  {
    nombre: "Retrospectiva",
    ruta: "/retrospectiva",
    detalle: "Cerrar un proyecto",
  },
  {
    nombre: "Puesta en marcha",
    ruta: "/puesta-en-marcha",
    detalle: "Gmail, clientes, facturas, banco y detector",
  },
];

/** Las 11 entradas, en el orden del menú lateral de la PC. */
export const SECCIONES = [...SECCIONES_BARRA, ...SECCIONES_MAS];

/** Pantallas que todavía no tienen su partida construida (Hoy es el tablero). */
export const SECCIONES_PENDIENTES = SECCIONES.filter(
  (s) => s.ruta !== "/" && s.partida,
);

/** La sección a la que pertenece una ruta, o undefined. */
export const seccionDeRuta = (pathname: string): Seccion | undefined => {
  if (pathname === "/" || pathname === "") return SECCIONES_BARRA[0];
  return SECCIONES.find(
    (s) =>
      s.ruta !== "/" &&
      (pathname === s.ruta || pathname.startsWith(`${s.ruta}/`)),
  );
};

/** Una entrada de Más cuenta como «Más» en la barra del celular. */
export const entradaActivaBarra = (pathname: string): string | undefined => {
  const s = seccionDeRuta(pathname);
  if (!s) return undefined;
  return SECCIONES_MAS.includes(s) ? "Más" : s.nombre;
};
