// Kaizen Files · KF-27 · Minuta (maqueta Minuta; no está en disco: se siguió
// 04-diseno.json, el contrato y R007–R009, R050).
// c2-minuta-dictar: un campo de texto que recibe el dictado del teclado del
// celular. c2-minuta-ordenar: Ordenar guarda la minuta en la cola (estado
// «borrador») y la PC la ordena con claude -p (pc/minuta.mjs). Esta pantalla
// se actualiza sola hasta que llega ordenada. Lo ordenado vive en las tablas
// minutas y pendientes: el expediente (KF-08) lo muestra sin pestañas nuevas.
import { Lightbulb } from "lucide-react";
import { useCreate, useGetList, useGetOne, type Identifier } from "ra-core";
import { useId, useState } from "react";
import { Link } from "react-router";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { MINUTA_VACIA, minutaVacia } from "../../../../pc/minuta.mjs";
import { fechaCorta, type Pendiente } from "../expediente/lineaDeTiempo";
import { EstadoDatos } from "../misc/Estados";
import type { Company } from "../types";
import { EnviarMinuta, type MinutaParaEnviar } from "./EnviarMinuta";

export const RUTA_MINUTA = "/minuta";

type MinutaFila = MinutaParaEnviar & {
  cliente_id: Identifier;
  texto: string;
  friccion?: string | null;
  estado: "borrador" | "ordenada" | "enviada";
};

const EN_COLA =
  "En cola: la PC la ordena con Claude. Esta pantalla se actualiza sola.";

export const MinutaPage = () => {
  const idCliente = useId();
  const idTexto = useId();
  const [clienteId, setClienteId] = useState("");
  const [texto, setTexto] = useState("");
  const [aviso, setAviso] = useState<string | null>(null);
  const [minutaId, setMinutaId] = useState<Identifier | null>(null);
  const [crear, { isPending: guardando }] = useCreate();

  const clientes = useGetList<Company>("companies", {
    pagination: { page: 1, perPage: 1000 },
    sort: { field: "name", order: "ASC" },
  });

  const ordenar = () => {
    if (!clienteId) return setAviso("Elige el cliente de la minuta.");
    if (minutaVacia(texto)) return setAviso(MINUTA_VACIA);
    setAviso(null);
    crear(
      "minutas",
      {
        data: { cliente_id: Number(clienteId), texto, estado: "borrador" },
      },
      {
        onSuccess: (m) => setMinutaId(m.id),
        onError: () =>
          setAviso("No se pudo guardar la minuta. Prueba otra vez."),
      },
    );
  };

  const nueva = () => {
    setMinutaId(null);
    setTexto("");
    setAviso(null);
  };

  return (
    <div className="flex min-w-0 flex-col gap-4 py-2 max-w-3xl">
      <div>
        <h1 className="text-2xl font-semibold m-0">Minuta</h1>
        <p className="m-0 text-muted-foreground">
          Dicta lo hablado y toca Ordenar.
        </p>
      </div>

      {minutaId == null ? (
        <Card>
          <CardContent className="flex flex-col gap-3">
            <label htmlFor={idCliente} className="text-sm font-medium">
              Cliente
            </label>
            <select
              id={idCliente}
              value={clienteId}
              onChange={(e) => setClienteId(e.target.value)}
              className="min-h-11 w-full rounded-md border bg-background px-3 text-base"
            >
              <option value="">Elige…</option>
              {(clientes.data ?? []).map((c) => (
                <option key={c.id} value={String(c.id)}>
                  {c.name}
                </option>
              ))}
            </select>
            <EstadoDatos
              consultas={[clientes]}
              que="la lista de clientes"
              hayDatos={(clientes.data ?? []).length > 0}
              vacio="Todavía no hay clientes. Agréguelos en Clientes para hacer su minuta."
              cargando="Cargando clientes…"
            >
              {null}
            </EstadoDatos>

            <label htmlFor={idTexto} className="text-sm font-medium">
              Lo hablado
            </label>
            <textarea
              id={idTexto}
              value={texto}
              onChange={(e) => setTexto(e.target.value)}
              rows={8}
              inputMode="text"
              autoCapitalize="sentences"
              autoCorrect="on"
              spellCheck
              placeholder="Toca el micrófono del teclado y dicta."
              className="w-full min-w-0 rounded-md border bg-background p-3 text-base"
            />

            {aviso ? (
              <p role="alert" className="m-0 text-sm text-destructive">
                {aviso}
              </p>
            ) : null}

            <Button
              type="button"
              className="min-h-11 self-start"
              disabled={guardando}
              onClick={ordenar}
            >
              Ordenar
            </Button>
          </CardContent>
        </Card>
      ) : (
        <MinutaEnCurso id={minutaId} onNueva={nueva} />
      )}
    </div>
  );
};

MinutaPage.path = RUTA_MINUTA;

/** Espera a la cola y muestra la minuta ordenada. */
const MinutaEnCurso = ({
  id,
  onNueva,
}: {
  id: Identifier;
  onNueva: () => void;
}) => {
  const { data: m, isError } = useGetOne<MinutaFila>(
    "minutas",
    { id },
    {
      // Mientras está en la cola, se vuelve a leer cada segundo.
      refetchInterval: (q) =>
        (q.state.data as MinutaFila | undefined)?.estado === "borrador"
          ? 1000
          : false,
    },
  );
  const ordenada = !!m && m.estado !== "borrador";
  const pendientes = useGetList<Pendiente>(
    "pendientes",
    {
      filter: { minuta_id: id },
      pagination: { page: 1, perPage: 1000 },
      sort: { field: "id", order: "ASC" },
    },
    { enabled: ordenada },
  );

  if (isError)
    return (
      <p role="alert" className="text-sm text-destructive">
        No se pudo leer la minuta.
      </p>
    );
  if (!ordenada || pendientes.isPending)
    return (
      <div className="flex flex-col gap-2">
        <p role="status" className="m-0 rounded-md bg-muted p-3 text-sm">
          {EN_COLA}
        </p>
        {/* KF-28 · C5: en la cola no hay Enviar y se dice por qué. */}
        <EnviarMinuta minuta={{ id, estado: "borrador" }} />
      </div>
    );

  const acuerdos = (m.acuerdos ?? "").split("\n").filter(Boolean);
  const lista = pendientes.data ?? [];

  return (
    <section aria-label="Minuta ordenada" className="min-w-0">
      <Card>
        <CardContent className="flex flex-col gap-4">
          <div>
            <h2 className="text-lg font-semibold m-0">Acuerdos</h2>
            <ul aria-label="Acuerdos" className="m-0 mt-1 pl-5 list-disc">
              {acuerdos.map((a, i) => (
                <li key={i} className="py-0.5 break-words">
                  {a}
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h2 className="text-lg font-semibold m-0">Pendientes</h2>
            {lista.length ? (
              <ul aria-label="Pendientes" className="list-none m-0 p-0">
                {lista.map((p) => (
                  <li
                    key={p.id}
                    className="flex flex-col gap-0.5 py-2 border-b last:border-b-0"
                  >
                    <b className="font-semibold break-words">{p.descripcion}</b>
                    <span className="text-sm text-muted-foreground">
                      Responsable: {p.responsable || "sin responsable"}
                    </span>
                    <span className="text-sm text-muted-foreground">
                      Fecha: {fechaCorta(p.fecha_limite)}
                    </span>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="m-0 mt-1 text-sm text-muted-foreground">
                Sin pendientes.
              </p>
            )}
          </div>

          {m.friccion ? (
            <p className="m-0 flex flex-wrap items-center gap-2 text-sm">
              <Badge className="bg-amber-100 text-amber-900 dark:bg-amber-900/40 dark:text-amber-100">
                <Lightbulb className="size-3.5" aria-hidden />
                Fricción
              </Badge>
              <span className="min-w-0 break-words">{m.friccion}</span>
            </p>
          ) : null}

          <EnviarMinuta minuta={m} />

          <div className="flex flex-wrap gap-2">
            <Link
              to={`/companies/${m.cliente_id}/show`}
              className="inline-flex items-center min-h-11 px-3 rounded-md border text-sm font-medium"
            >
              Ver en el expediente
            </Link>
            <Button
              type="button"
              variant="outline"
              className="min-h-11"
              onClick={onNueva}
            >
              Nueva minuta
            </Button>
          </div>
        </CardContent>
      </Card>
    </section>
  );
};
