// c2-instalable: botón «Instalar Kaizen Files» (PWA). Chrome y Edge avisan con
// beforeinstallprompt, a veces antes de que React monte; por eso se escucha
// apenas se importa este módulo y se guarda el aviso. iPhone no tiene ese
// aviso: se explica cómo agregarla a la pantalla de inicio.
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

type AvisoInstalar = Event & {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
};

let avisoGuardado: AvisoInstalar | null = null;
const oyentes = new Set<() => void>();
const avisar = () => oyentes.forEach((o) => o());

if (typeof window !== "undefined") {
  window.addEventListener("beforeinstallprompt", (e) => {
    e.preventDefault();
    avisoGuardado = e as AvisoInstalar;
    avisar();
  });
  window.addEventListener("appinstalled", () => {
    avisoGuardado = null;
    avisar();
  });
}

const esIphone = () => /iPad|iPhone|iPod/.test(window.navigator.userAgent);
const yaInstalada = () =>
  window.matchMedia?.("(display-mode: standalone)").matches ||
  (window.navigator as { standalone?: boolean }).standalone === true;

export const InstalarApp = ({ className }: { className?: string }) => {
  const [aviso, setAviso] = useState(avisoGuardado);
  const [ayuda, setAyuda] = useState(false);

  useEffect(() => {
    const oyente = () => setAviso(avisoGuardado);
    oyentes.add(oyente);
    return () => {
      oyentes.delete(oyente);
    };
  }, []);

  if (yaInstalada()) {
    return (
      <p className={cn("text-sm text-muted-foreground", className)}>
        Kaizen Files ya está instalada en este dispositivo.
      </p>
    );
  }

  const instalar = async () => {
    if (!aviso) {
      setAyuda(true);
      return;
    }
    await aviso.prompt();
    await aviso.userChoice;
    avisoGuardado = null;
    setAviso(null);
  };

  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <Button type="button" variant="outline" onClick={instalar}>
        Instalar Kaizen Files
      </Button>
      {esIphone() ? (
        <p className="text-[13px] text-muted-foreground">
          En iPhone: abre la app en Safari, toca Compartir y luego «Agregar a
          pantalla de inicio».
        </p>
      ) : ayuda ? (
        <p className="text-[13px] text-muted-foreground">
          Si no sale el aviso, abre el menú del navegador (⋮) y elige «Instalar
          Kaizen Files» o «Agregar a pantalla de inicio».
        </p>
      ) : null}
    </div>
  );
};
