// Kaizen Files · KF-08 · Expediente (maqueta Expediente).
// c1-r-expediente (R001–R003), c2-expediente-pestanas y c2-expediente-contactos
// (R048). Va sobre la ficha de empresa de Atomic CRM: CompanyShow pone el
// registro (ShowBase) y esta pantalla arma la línea de tiempo, las 5 pestañas
// y los contactos. Cada fuente se lee aparte: si una falla, se nombra y se
// muestra el resto.
// KF-21 · c2-expediente-correo (R048): el correo con evidencia de una lección
// propuesta lleva la marca de fricción y «Ver lección propuesta», que abre la
// pantalla Validar de KF-20. Sale de la misma búsqueda por evidencia de la
// pestaña Lecciones.
// KF-25 · c2-expediente-cerrar (R048): cada proyecto activo (negocio de
// Atomic) lleva «Cerrar proyecto», que abre su Retrospectiva.
import { useQuery } from "@tanstack/react-query";
import { FolderCheck, Lightbulb, Pencil } from "lucide-react";
import { useDataProvider, useGetOne, type Identifier } from "ra-core";
import { type ReactNode } from "react";
import { Link, useSearchParams } from "react-router";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { proyectoCerrado } from "../clientes/filasClientes";
import { ValidarPage } from "../lecciones/ValidarPage";
import { EnviarMinuta } from "../minuta/EnviarMinuta";
import { registrarEvento } from "../misc/eventos";
import { Cargando } from "../misc/Estados";
import { rutaRetro } from "../retro/retro";
import type { Company, Contact, Deal } from "../types";
import {
  armarLineaDeTiempo,
  avisoFalla,
  dinero,
  ESTADO_FACTURA,
  ESTADO_MINUTA,
  fechaCorta,
  friccionPorCorreo,
  leccionesDelCliente,
  SIN_REGISTROS,
  type Correo,
  type Evidencia,
  type Factura,
  type Leccion,
  type Minuta,
  type Pendiente,
} from "./lineaDeTiempo";

const TODO = { page: 1, perPage: 500 };

/** Lee una fuente sin reintentos: si falla, se dice enseguida. */
function useFuente<T>(
  fuente: string,
  clienteId: Identifier,
  leer: () => Promise<T[]>,
  habilitada = true,
) {
  return useQuery({
    queryKey: ["kf-expediente", fuente, clienteId],
    queryFn: leer,
    retry: false,
    enabled: habilitada,
  });
}

function useExpediente(cliente: Company) {
  const dp = useDataProvider();
  const id = cliente.id;
  const lista = async <T,>(
    recurso: string,
    filter: Record<string, unknown>,
    campo: string,
    order: "ASC" | "DESC" = "DESC",
  ) =>
    (
      await dp.getList(recurso, {
        filter,
        pagination: TODO,
        sort: { field: campo, order },
      })
    ).data as T[];

  const correos = useFuente("correos", id, () =>
    lista<Correo>("correos", { "cliente_ids@cs": `{${id}}` }, "fecha"),
  );
  const minutas = useFuente("minutas", id, () =>
    lista<Minuta>("minutas", { cliente_id: id }, "creado_en"),
  );
  const facturas = useFuente("facturas", id, () =>
    lista<Factura>("facturas", { cliente_id: id }, "fecha"),
  );
  const pendientes = useFuente("pendientes", id, () =>
    lista<Pendiente>("pendientes", { cliente_id: id }, "fecha_limite", "ASC"),
  );
  const contactos = useFuente("contactos", id, () =>
    lista<Contact>("contacts", { company_id: id }, "last_name", "ASC"),
  );
  const proyectos = useFuente("proyectos", id, async () =>
    (await lista<Deal>("deals", { company_id: id }, "name", "ASC")).filter(
      (d) => !proyectoCerrado(d),
    ),
  );

  // Lecciones: las que tienen evidencia en algo de este cliente. Esperan a
  // que las otras fuentes terminen; una fuente caída cuenta como vacía.
  const listas = [correos, minutas, facturas];
  const ids = {
    correos: (correos.data ?? []).map((c) => c.id),
    minutas: (minutas.data ?? []).map((m) => m.id),
    facturas: (facturas.data ?? []).map((f) => f.id),
  };
  const lecciones = useFuente(
    "lecciones",
    `${id}:${ids.correos}:${ids.minutas}:${ids.facturas}`,
    async () => {
      const campos = [
        ["correo_id", ids.correos],
        ["minuta_id", ids.minutas],
        ["factura_id", ids.facturas],
      ] as const;
      const evidencias = (
        await Promise.all(
          campos
            .filter(([, v]) => v.length)
            .map(([campo, v]) =>
              lista<Evidencia>(
                "evidencias",
                { [`${campo}@in`]: `(${v.join(",")})` },
                "id",
              ),
            ),
        )
      ).flat();
      const leccionIds = leccionesDelCliente(evidencias, ids);
      if (!leccionIds.length) return [];
      // Cada lección lleva sus evidencias: de ahí sale la marca del correo.
      return (
        await lista<Leccion>(
          "lecciones",
          { "id@in": `(${leccionIds.join(",")})` },
          "repeticiones",
        )
      ).map((l) => ({
        ...l,
        evidencias: evidencias.filter((e) => e.leccion_id === l.id),
      }));
    },
    listas.every((q) => !q.isPending),
  );

  return {
    correos,
    minutas,
    facturas,
    pendientes,
    lecciones,
    contactos,
    proyectos,
  };
}

const Vacio = () => (
  <p data-estado="vacio" className="text-sm text-muted-foreground py-2">
    {SIN_REGISTROS}
  </p>
);

const Item = ({
  arriba,
  titulo,
  abajo,
  marca,
}: {
  arriba: ReactNode;
  titulo: ReactNode;
  abajo?: ReactNode;
  marca?: ReactNode;
}) => (
  <li className="flex flex-col gap-1 py-2.5 border-b last:border-b-0">
    <span className="text-xs text-muted-foreground">{arriba}</span>
    <b className="text-[15px] font-semibold">{titulo}</b>
    {abajo ? (
      <span className="text-sm text-muted-foreground">{abajo}</span>
    ) : null}
    {marca ? <div>{marca}</div> : null}
  </li>
);

/** Contenido de una pestaña: cargando, fuente caída, vacía o la lista. */
function Panel<T>({
  fuente,
  q,
  children,
}: {
  fuente: string;
  q: { isPending: boolean; isError: boolean; data?: T[] };
  children: (datos: T[]) => ReactNode;
}) {
  if (q.isError)
    return (
      <p className="text-sm text-destructive py-2">{avisoFalla(fuente)}</p>
    );
  if (q.isPending) return <Cargando />;
  if (!q.data?.length) return <Vacio />;
  return <ul className="list-none m-0 p-0">{children(q.data)}</ul>;
}

/** Marca de fricción del correo: qué pasó y el enlace a Validar (KF-20). */
const Friccion = ({
  leccion,
  correoId,
}: {
  leccion: Leccion;
  correoId: number;
}) => (
  <span className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
    <Badge className="bg-amber-100 text-amber-900 dark:bg-amber-900/40 dark:text-amber-100">
      <Lightbulb className="size-3.5" aria-hidden />
      Fricción
    </Badge>
    <span className="text-muted-foreground min-w-0 break-words">
      {leccion.que_paso}
    </span>
    <Link
      to={ValidarPage.pathUna.replace(":id", String(leccion.id))}
      className="inline-flex items-center min-h-11 font-medium underline"
      onClick={() =>
        registrarEvento("leccion.abierta", {
          leccion_id: leccion.id,
          desde: "expediente",
          correo_id: correoId,
        })
      }
    >
      Ver lección propuesta
    </Link>
  </span>
);

const PESTANAS = [
  ["comunicaciones", "Comunicaciones"],
  ["minutas", "Minutas"],
  ["pendientes", "Pendientes"],
  ["cobros", "Cobros"],
  ["lecciones", "Lecciones"],
] as const;

/** KF-24: al llegar desde «Iniciar proyecto», el proyecto nuevo se nombra arriba. */
const ProyectoIniciado = ({ clienteId }: { clienteId: Identifier }) => {
  const [busqueda] = useSearchParams();
  const id = busqueda.get("proyecto");
  const { data } = useGetOne<{
    id: Identifier;
    nombre: string;
    tipo_proyecto: string;
    cliente_id: Identifier;
  }>("punto_partida", { id: id ?? "" }, { enabled: !!id });
  // Solo el proyecto de este cliente: otro ?proyecto= no se anuncia aquí.
  if (!id || !data || String(data.cliente_id) !== String(clienteId))
    return null;
  return (
    <p
      role="status"
      className="m-0 rounded-md bg-green-50 p-3 text-sm text-green-900 break-words dark:bg-green-900/30 dark:text-green-100"
    >
      Proyecto iniciado: {data.nombre} · {data.tipo_proyecto}
    </p>
  );
};

export const Expediente = ({ cliente }: { cliente: Company }) => {
  const f = useExpediente(cliente);
  // KF-29: Hoy abre la minuta en su expediente con ?pestana=minutas.
  const [busqueda] = useSearchParams();
  const pedida = busqueda.get("pestana");
  const pestanaInicial =
    PESTANAS.find(([valor]) => valor === pedida)?.[0] ?? "comunicaciones";

  const fuentes = [
    ["correos", f.correos],
    ["minutas", f.minutas],
    ["facturas", f.facturas],
    ["pendientes", f.pendientes],
    ["lecciones", f.lecciones],
    ["contactos", f.contactos],
  ] as const;
  const caidas = fuentes.filter(([, q]) => q.isError).map(([n]) => n);
  const friccion = friccionPorCorreo(f.lecciones.data);
  const marcaDe = (correoId: number) => {
    const l = friccion.get(correoId);
    return l ? <Friccion leccion={l} correoId={correoId} /> : undefined;
  };

  const deLinea = [f.correos, f.minutas, f.facturas];
  const lineaLista = deLinea.every((q) => !q.isPending || q.isError);
  const linea = armarLineaDeTiempo({
    correos: f.correos.data,
    minutas: f.minutas.data,
    facturas: f.facturas.data,
  });

  return (
    <div className="flex flex-col gap-5 py-2">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-2xl md:text-[28px] font-bold m-0">
            {cliente.name}
          </h1>
          <p className="text-sm text-muted-foreground mt-1">Expediente</p>
        </div>
        <Link
          to={`/companies/${cliente.id}`}
          className="inline-flex items-center gap-2 text-sm min-h-11 px-3 rounded-md border"
        >
          <Pencil className="size-4" aria-hidden />
          Editar ficha
        </Link>
      </div>

      <ProyectoIniciado clienteId={cliente.id} />

      {caidas.length ? (
        <div
          role="alert"
          className="rounded-lg border border-amber-300 bg-amber-50 text-amber-900 dark:bg-amber-950 dark:text-amber-100 px-4 py-3 text-sm"
        >
          {caidas.map((n) => (
            <p key={n} className="m-0">
              {avisoFalla(n)}
            </p>
          ))}
        </div>
      ) : null}

      <div className="grid gap-5 md:grid-cols-[minmax(0,2fr)_minmax(260px,1fr)]">
        <div className="flex flex-col gap-5 min-w-0">
          <Card>
            <CardContent className="flex flex-col gap-2">
              <h2 className="text-lg font-semibold m-0">Línea de tiempo</h2>
              {!lineaLista ? (
                <Cargando />
              ) : linea.length ? (
                <ul aria-label="Línea de tiempo" className="list-none m-0 p-0">
                  {linea.map((e) => (
                    <Item
                      key={e.clave}
                      arriba={`${fechaCorta(e.fecha)} · ${e.tipo}`}
                      titulo={e.titulo}
                      abajo={e.detalle}
                      marca={e.fuente === "correos" ? marcaDe(e.id) : undefined}
                    />
                  ))}
                </ul>
              ) : caidas.length ? null : (
                <Vacio />
              )}
            </CardContent>
          </Card>

          <Card>
            <CardContent>
              <Tabs defaultValue={pestanaInicial}>
                <TabsList
                  aria-label="Expediente"
                  className="w-full justify-start overflow-x-auto h-auto"
                >
                  {PESTANAS.map(([valor, nombre]) => (
                    <TabsTrigger
                      key={valor}
                      value={valor}
                      className="flex-none min-h-11 px-3"
                    >
                      {nombre}
                    </TabsTrigger>
                  ))}
                </TabsList>

                <TabsContent value="comunicaciones">
                  <Panel fuente="correos" q={f.correos}>
                    {(datos) =>
                      datos.map((c) => (
                        <Item
                          key={c.id}
                          arriba={`${fechaCorta(c.fecha)}${c.de ? ` · de ${c.de}` : ""}`}
                          titulo={
                            c.enlace ? (
                              <a
                                href={c.enlace}
                                target="_blank"
                                rel="noreferrer"
                              >
                                {c.asunto || "(sin asunto)"}
                              </a>
                            ) : (
                              c.asunto || "(sin asunto)"
                            )
                          }
                          marca={marcaDe(c.id)}
                        />
                      ))
                    }
                  </Panel>
                </TabsContent>

                <TabsContent value="minutas">
                  <Panel fuente="minutas" q={f.minutas}>
                    {(datos) =>
                      datos.map((m) => (
                        <Item
                          key={m.id}
                          arriba={fechaCorta(m.creado_en)}
                          titulo={m.texto.split("\n")[0]}
                          abajo={m.acuerdos}
                          marca={
                            <span className="flex flex-col items-start gap-2">
                              <Badge variant="secondary">
                                {ESTADO_MINUTA[m.estado ?? "borrador"]}
                              </Badge>
                              <EnviarMinuta minuta={m} />
                            </span>
                          }
                        />
                      ))
                    }
                  </Panel>
                </TabsContent>

                <TabsContent value="pendientes">
                  <Panel fuente="pendientes" q={f.pendientes}>
                    {(datos) =>
                      datos.map((p) => (
                        <Item
                          key={p.id}
                          arriba={`${fechaCorta(p.fecha_limite)} · ${
                            p.responsable || "Sin responsable"
                          }`}
                          titulo={p.descripcion}
                          marca={
                            p.hecho ? (
                              <Badge variant="secondary">Hecho</Badge>
                            ) : null
                          }
                        />
                      ))
                    }
                  </Panel>
                </TabsContent>

                <TabsContent value="cobros">
                  <Panel fuente="facturas" q={f.facturas}>
                    {(datos) =>
                      datos.map((x) => (
                        <Item
                          key={x.id}
                          arriba={`${x.numero} · ${fechaCorta(x.fecha)}`}
                          titulo={dinero(x.monto_centavos)}
                          abajo={`Pagado ${dinero(x.pagado_centavos ?? 0)} de ${dinero(
                            x.monto_centavos,
                          )}`}
                          marca={
                            <Badge variant="secondary">
                              {ESTADO_FACTURA[x.estado ?? "pendiente"]}
                            </Badge>
                          }
                        />
                      ))
                    }
                  </Panel>
                </TabsContent>

                <TabsContent value="lecciones">
                  <Panel fuente="lecciones" q={f.lecciones}>
                    {(datos) =>
                      datos.map((l) => (
                        <Item
                          key={l.id}
                          arriba={`x${l.repeticiones ?? 1} · ${
                            l.categoria || "Sin categoría"
                          }`}
                          titulo={l.que_paso}
                          marca={
                            <Badge variant="secondary">
                              {l.estado === "aprobada"
                                ? "Aprobada"
                                : l.estado === "descartada"
                                  ? "Descartada"
                                  : "Propuesta"}
                            </Badge>
                          }
                        />
                      ))
                    }
                  </Panel>
                </TabsContent>
              </Tabs>
            </CardContent>
          </Card>
        </div>

        <div className="flex flex-col gap-5 self-start min-w-0 w-full">
          <Card>
            <CardContent className="flex flex-col gap-2">
              <h2 className="text-lg font-semibold m-0">Proyectos activos</h2>
              {f.proyectos.isError ? (
                <p className="text-sm text-destructive">
                  No se pudieron leer los proyectos.
                </p>
              ) : f.proyectos.isPending ? (
                <Cargando />
              ) : f.proyectos.data?.length ? (
                <ul
                  aria-label="Proyectos activos"
                  className="list-none m-0 p-0"
                >
                  {f.proyectos.data.map((d) => (
                    <li
                      key={d.id}
                      className="flex flex-wrap items-center justify-between gap-2 py-1.5 border-b last:border-b-0"
                    >
                      <span className="text-sm font-medium min-w-0 break-words">
                        {d.name}
                      </span>
                      <Link
                        to={rutaRetro(d.id)}
                        className="inline-flex items-center gap-2 text-sm min-h-11 px-3 rounded-md border"
                      >
                        <FolderCheck className="size-4" aria-hidden />
                        Cerrar proyecto
                      </Link>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Sin proyectos activos.
                </p>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardContent className="flex flex-col gap-2">
              <h2 className="text-lg font-semibold m-0">Contactos</h2>
              {f.contactos.isError ? (
                <p className="text-sm text-destructive">
                  {avisoFalla("contactos")}
                </p>
              ) : f.contactos.isPending ? (
                <Cargando />
              ) : f.contactos.data?.length ? (
                <ul aria-label="Contactos" className="list-none m-0 p-0">
                  {f.contactos.data.map((c) => (
                    <li key={c.id} className="py-1.5 text-sm">
                      <Link
                        to={`/contacts/${c.id}/show`}
                        className="font-medium"
                      >
                        {`${c.first_name ?? ""} ${c.last_name ?? ""}`.trim()}
                      </Link>
                      {" · "}
                      <span className="text-muted-foreground">
                        {c.title || "sin rol"}
                      </span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Sin contactos todavía.
                </p>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
};
