// KF-22 · c1-r-biblioteca (R019–R021), c2-biblioteca-lista y
// c2-biblioteca-convertir (R052).
// Qué entra a la Biblioteca y en qué orden. Entra solo lo que Validar (KF-20)
// dejó con estado «aprobada». No se mira decidido_por: Deshacer lo deja lleno
// aunque la lección vuelva a «propuesta».
import type { Leccion } from "./validar";

export type LeccionBiblioteca = Leccion & { repeticiones?: number | null };

/** Desde cuántas repeticiones una lección se puede volver regla. */
export const MINIMO_PARA_REGLA = 2;

export const repeticiones = (l: Pick<LeccionBiblioteca, "repeticiones">) =>
  l.repeticiones ?? 1;

export const puedeConvertir = (l: Pick<LeccionBiblioteca, "repeticiones">) =>
  repeticiones(l) >= MINIMO_PARA_REGLA;

/** Las aprobadas, de más a menos repetidas; empate: la decidida más reciente. */
export const enBiblioteca = <T extends LeccionBiblioteca>(lecciones: T[]) =>
  lecciones
    .filter((l) => l.estado === "aprobada")
    .sort(
      (a, b) =>
        repeticiones(b) - repeticiones(a) ||
        (b.decidido_en ?? "").localeCompare(a.decidido_en ?? "") ||
        String(a.id).localeCompare(String(b.id), undefined, { numeric: true }),
    );

export type Filtros = { categoria: string; tipo_proyecto: string };
export const SIN_FILTRO: Filtros = { categoria: "", tipo_proyecto: "" };

export const filtrar = <T extends LeccionBiblioteca>(
  lecciones: T[],
  f: Filtros,
) =>
  lecciones.filter(
    (l) =>
      (!f.categoria || l.categoria === f.categoria) &&
      (!f.tipo_proyecto || l.tipo_proyecto === f.tipo_proyecto),
  );

/** Valores distintos de una columna, para las opciones de un filtro. */
export const opciones = (
  lecciones: LeccionBiblioteca[],
  campo: keyof Filtros,
) =>
  [
    ...new Set(
      lecciones
        .map((l) => l[campo])
        .filter((v): v is string => typeof v === "string" && v !== ""),
    ),
  ].sort((a, b) => a.localeCompare(b, "es"));

/** Las 3 formas de la tabla reglas (columna forma). */
export const FORMAS = [
  {
    forma: "checklist",
    nombre: "Ítem de checklist",
    detalle: "Se revisa antes de empezar cada proyecto.",
  },
  {
    forma: "clausula",
    nombre: "Cláusula de cotización",
    detalle: "Va escrita en cada cotización.",
  },
  {
    forma: "plantilla",
    nombre: "Plantilla de correo",
    detalle: "Se manda al cliente en el momento justo.",
  },
] as const;

export type Forma = (typeof FORMAS)[number]["forma"];

export const nombreForma = (f: Forma) =>
  FORMAS.find((x) => x.forma === f)!.nombre;
