import type { Identifier } from "ra-core";

import { normalizarTipo, type ItemChecklist } from "../punto/puntoPartida";
import type { Deal } from "../types";

export const RUTA_RETRO = "/retrospectiva";
export const RUTA_RETRO_UNA = `${RUTA_RETRO}/:id`;
export const rutaRetro = (negocioId: Identifier) =>
  `${RUTA_RETRO}/${negocioId}`;

export const PREGUNTAS = [
  "¿Qué pasó en este proyecto que no quieres que se repita?",
  "¿Qué harás distinto la próxima vez?",
] as const;

export const AVISO_PREGUNTAS = "Contesta las 2 preguntas para cerrar.";

/** Las 2 respuestas limpias, o null si falta alguna. */
export const respuestasLimpias = (r: [string, string]) => {
  const [a, b] = r.map((x) => x.trim());
  return a && b ? ([a, b] as [string, string]) : null;
};

type PuntoPartida = {
  id: Identifier;
  nombre: string;
  tipo_proyecto: string;
  cliente_id?: Identifier | null;
  negocio_id?: Identifier | null;
  checklist?: ItemChecklist[] | null;
};

/**
 * El Punto de Partida de este proyecto: el ligado al negocio o, si no, el del
 * mismo cliente con el mismo nombre. Puede no haber.
 */
export const puntoDelNegocio = <P extends PuntoPartida>(
  puntos: P[],
  d: Pick<Deal, "id" | "name" | "company_id">,
): P | undefined =>
  puntos.find(
    (p) => p.negocio_id != null && String(p.negocio_id) === String(d.id),
  ) ??
  puntos.find(
    (p) =>
      String(p.cliente_id) === String(d.company_id) &&
      normalizarTipo(p.nombre) === normalizarTipo(d.name),
  );

/** Solo las casillas del checklist (las cláusulas no se cumplen en obra). */
export const checklistCumplido = (
  items: ItemChecklist[] | null | undefined,
) => {
  const lista = (items ?? []).filter((i) => i.forma === "checklist");
  return {
    items: lista,
    cumplidos: lista.filter((i) => i.hecho).length,
    total: lista.length,
  };
};

type LeccionRepetida = {
  tipo_proyecto?: string | null;
  repeticiones?: number | null;
  estado: string;
};

/** Las lecciones aprobadas del mismo tipo que pasaron 2 o más veces. */
export const leccionesRepetidas = <L extends LeccionRepetida>(
  lecciones: L[],
  tipo: string | null | undefined,
): L[] => {
  const clave = normalizarTipo(tipo);
  if (!clave) return [];
  return lecciones
    .filter(
      (l) =>
        l.estado === "aprobada" &&
        (l.repeticiones ?? 1) >= 2 &&
        normalizarTipo(l.tipo_proyecto) === clave,
    )
    .sort((a, b) => (b.repeticiones ?? 1) - (a.repeticiones ?? 1));
};

/** Lo nuevo: una lección propuesta. No se aprueba aquí, se decide en Validar. */
export const leccionDeRetro = (
  [quePaso, solucion]: [string, string],
  tipo: string | null | undefined,
) => ({
  que_paso: quePaso,
  solucion,
  tipo_proyecto: tipo?.trim() || null,
  estado: "propuesta",
  repeticiones: 1,
});

/** Archivar como lo hace Atomic (deals/DealShow.tsx:211). */
export const cambiosCerrar = (ahora: Date) => ({
  archived_at: ahora.toISOString(),
});
