// Kaizen Files · KF-12 · c3-importadores (R068).
// Lee un archivo con su lector y deja el evento archivo.leido o
// archivo.rechazado con el motivo. Las librerías y el registro llegan
// inyectados: en la app, de cargar.ts; en las pruebas, del build de Node.
import type { getDocument as GetDocument } from "pdfjs-dist";
import { filasPdf } from "./leer_pdf";
import {
  leerAhorroExcel,
  leerAhorroPdf,
  leerEstadoCuentaPdf,
  leerFacturaDgi,
  leerTarjetaExcel,
  leerTarjetaPdf,
  type Empresa,
  type XLSX,
} from "./lectores";
import { leerFijosExcel, leerPresupuestoExcel } from "./presupuesto";

export type Libs = { getDocument: typeof GetDocument; XLSX: XLSX };

export type TipoArchivo =
  | "factura-dgi"
  | "banco-pdf"
  | "ahorro-excel"
  | "tarjeta-excel"
  // KF-15: semillas del Presupuesto.
  | "presupuesto-excel"
  | "fijos-excel"
  // KF-32: cuentas de casa y tarjetas reales, en PDF.
  | "ahorro-pdf"
  | "tarjeta-pdf";

export type PedidoArchivo = {
  nombre: string;
  tipo: TipoArchivo;
  bytes: Uint8Array;
  /** Para la factura DGI: empresas configuradas (RUC del emisor). */
  empresas?: Empresa[];
  /** Para banco, ahorro y tarjeta: la cuenta a la que pertenecen. */
  cuenta?: string;
};

export type Resultado =
  | { ok: true; datos: unknown }
  | { ok: false; motivo: string };

type Registrar = (tipo: string, datos: Record<string, unknown>) => void;

export async function leerArchivo(
  pedido: PedidoArchivo,
  { libs, registrar }: { libs: Libs; registrar: Registrar },
): Promise<Resultado> {
  const { nombre, tipo, bytes, empresas = [], cuenta = "" } = pedido;
  try {
    let datos: unknown;
    if (tipo === "factura-dgi")
      datos = leerFacturaDgi(await filasPdf(bytes, libs.getDocument), empresas);
    else if (tipo === "banco-pdf")
      datos = leerEstadoCuentaPdf(
        await filasPdf(bytes, libs.getDocument),
        cuenta,
      );
    else if (tipo === "ahorro-excel")
      datos = leerAhorroExcel(libs.XLSX, bytes, cuenta);
    else if (tipo === "tarjeta-excel")
      datos = leerTarjetaExcel(libs.XLSX, bytes, cuenta);
    else if (tipo === "ahorro-pdf")
      datos = leerAhorroPdf(await filasPdf(bytes, libs.getDocument), cuenta);
    else if (tipo === "tarjeta-pdf")
      datos = leerTarjetaPdf(await filasPdf(bytes, libs.getDocument), cuenta);
    else if (tipo === "presupuesto-excel")
      datos = leerPresupuestoExcel(libs.XLSX, bytes);
    else datos = leerFijosExcel(libs.XLSX, bytes);
    const filas = Array.isArray(datos)
      ? datos.length
      : tipo === "presupuesto-excel"
        ? (datos as { movimientos: unknown[] }).movimientos.length
        : 1;
    registrar("archivo.leido", { nombre, tipo, filas });
    return { ok: true, datos };
  } catch (e) {
    const motivo = e instanceof Error ? e.message : String(e);
    registrar("archivo.rechazado", { nombre, tipo, motivo });
    return { ok: false, motivo };
  }
}
