// Kaizen Files · KF-04 · c3-config, c3-cuentas-personales.
// Empresas, cuentas y tarjetas viven en tablas: se agregan en la app,
// ninguna queda escrita en el programa salvo la semilla del contrato.

export type Empresa = {
  id: number;
  nombre: string;
  ruc?: string | null;
  carpeta_facturas?: string | null;
  autor?: string | null;
  creado_en?: string;
};

export const DUENOS = ["DPB", "Cesar", "Caro"] as const;
export type Dueno = (typeof DUENOS)[number];

export type Cuenta = {
  id: number;
  nombre: string;
  dueno: Dueno;
  banco?: string | null;
  tipo: "banco" | "tarjeta";
  ambito: "empresa" | "casa";
  /** KF-14: la empresa dueña de la cuenta, por su RUC. */
  empresa_ruc?: string | null;
  carpeta_estados?: string | null;
  autor?: string | null;
  creado_en?: string;
};

/** Semilla: las 5 empresas del contrato (c1-r-empresas). */
export const SEMILLA_EMPRESAS = [
  "DYNAMIC",
  "ARCHROME",
  "BLACK CANVA",
  "FONG CERRUD STUDIO",
  "METALES Y ACABADOS DPB",
];

export const sembrarEmpresas = (): Empresa[] =>
  SEMILLA_EMPRESAS.map((nombre, i) => ({
    id: i + 1,
    nombre,
    ruc: null,
    carpeta_facturas: null,
    autor: "semilla",
  }));

/** Nombre corto de una cuenta: «Caro · Banistmo · tarjeta». */
export const nombreCuenta = (c: Pick<Cuenta, "dueno" | "banco" | "tipo">) =>
  [c.dueno, c.banco, c.tipo === "tarjeta" ? "tarjeta" : null]
    .filter(Boolean)
    .join(" · ");

/** KF-14: mismo nombre de empresa, sin importar mayúsculas ni espacios. */
export const mismoNombre = (a: string, b: string) =>
  a.trim().toLocaleUpperCase("es") === b.trim().toLocaleUpperCase("es");

// KF-11 · c2-puesta-buzones, c2-puesta-marcha ----------------------------

/** Tabla buzones: la llave es el correo (en el demo, FakeRest le pone id). */
export type Buzon = {
  id: string | number;
  correo: string;
  activo: boolean;
  marca_ms?: number | null;
  autor?: string | null;
  creado_en?: string;
};

/** Tabla eventos («objeto.acción»). */
export type Evento = {
  id: number;
  tipo: string;
  datos: Record<string, unknown>;
  en: string;
  autor?: string | null;
};

export type Estado = "Conectado" | "Falta permiso" | "Error" | "Sin corridas";

/** La escucha de la PC (pc/gmail-permiso.mjs) que manda a Google. */
export const ESCUCHA_PERMISO = "http://127.0.0.1:53682/permitir";
export const urlPermitir = (correo: string) =>
  `${ESCUCHA_PERMISO}?buzon=${encodeURIComponent(correo)}`;

export const normalizarCorreo = (c: string) => c.trim().toLowerCase();

/** Correos con un evento buzon.permitido (lo escribe la PC). */
export const correosPermitidos = (eventos: Evento[]) =>
  new Set(
    eventos
      .filter((e) => e.tipo === "buzon.permitido")
      .map((e) => normalizarCorreo(String(e.datos?.buzon ?? ""))),
  );

/** Un buzón está conectado si la PC guardó su permiso. */
export const estadoBuzon = (correo: string, permitidos: Set<string>): Estado =>
  permitidos.has(normalizarCorreo(correo)) ? "Conectado" : "Falta permiso";

/** Todos los buzones activos conectados; ninguno o alguno sin permiso: falta. */
export const estadoBuzones = (
  buzones: Buzon[],
  permitidos: Set<string>,
): Estado => {
  const activos = buzones.filter((b) => b.activo);
  return activos.length > 0 &&
    activos.every((b) => estadoBuzon(b.correo, permitidos) === "Conectado")
    ? "Conectado"
    : "Falta permiso";
};

/** El último detector.corrio manda: ok → conectado; si no → error. */
export const estadoDetector = (corridas: Evento[]): Estado => {
  const ultima = [...corridas]
    .filter((e) => e.tipo === "detector.corrio")
    .sort((a, b) => String(b.en).localeCompare(String(a.en)))[0];
  if (!ultima) return "Sin corridas";
  return ultima.datos?.ok === true ? "Conectado" : "Error";
};
