PuestaEnMarchaPage.path = "/puesta-en-marcha";

const Seccion = ({
  titulo,
  boton,
  onAgregar,
  children,
}: {
  titulo: string;
  boton: string;
  onAgregar: () => void;
  children: ReactNode;
}) => (
  <section className="flex flex-col gap-2">
    <div className="flex items-center justify-between gap-3">
      <h2 className="text-lg font-semibold">{titulo}</h2>
      <Button size="sm" className="min-h-11 sm:min-h-9" onClick={onAgregar}>
        {boton}
      </Button>
    </div>
    <div className="rounded-xl border bg-card px-4">{children}</div>
  </section>
);

const Fila = ({ titulo, detalle }: { titulo: string; detalle: string }) => (
  <li className="flex flex-col gap-1 border-b py-3 last:border-b-0">
    <b className="text-[15px]">{titulo}</b>
    <span className="text-[13px] text-muted-foreground break-all">
      {detalle}
    </span>
  </li>
);

const Vacia = ({ texto }: { texto: string }) => (
  <Vacio className="py-3">{texto}</Vacio>
);

const useAutor = () => {
  const { identity } = useGetIdentity();
  return identity?.fullName ?? null;
};

// Panel de estado (KF-11 · c2-puesta-marcha) -----------------------------

const COLOR: Record<Estado, string> = {
  Conectado: "bg-emerald-100 text-emerald-900",
  "Falta permiso": "bg-amber-100 text-amber-900",
  Error: "bg-red-100 text-red-900",
  "Sin corridas": "bg-muted text-muted-foreground",
};

const Insignia = ({ estado }: { estado: Estado }) => (
  <span
    data-testid="estado"
    className={`shrink-0 rounded-full px-2.5 py-0.5 text-[13px] font-medium ${COLOR[estado]}`}
  >
    {estado}
  </span>
);

// Se filtra en la pantalla: al quitar uno, la lista en caché ya lo deja fuera.
const useBuzones = () => {
  const r = useGetList<Buzon>("buzones", TODAS);
  return { ...r, data: r.data?.filter((b) => b.activo) };
};
const usePermitidos = () =>
  useGetList<Evento>("eventos", {
    ...TODAS,
    filter: { tipo: "buzon.permitido" },
  });

const cuantos = (n: number | undefined, uno: string, varios: string) =>
  `${n ?? 0} ${n === 1 ? uno : varios}`;

const PanelEstado = () => {
  const clientes = useGetList("companies", {
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  const buzones = useBuzones();
  const permitidos = usePermitidos();
  const empresas = useGetList<Empresa>("empresas", TODAS);
  const cuentas = useGetList<Cuenta>("cuentas", TODAS);
  const detector = useGetList<Evento>("eventos", {
    pagination: { page: 1, perPage: 1 },
    sort: { field: "en", order: "DESC" },
    filter: { tipo: "detector.corrio" },
  });
  const ultima = detector.data?.[0];
  const filas: Array<{ titulo: string; estado: Estado; detalle: string }> = [
    {
      titulo: "Clientes",
      estado: clientes.error ? "Error" : "Conectado",
      detalle: cuantos(clientes.total, "cliente", "clientes"),
    },
    {
      titulo: "Buzones",
      estado:
        buzones.error || permitidos.error
          ? "Error"
          : estadoBuzones(
              buzones.data ?? [],
              correosPermitidos(permitidos.data ?? []),
            ),
      detalle: cuantos(buzones.data?.length, "buzón", "buzones"),
    },
    {
      titulo: "Empresas",
      estado: empresas.error ? "Error" : "Conectado",
      detalle: cuantos(empresas.data?.length, "empresa", "empresas"),
    },
    {
      titulo: "Cuentas",
      estado: cuentas.error ? "Error" : "Conectado",
      detalle: cuantos(cuentas.data?.length, "cuenta", "cuentas"),
    },
    {
      titulo: "Detector",
      estado: detector.error ? "Error" : estadoDetector(detector.data ?? []),
      detalle: ultima
        ? `Última corrida ${new Date(ultima.en).toLocaleString("es-PA")}`
        : "Todavía no corre",
    },
  ];
  const lecturas = [clientes, buzones, permitidos, empresas, cuentas, detector];
  return (
    <section className="rounded-xl border bg-card px-4">
      {lecturas.some((q) => q.isError) ? (
        <NoCargo que="el estado de alguna conexión" className="pt-3" />
      ) : lecturas.some((q) => q.isPending) ? (
        <Cargando className="pt-3">
          Cargando el estado de las conexiones…
        </Cargando>
      ) : null}
      <ul aria-label="Estado" className="list-none m-0 p-0">
        {filas.map((f) => (
          <li
            key={f.titulo}
            className="flex items-center justify-between gap-3 border-b py-3 last:border-b-0"
          >
            <div className="flex flex-col gap-0.5">
              <b className="text-[15px]">{f.titulo}</b>
              <span className="text-[13px] text-muted-foreground">
                {f.detalle}
              </span>
            </div>
            <Insignia estado={f.estado} />
          </li>
        ))}
      </ul>
    </section>
  );
};

// Buzones (KF-11 · c2-puesta-buzones) ------------------------------------

const SeccionBuzones = () => {
  const [abierto, setAbierto] = useState(false);
  const { data = [], isPending } = useBuzones();
  const { data: eventos = [] } = usePermitidos();
  const permitidos = correosPermitidos(eventos);
  const [update] = useUpdate<Buzon>();
  const notify = useNotify();
  // Quitar no borra: activo = false y el lector lo salta.
  const quitar = (b: Buzon) =>
    update(
      "buzones",
      { id: b.id, data: { activo: false }, previousData: b },
      {
        onError: () => notify("No se pudo quitar el buzón", { type: "error" }),
      },
    );
  return (
    <Seccion
      titulo="Buzones"
      boton="+ Agregar buzón"
      onAgregar={() => setAbierto(true)}
    >
      {!isPending && data.length === 0 ? (
        <Vacia texto="Todavía no hay buzones." />
      ) : (
        <ul aria-label="Buzones" className="list-none m-0 p-0">
          {data.map((b) => {
            const estado = estadoBuzon(b.correo, permitidos);
            return (
              <li
                key={b.id}
                className="flex flex-col gap-2 border-b py-3 last:border-b-0 sm:flex-row sm:items-center sm:justify-between"
              >
                <div className="flex min-w-0 items-center gap-2">
                  <b className="break-all text-[15px]">{b.correo}</b>
                  <Insignia estado={estado} />
                </div>
                <div className="flex gap-2">
                  <Button
                    asChild
                    size="sm"
                    variant={estado === "Conectado" ? "outline" : "default"}
                    className="min-h-11 sm:min-h-9"
                  >
                    <a
                      href={urlPermitir(b.correo)}
                      target="_blank"
                      rel="noreferrer"
                    >
                      Permitir
                    </a>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    className="min-h-11 sm:min-h-9"
                    onClick={() => quitar(b)}
                  >
                    Quitar
                  </Button>
                </div>
              </li>
            );
          })}
        </ul>
      )}
      <AgregarBuzon abierto={abierto} setAbierto={setAbierto} />
    </Seccion>
  );
};

const AgregarBuzon = ({
  abierto,
  setAbierto,
}: {
  abierto: boolean;
  setAbierto: (v: boolean) => void;
}) => {
  const [create, { isPending }] = useCreate();
  const [update, { isPending: reactivando }] = useUpdate<Buzon>();
  // Todos, también los quitados: volver a agregar uno lo reactiva.
  const { data: todos = [] } = useGetList<Buzon>("buzones", TODAS);
  const notify = useNotify();
  const autor = useAutor();

  const guardar = (ev: FormEvent<HTMLFormElement>) => {
    ev.preventDefault();
    const f = new FormData(ev.currentTarget);
    const correo = normalizarCorreo(String(f.get("correo") ?? ""));
    const listo = () => {
      registrarEvento("buzon.creado", { correo });
      setAbierto(false);
    };
    const existente = todos.find((b) => normalizarCorreo(b.correo) === correo);
    if (existente?.activo) {
      notify(`${correo} ya está en la lista`, { type: "error" });
      return;
    }
    if (existente) {
      update(
        "buzones",
        { id: existente.id, data: { activo: true }, previousData: existente },
        {
          onSuccess: listo,
          onError: () =>
            notify("No se pudo agregar el buzón", { type: "error" }),
        },
      );
      return;
    }
    create(
      "buzones",
      { data: { correo, activo: true, autor } },
      {
        onSuccess: listo,
        onError: () => notify("No se pudo agregar el buzón", { type: "error" }),
      },
    );
  };

  return (
    <Dialog open={abierto} onOpenChange={setAbierto}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Agregar buzón</DialogTitle>
        </DialogHeader>
        <form onSubmit={guardar} className="flex flex-col gap-3">
          <Campo id="buzon-correo" etiqueta="Correo">
            <Input id="buzon-correo" name="correo" required />
          </Campo>
          <DialogFooter>
            <Button type="submit" disabled={isPending || reactivando}>
              Guardar
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

// Empresas --------------------------------------------------------------

const SeccionEmpresas = () => {
  const [abierto, setAbierto] = useState(false);
  const { data = [], isPending } = useGetList<Empresa>("empresas", TODAS);
  return (
    <Seccion
      titulo="Empresas"
      boton="+ Agregar empresa"
      onAgregar={() => setAbierto(true)}
    >
      {!isPending && data.length === 0 ? (
        <Vacia texto="Todavía no hay empresas." />
      ) : (
        <ul aria-label="Empresas" className="list-none m-0 p-0">
          {data.map((e) => (
            <Fila
              key={e.id}
              titulo={e.nombre}
              detalle={[
                e.ruc ? `RUC ${e.ruc}` : "Sin RUC",
                e.carpeta_facturas ?? "Sin carpeta de facturas",
              ].join(" · ")}
            />
          ))}
        </ul>
      )}
      <AgregarEmpresa abierto={abierto} setAbierto={setAbierto} />
    </Seccion>
  );
};

const AgregarEmpresa = ({
  abierto,
  setAbierto,
}: {
  abierto: boolean;
  setAbierto: (v: boolean) => void;
}) => {
  const [create, { isPending }] = useCreate();
  const [update, { isPending: completando }] = useUpdate<Empresa>();
  const { data: empresas = [] } = useGetList<Empresa>("empresas", TODAS);
  const notify = useNotify();
  const autor = useAutor();

  const guardar = (ev: FormEvent<HTMLFormElement>) => {
    ev.preventDefault();
    const f = new FormData(ev.currentTarget);
    const datos = {
      nombre: String(f.get("nombre") ?? "").trim(),
      ruc: String(f.get("ruc") ?? "").trim() || null,
      carpeta_facturas: String(f.get("carpeta_facturas") ?? "").trim() || null,
      autor,
    };
    // Un RUC es de una sola empresa: si ya lo tiene otra, no se mezclan.
    const conRuc = datos.ruc
      ? empresas.find(
          (e) => e.ruc === datos.ruc && !mismoNombre(e.nombre, datos.nombre),
        )
      : undefined;
    if (conRuc) {
      notify(`El RUC ${datos.ruc} ya es de ${conRuc.nombre}`, {
        type: "error",
      });
      return;
    }
    // KF-14 · decisión de Cesar: la empresa que ya está (la de la semilla) se
    // completa en su misma fila; nunca queda repetida.
    const existente = empresas.find((e) => mismoNombre(e.nombre, datos.nombre));
    if (existente) {
      update(
        "empresas",
        {
          id: existente.id,
          data: {
            ruc: datos.ruc ?? existente.ruc ?? null,
            carpeta_facturas:
              datos.carpeta_facturas ?? existente.carpeta_facturas ?? null,
          },
          previousData: existente,
        },
        {
          onSuccess: () => setAbierto(false),
          onError: () =>
            notify("No se pudo completar la empresa", { type: "error" }),
        },
      );
      return;
    }
    create(
      "empresas",
      { data: datos },
      {
        onSuccess: (empresa) => {
          registrarEvento("empresa.creada", {
            id: empresa.id,
            nombre: datos.nombre,
          });
          setAbierto(false);
        },
        onError: () =>
          notify("No se pudo guardar la empresa", { type: "error" }),
      },
    );
  };

  return (
    <Dialog open={abierto} onOpenChange={setAbierto}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Agregar empresa</DialogTitle>
        </DialogHeader>
        <form onSubmit={guardar} className="flex flex-col gap-3">
          <Campo id="empresa-nombre" etiqueta="Nombre">
            <Input id="empresa-nombre" name="nombre" required />
          </Campo>
          <Campo id="empresa-ruc" etiqueta="RUC">
            <Input id="empresa-ruc" name="ruc" />
          </Campo>
          <Campo id="empresa-carpeta" etiqueta="Carpeta de facturas">
            <Input id="empresa-carpeta" name="carpeta_facturas" />
          </Campo>
          <DialogFooter>
            <Button type="submit" disabled={isPending || completando}>
              Guardar
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

// Cuentas y tarjetas ----------------------------------------------------

const SeccionCuentas = () => {
  const [abierto, setAbierto] = useState(false);
  const { data = [], isPending } = useGetList<Cuenta>("cuentas", TODAS);
  const { data: empresas = [] } = useGetList<Empresa>("empresas", TODAS);
  const empresaDe = (ruc?: string | null) =>
    ruc ? empresas.find((e) => e.ruc === ruc)?.nombre : undefined;
  return (
    <Seccion
      titulo="Cuentas y tarjetas"
      boton="+ Agregar cuenta"
      onAgregar={() => setAbierto(true)}
    >
      {!isPending && data.length === 0 ? (
        <Vacia texto="Todavía no hay cuentas ni tarjetas." />
      ) : (
        <ul aria-label="Cuentas y tarjetas" className="list-none m-0 p-0">
          {data.map((c) => (
            <Fila
              key={c.id}
              titulo={c.nombre}
              detalle={[
                c.tipo === "tarjeta" ? "Tarjeta" : "Cuenta de banco",
                c.ambito === "casa"
                  ? "Casa"
                  : (empresaDe(c.empresa_ruc) ?? "Empresa"),
                c.carpeta_estados ?? "Sin carpeta de estados de cuenta",
              ].join(" · ")}
            />
          ))}
        </ul>
      )}
      <AgregarCuenta abierto={abierto} setAbierto={setAbierto} />
    </Seccion>
  );
};

const AgregarCuenta = ({
  abierto,
  setAbierto,
}: {
  abierto: boolean;
  setAbierto: (v: boolean) => void;
}) => {
  const [create, { isPending }] = useCreate();
  const notify = useNotify();
  const autor = useAutor();
  // KF-14: la cuenta se liga a su empresa por el RUC (cuentas.empresa_ruc).
  const { data: empresas = [] } = useGetList<Empresa>("empresas", TODAS);
  const conRuc = empresas.filter((e) => e.ruc);

  const guardar = (ev: FormEvent<HTMLFormElement>) => {
    ev.preventDefault();
    const f = new FormData(ev.currentTarget);
    const ambito = String(f.get("ambito")) as Cuenta["ambito"];
    const base = {
      dueno: String(f.get("dueno")) as Cuenta["dueno"],
      banco: String(f.get("banco") ?? "").trim() || null,
      tipo: String(f.get("tipo")) as Cuenta["tipo"],
    };
    const datos = {
      ...base,
      nombre: nombreCuenta(base),
      ambito,
      empresa_ruc:
        ambito === "empresa"
          ? String(f.get("empresa_ruc") ?? "") || null
          : null,
      carpeta_estados: String(f.get("carpeta_estados") ?? "").trim() || null,
      autor,
    };
    create(
      "cuentas",
      { data: datos },
      {
        onSuccess: (cuenta) => {
          registrarEvento("cuenta.creada", {
            id: cuenta.id,
            dueno: datos.dueno,
            tipo: datos.tipo,
            ambito: datos.ambito,
          });
          setAbierto(false);
        },
        onError: () =>
          notify("No se pudo guardar la cuenta", { type: "error" }),
      },
    );
  };

  return (
    <Dialog open={abierto} onOpenChange={setAbierto}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Agregar cuenta o tarjeta</DialogTitle>
        </DialogHeader>
        <form onSubmit={guardar} className="flex flex-col gap-3">
          <Campo id="cuenta-dueno" etiqueta="Dueño">
            <select id="cuenta-dueno" name="dueno" className={claseSelect}>
              {DUENOS.map((d) => (
                <option key={d} value={d}>
                  {d}
                </option>
              ))}
            </select>
          </Campo>
          <Campo id="cuenta-banco" etiqueta="Banco">
            <Input id="cuenta-banco" name="banco" required />
          </Campo>
          <Campo id="cuenta-tipo" etiqueta="Tipo">
            <select id="cuenta-tipo" name="tipo" className={claseSelect}>
              <option value="banco">Cuenta de banco</option>
              <option value="tarjeta">Tarjeta</option>
            </select>
          </Campo>
          <Campo id="cuenta-ambito" etiqueta="Empresa o casa">
            <select id="cuenta-ambito" name="ambito" className={claseSelect}>
              <option value="empresa">Empresa</option>
              <option value="casa">Casa</option>
            </select>
          </Campo>
          <Campo id="cuenta-empresa" etiqueta="¿De qué empresa?">
            <select
              id="cuenta-empresa"
              name="empresa_ruc"
              className={claseSelect}
            >
              <option value="">Ninguna</option>
              {conRuc.map((e) => (
                <option key={e.id} value={e.ruc ?? ""}>
                  {e.nombre}
                </option>
              ))}
            </select>
          </Campo>
          <Campo id="cuenta-carpeta" etiqueta="Carpeta de estados de cuenta">
            <Input id="cuenta-carpeta" name="carpeta_estados" />
          </Campo>
          <DialogFooter>
            <Button type="submit" disabled={isPending}>
              Guardar
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

const Campo = ({
  id,
  etiqueta,
  children,
}: {
  id: string;
  etiqueta: string;
  children: ReactNode;
}) => (
  <div className="flex flex-col gap-1.5">
    <Label htmlFor={id}>{etiqueta}</Label>
    {children}
  </div>
);
