// KF-20 · c1-r-validar (R016–R018), c2-validar-* (R051).
// Qué manda la pantalla Validar a la tabla lecciones. Nunca manda autor ni
// decidido_por: los pone el disparador kf_poner_autor de KF-05
// (supabase/migrations/20261111130000_kf_usuarios.sql). En la demo lo imita
// el proveedor FakeRest.
// Descartar solo cambia el estado: las filas de evidencias quedan, y así el
// detector (pc/detector.mjs, KF-18) ignora lo que vuelva con esa evidencia.

export type Leccion = {
  id: number | string;
  categoria?: string | null;
  que_paso: string;
  causa_raiz?: string | null;
  costo_centavos?: number | null;
  solucion?: string | null;
  regla_nueva?: string | null;
  tipo_proyecto?: string | null;
  estado: string;
  decidido_en?: string | null;
  decidido_por?: string | null;
};

/** Lo que se puede editar antes de aprobar (c2-validar-editar). */
export type Edicion = { regla_nueva: string | null };

/** Los cambios de la edición que difieren de la lección. */
export const cambiosEditar = (
  l: Pick<Leccion, "regla_nueva">,
  e: Edicion,
): Partial<Edicion> =>
  (e.regla_nueva ?? null) === (l.regla_nueva ?? null)
    ? {}
    : { regla_nueva: e.regla_nueva };

/** Aprobar guarda la versión en pantalla (editada o no), con su fecha. */
export const cambiosAprobar = (
  l: Pick<Leccion, "regla_nueva">,
  e: Edicion,
  ahora: Date,
) => ({
  ...cambiosEditar(l, e),
  estado: "aprobada",
  decidido_en: ahora.toISOString(),
});

/** Descartar no borra: solo el estado y la fecha. */
export const cambiosDescartar = (ahora: Date) => ({
  estado: "descartada",
  decidido_en: ahora.toISOString(),
});

/** Deshacer: vuelve a los valores de antes en las columnas que tocó la acción. */
export const cambiosDeshacer = (
  antes: Leccion,
  hechos: Record<string, unknown>,
) =>
  Object.fromEntries(
    Object.keys(hechos).map((k) => [
      k,
      (antes as Record<string, unknown>)[k] ?? null,
    ]),
  );
