import type { Identifier } from "ra-core";
import { useEffect, useRef } from "react";

import { registrarEvento } from "../misc/eventos";
import type { Company } from "../types";

/**
 * expediente.abierto, una vez por cliente. Va fuera de la vista: en el celular
 * useIsMobile arranca en falso y la vista se monta dos veces. El ref también
 * aguanta el doble montaje del modo estricto de React.
 */
export const useExpedienteAbierto = (cliente?: Company) => {
  const abierto = useRef<Identifier | null>(null);
  useEffect(() => {
    if (!cliente || abierto.current === cliente.id) return;
    abierto.current = cliente.id;
    registrarEvento("expediente.abierto", {
      cliente_id: cliente.id,
      cliente: cliente.name,
    });
  }, [cliente]);
};
