// Kaizen Files · KF-29 · c2-hoy (R046), maqueta Main.
// La pantalla de entrada: «Te espera» (lecciones por aprobar, minutas sin
// enviar, facturas vencidas) y los proyectos activos. Cada fila abre su
// pantalla. pantalla.abierta lo registra el layout (usePantallaAbierta).
import { useGetList, useGetMany, type Identifier } from "ra-core";
import { useMemo, type ReactNode } from "react";
import { Link } from "react-router";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { estadoCobro, hoyLocal, rucsConCuenta } from "../cobros/estadoCobro";
import { CobrosPage } from "../cobros/CobrosPage";
import { dinero, fechaCorta } from "../expediente/lineaDeTiempo";
import { ValidarPage } from "../lecciones/ValidarPage";
import { Cargando, NoCargo, Vacio } from "../misc/Estados";
import type { Company, Deal } from "../types";
import {
  facturasVencidas,
  LECCION_POR_APROBAR,
  minutaSinEnviar,
  proyectosActivos,
} from "./hoy";

const TODAS = { pagination: { page: 1, perPage: 10000 } };
const POR_ID = { field: "id", order: "ASC" } as const;
/** Proyectos activos que caben en Hoy; el resto está en Clientes. */
const MAX_PROYECTOS = 8;

type LeccionFila = { id: Identifier; que_paso: string; categoria?: string };
type MinutaFila = {
  id: Identifier;
  cliente_id: Identifier;
  texto: string;
  estado?: string;
  creado_en?: string | null;
};
type FacturaFila = {
  id: Identifier;
  empresa_ruc: string;
  numero: string;
  cliente_id?: Identifier | null;
  vence?: string | null;
  monto_centavos: number;
  pagado_centavos?: number;
  estado?: string;
};
type CuentaFila = { id: Identifier; tipo: string; empresa_ruc?: string | null };

const rutaExpediente = (clienteId: Identifier, pestana?: string) =>
  `/companies/${clienteId}/show${pestana ? `?pestana=${pestana}` : ""}`;

/** Un número que sale junto al título del grupo. */
const Conteo = ({ clave, n }: { clave: string; n?: number }) => (
  <Badge variant="secondary" className="tabular-nums" data-conteo={clave}>
    {n ?? "…"}
  </Badge>
);

/** Una fila que abre su pantalla. */
const Fila = ({
  to,
  titulo,
  abajo,
}: {
  to: string;
  titulo: ReactNode;
  abajo?: ReactNode;
}) => (
  <li className="border-b last:border-b-0">
    <Link
      to={to}
      className="flex flex-col gap-0.5 py-3 min-h-11 no-underline text-foreground hover:bg-accent/40 rounded-sm min-w-0"
    >
      <span className="font-medium break-words">{titulo}</span>
      {abajo ? (
        <span className="text-[13px] text-muted-foreground break-words">
          {abajo}
        </span>
      ) : null}
    </Link>
  </li>
);

/** Un grupo de Te espera: título, conteo y sus filas. */
const Grupo = ({
  titulo,
  clave,
  n,
  vacio,
  cargando,
  error,
  children,
}: {
  titulo: string;
  clave: string;
  n?: number;
  vacio: string;
  cargando: boolean;
  error: boolean;
  children: ReactNode;
}) => (
  <div className="flex flex-col gap-1 min-w-0">
    <h3 className="flex items-center gap-2 text-[15px] font-semibold m-0">
      {titulo}
      <Conteo clave={clave} n={cargando || error ? undefined : n} />
    </h3>
    {error ? (
      <NoCargo que={`«${titulo}»`} />
    ) : cargando ? (
      <Cargando />
    ) : n ? (
      <ul aria-label={titulo} className="list-none m-0 p-0">
        {children}
      </ul>
    ) : (
      <Vacio>{vacio}</Vacio>
    )}
  </div>
);

export const HoyPage = () => {
  const lecciones = useGetList<LeccionFila>("lecciones", {
    ...TODAS,
    sort: POR_ID,
    filter: { estado: LECCION_POR_APROBAR },
  });
  const minutasQ = useGetList<MinutaFila>("minutas", {
    ...TODAS,
    sort: { field: "creado_en", order: "DESC" },
  });
  const facturasQ = useGetList<FacturaFila>("facturas", {
    ...TODAS,
    sort: POR_ID,
  });
  const cuentas = useGetList<CuentaFila>("cuentas", { ...TODAS, sort: POR_ID });
  const deals = useGetList<Deal>("deals", { ...TODAS, sort: POR_ID });

  const minutas = useMemo(
    () => (minutasQ.data ?? []).filter(minutaSinEnviar),
    [minutasQ.data],
  );
  const hoy = hoyLocal();
  const vencidas = useMemo(
    () =>
      facturasVencidas(
        facturasQ.data ?? [],
        rucsConCuenta(cuentas.data ?? []),
        hoy,
      ),
    [facturasQ.data, cuentas.data, hoy],
  );
  const activos = useMemo(
    () => proyectosActivos(deals.data ?? []),
    [deals.data],
  );
  const visibles = activos.slice(0, MAX_PROYECTOS);

  // Nombre del cliente de cada fila, en una sola lectura.
  const idsClientes = useMemo(
    () => [
      ...new Set(
        [
          ...minutas.map((m) => m.cliente_id),
          ...vencidas.map((f) => f.cliente_id),
          ...visibles.map((d) => d.company_id),
        ].filter((id): id is Identifier => id != null),
      ),
    ],
    [minutas, vencidas, visibles],
  );
  const { data: clientes } = useGetMany<Company>(
    "companies",
    { ids: idsClientes },
    { enabled: idsClientes.length > 0 },
  );
  const cliente = (id?: Identifier | null) =>
    (clientes ?? []).find((c) => String(c.id) === String(id))?.name ?? "";

  return (
    <div className="flex flex-col gap-5 py-2">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl md:text-[28px] font-bold m-0">Hoy</h1>
        <p className="text-sm text-muted-foreground m-0">
          Lo que espera su decisión
        </p>
      </div>

      <div className="grid gap-5 md:grid-cols-[minmax(0,3fr)_minmax(280px,2fr)] items-start">
        <Card>
          <CardContent>
            <section aria-label="Te espera" className="flex flex-col gap-4">
              <h2 className="text-lg font-semibold m-0">Te espera</h2>

              <Grupo
                titulo="Lecciones por aprobar"
                clave="lecciones"
                n={lecciones.data?.length}
                vacio="Ninguna lección por aprobar."
                cargando={lecciones.isPending}
                error={lecciones.isError}
              >
                {(lecciones.data ?? []).map((l) => (
                  <Fila
                    key={l.id}
                    to={ValidarPage.pathUna.replace(":id", String(l.id))}
                    titulo={l.que_paso}
                    abajo={l.categoria ? `Lección · ${l.categoria}` : "Lección"}
                  />
                ))}
              </Grupo>

              <Grupo
                titulo="Minutas sin enviar"
                clave="minutas"
                n={minutas.length}
                vacio="Ninguna minuta por enviar."
                cargando={minutasQ.isPending}
                error={minutasQ.isError}
              >
                {minutas.map((m) => (
                  <Fila
                    key={m.id}
                    to={rutaExpediente(m.cliente_id, "minutas")}
                    titulo={cliente(m.cliente_id) || "Minuta"}
                    abajo={[fechaCorta(m.creado_en), m.texto.split("\n")[0]]
                      .filter(Boolean)
                      .join(" · ")}
                  />
                ))}
              </Grupo>

              <Grupo
                titulo="Facturas vencidas"
                clave="facturas"
                n={vencidas.length}
                vacio="Ninguna factura vencida."
                cargando={facturasQ.isPending || cuentas.isPending}
                error={facturasQ.isError || cuentas.isError}
              >
                {vencidas.map((f) => (
                  <Fila
                    key={f.id}
                    to={CobrosPage.path}
                    titulo={`Factura ${f.numero} · ${dinero(
                      f.monto_centavos - (f.pagado_centavos ?? 0),
                    )}`}
                    abajo={[
                      cliente(f.cliente_id),
                      f.vence ? `venció ${fechaCorta(f.vence)}` : "",
                      estadoCobro(f, rucsConCuenta(cuentas.data ?? []), hoy),
                    ]
                      .filter(Boolean)
                      .join(" · ")}
                  />
                ))}
              </Grupo>
            </section>
          </CardContent>
        </Card>

        <Card>
          <CardContent>
            <section
              aria-label="Proyectos activos"
              className="flex flex-col gap-2"
            >
              <h2 className="flex items-center gap-2 text-lg font-semibold m-0">
                Proyectos activos
                <Conteo
                  clave="proyectos"
                  n={
                    deals.isPending || deals.isError
                      ? undefined
                      : activos.length
                  }
                />
              </h2>
              {deals.isError ? (
                <NoCargo que="los proyectos activos" />
              ) : deals.isPending ? (
                <Cargando />
              ) : visibles.length ? (
                <ul
                  aria-label="Proyectos activos"
                  className="list-none m-0 p-0"
                >
                  {visibles.map((d) => (
                    <Fila
                      key={d.id}
                      to={rutaExpediente(d.company_id)}
                      titulo={d.name}
                      abajo={cliente(d.company_id)}
                    />
                  ))}
                </ul>
              ) : (
                <Vacio>Ningún proyecto activo.</Vacio>
              )}
              {activos.length > visibles.length ? (
                <Link
                  to="/clientes"
                  className="inline-flex items-center min-h-11 text-sm font-medium underline"
                >
                  Ver los {activos.length} en Clientes
                </Link>
              ) : null}
            </section>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

HoyPage.path = "/";
