// Kaizen Files · KF-24 · c1-r-punto-partida (R022–R024) y c2-punto-*
// (R054), maqueta PuntoPartida (no está en disco: se siguió 04-diseno.json).
// Lo aprendido se lee de `reglas` (KF-23). Los parecidos se buscan por tipo
// de proyecto, nunca por número de lección: en la demo las lecciones se
// renumeran al recargar y solo `reglas` sobrevive.
import type { Identifier } from "ra-core";

import type { Regla } from "../lecciones/reglas";

export const RUTA_PUNTO_PARTIDA = "/punto-partida";

/** Mismo tipo aunque cambien mayúsculas, tildes o espacios. */
export const normalizarTipo = (t: string | null | undefined) =>
  (t ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();

export type Aprendido = {
  /** true: no hubo parecidos y se usan las reglas sin tipo. */
  generales: boolean;
  /** Proyectos similares: lecciones distintas detrás de las reglas. */
  similares: number;
  checklist: Regla[];
  clausulas: Regla[];
};

/** Las reglas que tocan a un tipo de proyecto; si no hay, las generales. */
export const aprendidoPara = (reglas: Regla[], tipo: string): Aprendido => {
  const clave = normalizarTipo(tipo);
  const parecidas = reglas.filter(
    (r) => clave && normalizarTipo(r.tipo_proyecto) === clave,
  );
  const generales = !parecidas.length;
  const usadas = generales
    ? reglas.filter((r) => !normalizarTipo(r.tipo_proyecto))
    : parecidas;
  const origenes = new Set(
    usadas.map((r) => (r.leccion_id == null ? `r${r.id}` : `l${r.leccion_id}`)),
  );
  return {
    generales,
    similares: generales ? 0 : origenes.size,
    checklist: usadas.filter((r) => r.forma === "checklist"),
    clausulas: usadas.filter((r) => r.forma === "clausula"),
  };
};

export const deSimilares = (n: number) =>
  `De ${n} ${n === 1 ? "proyecto similar" : "proyectos similares"}`;

/** Tipos con reglas guardadas, para sugerirlos al escribir. */
export const tiposConReglas = (reglas: Regla[]) => {
  const vistos = new Map<string, string>();
  for (const r of reglas) {
    const t = r.tipo_proyecto?.trim();
    if (t && !vistos.has(normalizarTipo(t))) vistos.set(normalizarTipo(t), t);
  }
  return [...vistos.values()].sort((a, b) => a.localeCompare(b, "es"));
};

export type Datos = { nombre: string; tipo: string; cliente: string };
export type Falta = keyof Datos;

/** Lo que falta para crear el proyecto, en el orden del formulario. */
export const faltantes = (d: Datos): Falta[] =>
  (["nombre", "tipo", "cliente"] as const).filter((k) => !d[k].trim());

export const AVISO_FALTA: Record<Falta, string> = {
  nombre: "Escribe el nombre del proyecto.",
  tipo: "Falta el tipo de proyecto. Escríbelo para crear el proyecto.",
  cliente: "Elige el cliente.",
};

export type ItemChecklist = {
  regla_id: Identifier | null;
  forma: string;
  texto: string;
  hecho: boolean;
};

/** La fila que se guarda en `punto_partida`. */
export const filaProyecto = (d: Datos, items: ItemChecklist[]) => ({
  nombre: d.nombre.trim(),
  tipo_proyecto: d.tipo.trim(),
  cliente_id: Number(d.cliente),
  checklist: items,
});

export const rutaExpediente = (clienteId: Identifier, proyectoId: Identifier) =>
  `/companies/${clienteId}/show?proyecto=${proyectoId}`;
