// KF-05 · c1-r-usuarios (R033). Solo entran cuentas de DPB.
// La misma regla vive en la base (supabase/migrations/20261111130000_kf_usuarios.sql);
// esta copia solo da el aviso claro en el ingreso.
export const DOMINIO_DPB = "dynamicpanamabuilders.com";

export const AVISO_FUERA_DE_DPB = `Solo entran cuentas @${DOMINIO_DPB}.`;

export const esDeDpb = (correo: unknown): boolean =>
  typeof correo === "string" &&
  /^[^@\s]+@dynamicpanamabuilders\.com$/i.test(correo.trim());
