// Kaizen Files · KF-07 · c2-clientes-lista (R047, maqueta Clientes).
// Arma las filas de la lista: cliente = companies, proyecto = deals,
// contacto = contacts. Funciones puras para que la regla quede en un lugar.
import type { Company, Contact, Deal } from "../types";
import { norm } from "./leerClientesCsv";

export type Filtro = "clientes" | "activos" | "cerrados";

export const FILTROS: { id: Filtro; nombre: string }[] = [
  { id: "clientes", nombre: "Clientes" },
  { id: "activos", nombre: "Proyectos activos" },
  { id: "cerrados", nombre: "Cerrados" },
];

/**
 * Un proyecto está cerrado si se archivó o se perdió. Lo demás está activo.
 * KF-25 (Cerrar proyecto) puede afinar esta regla aquí mismo.
 */
export const proyectoCerrado = (d: Pick<Deal, "stage" | "archived_at">) =>
  !!d.archived_at || d.stage === "lost";

export type FilaCliente = {
  id: Company["id"];
  nombre: string;
  proyectos: { nombre: string; cerrado: boolean }[];
  activos: number;
  cerrados: number;
  contactos: string[];
};

export function armarFilas(
  companies: Company[],
  deals: Deal[],
  contacts: Contact[],
): FilaCliente[] {
  return companies
    .map((c) => {
      const proyectos = deals
        .filter((d) => d.company_id === c.id)
        .map((d) => ({ nombre: d.name, cerrado: proyectoCerrado(d) }))
        .sort((a, b) => Number(a.cerrado) - Number(b.cerrado));
      const activos = proyectos.filter((p) => !p.cerrado).length;
      return {
        id: c.id,
        nombre: c.name,
        proyectos,
        activos,
        cerrados: proyectos.length - activos,
        contactos: contacts
          .filter((p) => p.company_id === c.id)
          .map((p) => `${p.first_name ?? ""} ${p.last_name ?? ""}`.trim()),
      };
    })
    .sort((a, b) => a.nombre.localeCompare(b.nombre, "es"));
}

/** Busca por cliente, proyecto o contacto, sin acentos ni mayúsculas. */
export function filtrarFilas(
  filas: FilaCliente[],
  texto: string,
  filtro: Filtro,
): FilaCliente[] {
  const q = norm(texto);
  return filas.filter((f) => {
    if (filtro === "activos" && f.activos === 0) return false;
    if (filtro === "cerrados" && (f.activos > 0 || f.cerrados === 0))
      return false;
    if (!q) return true;
    return [f.nombre, ...f.proyectos.map((p) => p.nombre), ...f.contactos].some(
      (t) => norm(t).includes(q),
    );
  });
}

/** «2 activos», «Cerrado», «Sin proyectos». */
export const estadoFila = (f: FilaCliente) =>
  f.activos > 0
    ? `${f.activos} ${f.activos === 1 ? "activo" : "activos"}`
    : f.cerrados > 0
      ? "Cerrado"
      : "Sin proyectos";
