// Kaizen Files · KF-24 · Punto de Partida (maqueta PuntoPartida).
// c2-punto-datos: nombre, tipo y cliente. c2-punto-checklist: checklist,
// riesgos y cláusulas «de N proyectos similares», con casillas.
// c2-punto-iniciar: crea la fila de `punto_partida`, registra proyecto.creado
// y abre el expediente del cliente con el proyecto nuevo.
// Lo aprendido sale de `reglas` (KF-23); los riesgos, de las lecciones
// aprobadas del mismo tipo. Ambos se cruzan por tipo, no por número.
import { useCreate, useGetList, type Identifier } from "ra-core";
import { useRef, useState, type ReactNode } from "react";
import { Link, useNavigate } from "react-router";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { registrarEvento } from "../misc/eventos";
import { Cargando, EstadoDatos } from "../misc/Estados";
import type { LeccionBiblioteca } from "../lecciones/biblioteca";
import type { Regla } from "../lecciones/reglas";
import type { Company } from "../types";
import {
  AVISO_FALTA,
  RUTA_PUNTO_PARTIDA,
  aprendidoPara,
  deSimilares,
  faltantes,
  filaProyecto,
  normalizarTipo,
  rutaExpediente,
  tiposConReglas,
  type Datos,
  type Falta,
} from "./puntoPartida";

const TODO = { page: 1, perPage: 1000 };

export const PuntoPartidaPage = () => {
  const navigate = useNavigate();
  const [datos, setDatos] = useState<Datos>({
    nombre: "",
    tipo: "",
    cliente: "",
  });
  const [faltan, setFaltan] = useState<Falta[]>([]);
  const [hechos, setHechos] = useState<Set<string>>(new Set());
  const campos = useRef<Partial<Record<Falta, HTMLElement | null>>>({});
  const [create, { isPending: creando }] = useCreate();

  const reglas = useGetList<Regla>("reglas", {
    pagination: TODO,
    sort: { field: "id", order: "ASC" },
  });
  const lecciones = useGetList<LeccionBiblioteca>("lecciones", {
    pagination: TODO,
    sort: { field: "id", order: "ASC" },
    filter: { estado: "aprobada" },
  });
  const clientes = useGetList<Company>("companies", {
    pagination: TODO,
    sort: { field: "name", order: "ASC" },
  });

  const tipo = datos.tipo.trim();
  const aprendido = aprendidoPara(reglas.data ?? [], tipo);
  const riesgos = tipo
    ? (lecciones.data ?? []).filter(
        (l) => normalizarTipo(l.tipo_proyecto) === normalizarTipo(tipo),
      )
    : [];

  const cambiar = (k: Falta, v: string) => {
    setDatos((d) => ({ ...d, [k]: v }));
    setFaltan((f) => f.filter((x) => x !== k));
  };
  const marcar = (clave: string, si: boolean) =>
    setHechos((h) => {
      const n = new Set(h);
      if (si) n.add(clave);
      else n.delete(clave);
      return n;
    });

  const iniciar = () => {
    if (creando) return;
    const f = faltantes(datos);
    setFaltan(f);
    if (f.length) return campos.current[f[0]]?.focus();
    const items = [...aprendido.checklist, ...aprendido.clausulas].map((r) => ({
      regla_id: r.id,
      forma: r.forma,
      texto: r.texto,
      hecho: hechos.has(`regla-${r.id}`),
    }));
    const fila = filaProyecto(datos, items);
    create(
      "punto_partida",
      { data: fila },
      {
        onSuccess: (p: { id: Identifier }) => {
          registrarEvento("proyecto.creado", {
            punto_partida_id: p.id,
            nombre: fila.nombre,
            tipo_proyecto: fila.tipo_proyecto,
            cliente_id: fila.cliente_id,
            similares: aprendido.similares,
            generales: aprendido.generales,
          });
          navigate(rutaExpediente(fila.cliente_id, p.id));
        },
      },
    );
  };

  const invalido = (k: Falta) => (faltan.includes(k) ? true : undefined);
  const ref = (k: Falta) => (n: HTMLElement | null) => {
    campos.current[k] = n;
  };

  return (
    <div className="flex flex-col gap-4 py-2 max-w-3xl">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl font-semibold">Punto de Partida</h1>
        <p className="text-muted-foreground">
          Cada proyecto nuevo arranca con lo aprendido en los parecidos.
        </p>
        <Link
          to="/clientes"
          className="inline-flex min-h-11 items-center self-start text-sm font-semibold"
        >
          ← Clientes
        </Link>
      </div>

      <section
        aria-label="Datos del proyecto"
        className="flex flex-col gap-3 rounded-xl border bg-card p-4"
      >
        <h2 className="text-lg font-semibold">Datos del proyecto</h2>
        <div className="flex flex-col gap-1.5">
          <Label htmlFor="pp-nombre">Nombre del proyecto</Label>
          <Input
            id="pp-nombre"
            ref={ref("nombre")}
            className="min-h-11"
            value={datos.nombre}
            onChange={(e) => cambiar("nombre", e.target.value)}
            aria-invalid={invalido("nombre")}
          />
        </div>
        <div className="flex flex-col gap-1.5">
          <Label htmlFor="pp-tipo">Tipo de proyecto</Label>
          <Input
            id="pp-tipo"
            ref={ref("tipo")}
            list="pp-tipos"
            className="min-h-11"
            placeholder="Escolar, comercial, residencial…"
            value={datos.tipo}
            onChange={(e) => cambiar("tipo", e.target.value)}
            aria-invalid={invalido("tipo")}
          />
          <datalist id="pp-tipos">
            {tiposConReglas(reglas.data ?? []).map((t) => (
              <option key={t} value={t} />
            ))}
          </datalist>
        </div>
        <div className="flex flex-col gap-1.5">
          <Label htmlFor="pp-cliente">Cliente</Label>
          <select
            id="pp-cliente"
            ref={ref("cliente")}
            className="min-h-11 w-full min-w-0 rounded-md border bg-transparent px-3 text-sm"
            value={datos.cliente}
            onChange={(e) => cambiar("cliente", e.target.value)}
            aria-invalid={invalido("cliente")}
          >
            <option value="">
              {clientes.isPending ? "Cargando…" : "Elige el cliente"}
            </option>
            {(clientes.data ?? []).map((c) => (
              <option key={c.id} value={String(c.id)}>
                {c.name}
              </option>
            ))}
          </select>
          <EstadoDatos
            consultas={[clientes]}
            que="la lista de clientes"
            hayDatos={(clientes.data ?? []).length > 0}
            vacio="Todavía no hay clientes. Agréguelos en Clientes antes de iniciar el proyecto."
            cargando="Cargando clientes…"
          >
            {null}
          </EstadoDatos>
        </div>
      </section>

      <section
        aria-label="Lo aprendido"
        className="flex flex-col gap-3 rounded-xl border bg-card p-4"
      >
        <h2 className="text-lg font-semibold">Lo aprendido</h2>
        {reglas.isError ? (
          <p
            role="alert"
            data-estado="error"
            className="text-sm text-destructive"
          >
            No se pudieron leer las reglas. Puedes crear el proyecto igual.
          </p>
        ) : !tipo ? (
          <p className="text-muted-foreground">
            Escribe el tipo de proyecto para ver lo aprendido en proyectos
            parecidos.
          </p>
        ) : reglas.isPending ? (
          <Cargando />
        ) : (
          <>
            {aprendido.generales ? (
              <p
                role="note"
                className="rounded-md bg-amber-50 p-3 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100"
              >
                No hay proyectos parecidos de tipo «{tipo}». Se usan las reglas
                generales.
              </p>
            ) : (
              <p className="text-sm font-semibold">
                {deSimilares(aprendido.similares)} · {tipo}
              </p>
            )}
            <Grupo nombre="Checklist" vacio="Sin checklist.">
              {aprendido.checklist.map((r) => (
                <Casilla
                  key={r.id}
                  clave={`regla-${r.id}`}
                  texto={r.texto}
                  hechos={hechos}
                  marcar={marcar}
                />
              ))}
            </Grupo>
            <Grupo nombre="Riesgos" vacio="Sin riesgos registrados.">
              {riesgos.map((l) => (
                <Casilla
                  key={l.id}
                  clave={`riesgo-${l.id}`}
                  texto={l.que_paso ?? ""}
                  hechos={hechos}
                  marcar={marcar}
                />
              ))}
            </Grupo>
            <Grupo nombre="Cláusulas" vacio="Sin cláusulas.">
              {aprendido.clausulas.map((r) => (
                <Casilla
                  key={r.id}
                  clave={`regla-${r.id}`}
                  texto={r.texto}
                  hechos={hechos}
                  marcar={marcar}
                />
              ))}
            </Grupo>
          </>
        )}
      </section>

      {faltan.length ? (
        <div role="alert" className="text-sm text-destructive">
          {faltan.map((k) => (
            <p key={k}>{AVISO_FALTA[k]}</p>
          ))}
        </div>
      ) : null}
      <Button
        className="min-h-11 self-start"
        onClick={iniciar}
        disabled={creando}
      >
        Iniciar proyecto
      </Button>
    </div>
  );
};

PuntoPartidaPage.path = RUTA_PUNTO_PARTIDA;

const Grupo = ({
  nombre,
  vacio,
  children,
}: {
  nombre: string;
  vacio: string;
  children: ReactNode[];
}) => (
  <fieldset className="flex min-w-0 flex-col gap-1">
    <legend className="mb-1 font-semibold">{nombre}</legend>
    {children.length ? (
      children
    ) : (
      <p className="text-sm text-muted-foreground">{vacio}</p>
    )}
  </fieldset>
);

const Casilla = ({
  clave,
  texto,
  hechos,
  marcar,
}: {
  clave: string;
  texto: string;
  hechos: Set<string>;
  marcar: (clave: string, si: boolean) => void;
}) => (
  <label className="flex min-h-11 items-start gap-3 py-1 text-sm">
    <input
      type="checkbox"
      className="mt-0.5 size-5 shrink-0"
      checked={hechos.has(clave)}
      onChange={(e) => marcar(clave, e.target.checked)}
    />
    <span className="min-w-0 break-words">{texto}</span>
  </label>
);
