// Lee un PDF de texto y lo devuelve como páginas → filas → piezas con su posición.
// `getDocument` se inyecta: en la app llega de cargar.ts (import dinámico),
// en las pruebas de pdfjs-dist/legacy.
import type { getDocument as GetDocument } from "pdfjs-dist";

export type Pieza = { t: string; x: number; y: number; ancho: number };
export type Fila = { y: number; piezas: Pieza[]; texto: string };
export type Paginas = Fila[][];

const TOLERANCIA_Y = 2.5;

export async function filasPdf(
  bytes: Uint8Array,
  getDocument: typeof GetDocument,
): Promise<Paginas> {
  const tarea = getDocument({
    data: new Uint8Array(bytes),
    verbosity: 0,
  });
  const doc = await tarea.promise;
  const paginas: Paginas = [];
  for (let p = 1; p <= doc.numPages; p++) {
    const pagina = await doc.getPage(p);
    const contenido = await pagina.getTextContent();
    const piezas: Pieza[] = contenido.items
      .filter((i) => "str" in i && i.str.trim())
      .map((i) => {
        const it = i as { str: string; transform: number[]; width: number };
        return {
          t: it.str.trim(),
          x: it.transform[4],
          y: it.transform[5],
          ancho: it.width,
        };
      });
    piezas.sort((a, b) => b.y - a.y || a.x - b.x);
    const filas: Fila[] = [];
    for (const pieza of piezas) {
      let fila = filas.find((f) => Math.abs(f.y - pieza.y) < TOLERANCIA_Y);
      if (!fila) {
        fila = { y: pieza.y, piezas: [], texto: "" };
        filas.push(fila);
      }
      fila.piezas.push(pieza);
    }
    for (const f of filas) {
      f.piezas.sort((a, b) => a.x - b.x);
      f.texto = f.piezas.map((x) => x.t).join(" ");
    }
    paginas.push(filas.sort((a, b) => b.y - a.y));
  }
  await tarea.destroy();
  return paginas;
}
