// Kaizen Files · KF-16 · c1-r-presupuesto (R040–R042), c2-presupuesto-mes,
// -resumen, -categorias y -clasificar (R059), maqueta Presupuesto.
// Reemplaza la pantalla provisional de KF-06 en /presupuesto.
// Lo que suma, empareja y marca neutro es kaizen/lectores/presupuesto.ts
// (KF-15) por medio de vistaPresupuesto.ts; aquí solo se muestra y se guarda
// lo que Cesar elige. Casa o empresa sale del dueño de cada cuenta y de su
// empresa ligada por el RUC (KF-04/KF-14). Montos en centavos (comun.ts).
// KF-17: pagos fijos, «de dónde entró» y las acciones (accionesPresupuesto.tsx).
import { useDataProvider, useGetIdentity, useGetList } from "ra-core";
import { useMemo, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

import { dinero } from "@/kaizen/lectores/comun";
import type { EstadoCategoria } from "@/kaizen/lectores/presupuesto";
import { hoyLocal } from "../cobros/estadoCobro";
import { fechaCorta } from "../expediente/lineaDeTiempo";
import { registrarEvento } from "../misc/eventos";
import { Cargando, NoCargo, Vacio } from "../misc/Estados";
import { AccionesPresupuesto } from "./accionesPresupuesto";
import {
  GRUPO,
  mesesDe,
  nombreMes,
  nombreOrigen,
  patronDe,
  verMes,
  type CategoriaFila,
  type CuentaFila,
  type MovimientoFila,
  type MovimientoVisto,
  type PagoFijoFila,
  type PresupuestoFila,
  type ReglaFila,
  type Vista,
} from "./vistaPresupuesto";

const TODAS = {
  pagination: { page: 1, perPage: 10000 },
  sort: { field: "id", order: "ASC" as const },
};

const VISTAS: { valor: Vista; nombre: string }[] = [
  { valor: "todo", nombre: "Todo" },
  { valor: "casa", nombre: "Solo casa" },
  { valor: "empresa", nombre: "Solo empresa" },
];

/** Valor del selector para «entre mis cuentas»: no es una categoría. */
const ENTRE_MIS_CUENTAS = "entre-mis-cuentas";

const COLOR_ESTADO: Record<EstadoCategoria, string> = {
  Bien: "bg-emerald-100 text-emerald-900 dark:bg-emerald-950 dark:text-emerald-100",
  Cerca: "bg-amber-100 text-amber-900 dark:bg-amber-950 dark:text-amber-100",
  "Al tope":
    "bg-orange-100 text-orange-900 dark:bg-orange-950 dark:text-orange-100",
  Pasado: "bg-red-100 text-red-900 dark:bg-red-950 dark:text-red-100",
};

export const PresupuestoPage = () => {
  const cuentas = useGetList<CuentaFila>("cuentas", TODAS);
  const movimientos = useGetList<MovimientoFila>("movimientos", TODAS);
  const categorias = useGetList<CategoriaFila>("categorias", TODAS);
  const reglas = useGetList<ReglaFila>("reglas_categoria", TODAS);
  const presupuestos = useGetList<PresupuestoFila & { id: number }>(
    "presupuestos",
    TODAS,
  );
  const fijos = useGetList<PagoFijoFila>("pagos_fijos", TODAS);
  const consultas = [
    cuentas,
    movimientos,
    categorias,
    reglas,
    presupuestos,
    fijos,
  ];
  const cargando = consultas.some((q) => q.isPending);
  const fallo = consultas.some((q) => q.isError);

  const hoy = hoyLocal();
  const meses = useMemo(
    () => mesesDe(movimientos.data ?? [], hoy),
    [movimientos.data, hoy],
  );
  const [mesElegido, setMes] = useState<string | null>(null);
  const mes = mesElegido && meses.includes(mesElegido) ? mesElegido : meses[0];
  const [vista, setVista] = useState<Vista>("todo");

  const r = useMemo(
    () =>
      verMes(
        {
          cuentas: cuentas.data ?? [],
          movimientos: movimientos.data ?? [],
          categorias: categorias.data ?? [],
          reglas: reglas.data ?? [],
          presupuestos: presupuestos.data ?? [],
          fijos: fijos.data ?? [],
        },
        { mes, vista, hoy },
      ),
    [
      cuentas.data,
      movimientos.data,
      categorias.data,
      reglas.data,
      presupuestos.data,
      fijos.data,
      mes,
      vista,
      hoy,
    ],
  );

  const refrescar = () =>
    Promise.all([movimientos.refetch(), reglas.refetch()]);
  const refrescarTodo = () => Promise.all(consultas.map((q) => q.refetch()));

  return (
    <div className="flex flex-col gap-5 py-2">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl md:text-[28px] font-bold m-0">Presupuesto</h1>
        <p className="text-sm text-muted-foreground m-0">
          Gastado contra presupuestado, empresa y casa juntas
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <select
          aria-label="Mes"
          className="min-h-11 rounded-md border bg-background px-2 text-sm"
          value={mes}
          onChange={(e) => setMes(e.target.value)}
        >
          {meses.map((m) => (
            <option key={m} value={m}>
              {nombreMes(m)}
            </option>
          ))}
        </select>
        <div
          role="radiogroup"
          aria-label="Vista"
          className="inline-flex rounded-md border p-0.5 max-w-full"
        >
          {VISTAS.map((v) => (
            <button
              key={v.valor}
              type="button"
              role="radio"
              aria-checked={vista === v.valor}
              onClick={() => setVista(v.valor)}
              className={`min-h-10 px-3 rounded text-sm whitespace-nowrap ${
                vista === v.valor
                  ? "bg-primary text-primary-foreground font-semibold"
                  : "text-muted-foreground"
              }`}
            >
              {v.nombre}
            </button>
          ))}
        </div>
      </div>

      <AccionesPresupuesto
        datos={{
          mes,
          cuentas: cuentas.data ?? [],
          categorias: categorias.data ?? [],
          presupuestos: presupuestos.data ?? [],
          fijos: fijos.data ?? [],
        }}
        alGuardar={refrescarTodo}
      />

      {fallo ? (
        <NoCargo que="el presupuesto" />
      ) : cargando ? (
        <Cargando />
      ) : (
        <>
          {(movimientos.data ?? []).length ? null : (
            <Vacio>
              Todavía no hay movimientos. Toque «Leer estados de cuenta» para
              traerlos.
            </Vacio>
          )}
          <section
            aria-label="Resumen"
            className="grid grid-cols-2 md:grid-cols-4 gap-3"
          >
            <Dato etiqueta="Entró" nombre="entro" valor={dinero(r.entro)} />
            <Dato etiqueta="Salió" nombre="salio" valor={dinero(r.salio)} />
            <Dato
              etiqueta="Balance"
              nombre="balance"
              valor={dinero(r.balance)}
              negativo={r.balance < 0}
            />
            <Dato
              etiqueta="Por clasificar"
              nombre="por-clasificar"
              valor={String(r.porClasificar)}
            />
          </section>

          <Categorias categorias={r.categorias} />

          <div className="grid gap-5 md:grid-cols-2">
            <PagosFijos fijos={r.pagosFijos} />
            <DeDondeEntro origenes={r.origenes} />
          </div>

          {r.porClasificarLista.length ? (
            <PorClasificar
              movimientos={r.porClasificarLista}
              categorias={categorias.data ?? []}
              cuentas={cuentas.data ?? []}
              alClasificar={refrescar}
            />
          ) : null}
        </>
      )}
    </div>
  );
};

PresupuestoPage.path = "/presupuesto";

const Dato = ({
  etiqueta,
  nombre,
  valor,
  negativo = false,
}: {
  etiqueta: string;
  nombre: string;
  valor: string;
  negativo?: boolean;
}) => (
  <Card className="py-3">
    <CardContent className="flex flex-col gap-0.5 px-4">
      <span className="text-xs text-muted-foreground">{etiqueta}</span>
      <span
        data-dato={nombre}
        className={`text-lg md:text-xl font-semibold tabular-nums ${
          negativo ? "text-destructive" : ""
        }`}
      >
        {valor}
      </span>
    </CardContent>
  </Card>
);

