/** c2-presupuesto-ingresos: transferencias de las empresas, alquileres, otros. */
const DeDondeEntro = ({ origenes }: { origenes: Record<string, number> }) => {
  const lista = Object.entries(origenes);
  const total = lista.reduce((s, [, monto]) => s + monto, 0);
  return (
    <Card>
      <CardContent>
        <section aria-label="De dónde entró" className="flex flex-col gap-2">
          <h2 className="text-lg font-semibold m-0">De dónde entró</h2>
          {!lista.length ? (
            <p className="text-sm text-muted-foreground m-0">
              No entró nada este mes.
            </p>
          ) : (
            <ul
              aria-label="De dónde entró"
              className="list-none m-0 p-0 text-sm"
            >
              {lista.map(([origen, monto]) => (
                <li
                  key={origen}
                  className="flex justify-between gap-3 py-2.5 border-b last:border-b-0"
                >
                  <span data-col="origen" className="min-w-0 break-words">
                    {nombreOrigen(origen)}
                  </span>
                  <span data-col="monto" className="tabular-nums">
                    {dinero(monto)}
                  </span>
                </li>
              ))}
            </ul>
          )}
          <p className="flex justify-between gap-3 m-0 text-sm font-semibold">
            <span>Total</span>
            <span data-col="total" className="tabular-nums">
              {dinero(total)}
            </span>
          </p>
        </section>
      </CardContent>
    </Card>
  );
};

const PorClasificar = ({
  movimientos,
  categorias,
  cuentas,
  alClasificar,
}: {
  movimientos: MovimientoVisto[];
  categorias: CategoriaFila[];
  cuentas: CuentaFila[];
  alClasificar: () => Promise<unknown>;
}) => (
  <Card>
    <CardContent className="flex flex-col gap-2">
      <h2 className="text-lg font-semibold m-0">Por clasificar</h2>
      <p className="text-sm text-muted-foreground m-0">
        No suman a ninguna categoría hasta que se elija.
      </p>
      <ul aria-label="Por clasificar" className="list-none m-0 p-0 text-sm">
        {movimientos.map((m) => (
          <ItemPorClasificar
            key={String(m.fila.id)}
            m={m}
            categorias={categorias}
            cuenta={cuentas.find((c) => String(c.id) === m.cuenta)}
            alClasificar={alClasificar}
          />
        ))}
      </ul>
    </CardContent>
  </Card>
);

const ItemPorClasificar = ({
  m,
  categorias,
  cuenta,
  alClasificar,
}: {
  m: MovimientoVisto;
  categorias: CategoriaFila[];
  cuenta?: CuentaFila;
  alClasificar: () => Promise<unknown>;
}) => {
  const dp = useDataProvider();
  const { identity } = useGetIdentity();
  const [eleccion, setEleccion] = useState("");
  const [recordar, setRecordar] = useState(false);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const patron = patronDe(m.descripcion);
  const esEntreCuentas = eleccion === ENTRE_MIS_CUENTAS;
  const id = `clasificar-${m.fila.id}`;

  const guardar = async () => {
    const categoria = categorias.find((c) => String(c.id) === eleccion);
    if (!categoria && !esEntreCuentas) return;
    const autor = identity?.fullName ?? null;
    const aprende = recordar && !!categoria;
    setGuardando(true);
    setError(null);
    try {
      await dp.update<MovimientoFila>("movimientos", {
        id: m.fila.id,
        data: categoria
          ? { estado: "clasificado", categoria_id: categoria.id }
          : { estado: "transferencia_interna", categoria_id: null },
        previousData: m.fila,
      });
      if (aprende)
        await dp.create("reglas_categoria", {
          data: { patron, categoria_id: categoria.id, autor },
        });
      registrarEvento("movimiento.clasificado", {
        movimiento_id: m.fila.id,
        categoria: categoria ? categoria.nombre : "Entre mis cuentas",
        categoria_id: categoria?.id ?? null,
        recordar: aprende,
        ...(aprende ? { patron } : {}),
      });
      await alClasificar();
    } catch (e) {
      setError((e as Error).message);
      setGuardando(false);
    }
  };

  const porGrupo = (["casa", "empresa"] as const).map((a) => ({
    grupo: GRUPO[a],
    lista: categorias.filter((c) => c.ambito === a),
  }));

  return (
    <li className="flex flex-col gap-2 py-3 border-b last:border-b-0">
      <span className="flex flex-wrap justify-between gap-x-3">
        <span className="min-w-0 break-words">
          {fechaCorta(m.fecha)} · <b>{m.descripcion}</b>
          {cuenta ? ` · ${cuenta.nombre ?? cuenta.dueno}` : ""}
        </span>
        <span className="tabular-nums font-medium">{dinero(m.monto)}</span>
      </span>
      <span className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <select
          aria-label="Categoría"
          className="min-h-11 max-w-full rounded-md border bg-background px-2 text-sm"
          value={eleccion}
          onChange={(e) => setEleccion(e.target.value)}
        >
          <option value="">Elegir categoría…</option>
          {porGrupo.map((g) =>
            g.lista.length ? (
              <optgroup key={g.grupo} label={g.grupo}>
                {g.lista.map((c) => (
                  <option key={String(c.id)} value={String(c.id)}>
                    {c.nombre}
                  </option>
                ))}
              </optgroup>
            ) : null,
          )}
          <option value={ENTRE_MIS_CUENTAS}>Entre mis cuentas</option>
        </select>
        <label
          htmlFor={id}
          className="inline-flex items-center gap-2 min-h-11 min-w-0"
        >
          <input
            id={id}
            type="checkbox"
            className="size-4"
            checked={recordar && !esEntreCuentas}
            disabled={esEntreCuentas}
            onChange={(e) => setRecordar(e.target.checked)}
          />
          <span className="min-w-0 break-words">
            Recordar para los próximos («{patron}»)
          </span>
        </label>
        <Button
          className="min-h-11"
          disabled={!eleccion || guardando}
          onClick={guardar}
        >
          Clasificar
        </Button>
      </span>
      {error ? (
        <span role="alert" className="text-destructive">
          No se guardó: {error}
        </span>
      ) : null}
    </li>
  );
};
