// Kaizen Files · KF-08 · c1-r-expediente (R001–R003), maqueta Expediente.
// Junta correos, minutas y facturas de un cliente en una sola línea de tiempo
// ordenada por fecha, de la más nueva a la más vieja. Funciones puras.
// Columnas según supabase/migrations/20261111120000_kf_tablas.sql (KF-03).

export type Correo = {
  id: number;
  de?: string | null;
  asunto?: string | null;
  fecha?: string | null;
  enlace?: string | null;
  cliente_ids?: number[];
};

export type Minuta = {
  id: number;
  texto: string;
  acuerdos?: string | null;
  estado?: "borrador" | "ordenada" | "enviada";
  creado_en?: string | null;
  // KF-28: lo que Enviar necesita y lo que deja.
  cliente_id?: number | null;
  punto_partida_id?: number | null;
  enviada_en?: string | null;
  decidido_por?: string | null;
};

export type Factura = {
  id: number;
  numero: string;
  fecha?: string | null;
  vence?: string | null;
  monto_centavos: number;
  pagado_centavos?: number;
  estado?: "pendiente" | "parcial" | "pagada" | "revisar" | "sin_cruzar";
};

export type Pendiente = {
  id: number;
  descripcion: string;
  responsable?: string | null;
  fecha_limite?: string | null;
  hecho?: boolean;
};

export type Leccion = {
  id: number;
  categoria?: string | null;
  que_paso: string;
  estado?: "propuesta" | "aprobada" | "descartada";
  repeticiones?: number;
  /** Las evidencias que la ligaron al cliente (KF-21: marca de fricción). */
  evidencias?: Evidencia[];
};

export type Evidencia = {
  id: number;
  leccion_id: number;
  correo_id?: number | null;
  minuta_id?: number | null;
  factura_id?: number | null;
};

export type Fuente = "correos" | "minutas" | "facturas";

export type Entrada = {
  id: number;
  clave: string;
  fuente: Fuente;
  tipo: "Correo" | "Minuta" | "Factura";
  fecha: string;
  titulo: string;
  detalle: string;
};

/** Cómo se nombra cada fuente cuando no carga. */
export const NOMBRE_FUENTE: Record<string, string> = {
  correos: "Gmail",
  minutas: "Minutas",
  facturas: "Facturas",
  pendientes: "Pendientes",
  lecciones: "Lecciones",
  contactos: "Contactos",
};

export const avisoFalla = (fuente: string) =>
  `${NOMBRE_FUENTE[fuente] ?? fuente} no cargó. Se muestra lo demás.`;

export const SIN_REGISTROS = "Aún no hay registros.";

/** Una fecha sola («2026-10-30») cuenta como el inicio de ese día. */
const instante = (fecha: string) =>
  new Date(fecha.length === 10 ? `${fecha}T00:00:00Z` : fecha).getTime();

const MESES = [
  "ene",
  "feb",
  "mar",
  "abr",
  "may",
  "jun",
  "jul",
  "ago",
  "sep",
  "oct",
  "nov",
  "dic",
];

/** «30 oct 2026». Se lee del texto ISO para que la zona horaria no mueva el día. */
export const fechaCorta = (fecha?: string | null) => {
  if (!fecha) return "Sin fecha";
  const [a, m, d] = fecha.slice(0, 10).split("-").map(Number);
  if (!a || !m || !d) return "Sin fecha";
  return `${d} ${MESES[m - 1]} ${a}`;
};

/** Centavos enteros a «$10,700.00». */
export const dinero = (centavos: number) =>
  `$${(centavos / 100).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;

export const ESTADO_FACTURA: Record<string, string> = {
  pendiente: "Pendiente",
  parcial: "Parcial",
  pagada: "Pagada",
  revisar: "Revisar",
  sin_cruzar: "Sin cruzar",
};

export const ESTADO_MINUTA: Record<string, string> = {
  borrador: "Borrador",
  ordenada: "Sin enviar",
  enviada: "Enviada al cliente",
};

export function armarLineaDeTiempo({
  correos = [],
  minutas = [],
  facturas = [],
}: {
  correos?: Correo[];
  minutas?: Minuta[];
  facturas?: Factura[];
}): Entrada[] {
  const entradas: Entrada[] = [
    ...correos.map(
      (c): Entrada => ({
        id: c.id,
        clave: `correo-${c.id}`,
        fuente: "correos",
        tipo: "Correo",
        fecha: c.fecha ?? "",
        titulo: c.asunto || "(sin asunto)",
        detalle: c.de ? `de ${c.de}` : "",
      }),
    ),
    ...minutas.map(
      (m): Entrada => ({
        id: m.id,
        clave: `minuta-${m.id}`,
        fuente: "minutas",
        tipo: "Minuta",
        fecha: m.creado_en ?? "",
        titulo: m.texto.split("\n")[0],
        detalle: m.acuerdos ?? "",
      }),
    ),
    ...facturas.map(
      (f): Entrada => ({
        id: f.id,
        clave: `factura-${f.id}`,
        fuente: "facturas",
        tipo: "Factura",
        fecha: f.fecha ?? "",
        titulo: `Factura ${f.numero}`,
        detalle: `${dinero(f.monto_centavos)} · ${
          ESTADO_FACTURA[f.estado ?? "pendiente"] ?? f.estado
        }`,
      }),
    ),
  ];
  // Por fecha, la más nueva primero. Sin fecha va al final.
  return entradas.sort(
    (a, b) =>
      (b.fecha ? instante(b.fecha) : -Infinity) -
      (a.fecha ? instante(a.fecha) : -Infinity),
  );
}

/** Lecciones con evidencia en un correo, minuta o factura del cliente. */
export function leccionesDelCliente(
  evidencias: Evidencia[],
  ids: { correos: number[]; minutas: number[]; facturas: number[] },
): number[] {
  const c = new Set(ids.correos);
  const m = new Set(ids.minutas);
  const f = new Set(ids.facturas);
  return [
    ...new Set(
      evidencias
        .filter(
          (e) =>
            (e.correo_id != null && c.has(e.correo_id)) ||
            (e.minuta_id != null && m.has(e.minuta_id)) ||
            (e.factura_id != null && f.has(e.factura_id)),
        )
        .map((e) => e.leccion_id),
    ),
  ];
}

/**
 * KF-21 · c2-expediente-correo: correo → la lección PROPUESTA que tiene
 * evidencia en él. Sale de las mismas lecciones de la pestaña Lecciones
 * (buscadas por evidencia), sin otra búsqueda.
 */
export function friccionPorCorreo(lecciones: Leccion[] = []) {
  const porCorreo = new Map<number, Leccion>();
  for (const l of lecciones) {
    if ((l.estado ?? "propuesta") !== "propuesta") continue;
    for (const e of l.evidencias ?? [])
      if (e.correo_id != null && !porCorreo.has(e.correo_id))
        porCorreo.set(e.correo_id, l);
  }
  return porCorreo;
}
