// ---------- Clasificación ---------- prototipo/src/presupuesto.mjs:4-61

/** Días de diferencia entre la salida y la entrada de un mismo pase entre cuentas propias. */
export const VENTANA_DIAS = 3;

export type Cuenta = {
  id: string;
  titular: string;
  ambito: "empresa" | "casa";
  clase: "cuenta" | "tarjeta";
};
export type Regla = { patron: string; categoria: string; grupo: string };
export type ReglaIngreso = { patron: string; origen: string };

export type TipoMovimiento =
  | "pago de tarjeta"
  | "entre mis cuentas"
  | "ingreso"
  | "cobro de empresa"
  | "gasto"
  | "por clasificar";

/** Los dos primeros son neutros: no suman ni como gasto ni como ingreso. */
export const NEUTROS: TipoMovimiento[] = [
  "pago de tarjeta",
  "entre mis cuentas",
];

export type Clasificado = Movimiento & {
  i: number;
  tipo: TipoMovimiento | null;
  origen?: string;
  categoria?: string;
  grupo?: string;
  par?: number;
};

/** prototipo/src/presupuesto.mjs:13 */
export const claveMov = (m: {
  cuenta: string;
  fecha: string;
  referencia?: string;
}) => `${m.cuenta}|${m.fecha}|${m.referencia ?? ""}`;

/**
 * @param movs     + entra, − sale (centavos)
 * @param reglas   «Recordar para los próximos» agrega aquí
 * @param ingresos alquileres, otros
 * @param cobrados claveMov de las entradas que el cruce ya asignó a facturas
 * prototipo/src/presupuesto.mjs:15-61
 */
export function clasificar(
  movs: Movimiento[],
  cuentas: Cuenta[],
  reglas: Regla[],
  ingresos: ReglaIngreso[] = [],
  cobrados: Set<string> = new Set(),
): Clasificado[] {
  const porId = Object.fromEntries(cuentas.map((c) => [c.id, c]));
  const ms: Clasificado[] = movs.map((m, i) => ({ ...m, i, tipo: null }));

  // 1) Pares entre cuentas propias: misma cantidad, signo opuesto, cuentas distintas, ±VENTANA_DIAS.
  // KF-32: con un mes real hay montos redondos repetidos (un Yappy de 100 y
  // un traspaso de 100 dos días después). Se emparejan primero los pares más
  // cercanos en fecha; así el traspaso del mismo día no se lo lleva otro. A
  // igual distancia gana el par cuyas descripciones comparten más palabras
  // («TRANSFERENCIA A … ANA» con «TRANSFERENCIA DE … ANA», no un Yappy a un
  // tercero del mismo monto y el mismo día).
  // Una cuenta que no está configurada no es propia: no se empareja.
  const palabras = (m: Movimiento) =>
    new Set(
      norm(m.descripcion)
        .split(/[^a-z0-9]+/)
        .filter((p) => p.length > 2),
    );
  const candidatos: {
    sale: Clasificado;
    entra: Clasificado;
    dias: number;
    comunes: number;
  }[] = [];
  const entradas = ms.filter((m) => m.monto > 0 && porId[m.cuenta]);
  for (const sale of ms.filter((m) => m.monto < 0 && porId[m.cuenta]))
    for (const entra of entradas) {
      if (entra.monto !== -sale.monto || entra.cuenta === sale.cuenta) continue;
      const dias = Math.abs(diasEntre(sale.fecha, entra.fecha));
      if (dias > VENTANA_DIAS) continue;
      const pe = palabras(entra);
      const comunes = [...palabras(sale)].filter((p) => pe.has(p)).length;
      candidatos.push({ sale, entra, dias, comunes });
    }
  candidatos.sort(
    (a, b) =>
      a.dias - b.dias ||
      b.comunes - a.comunes ||
      a.sale.i - b.sale.i ||
      a.entra.i - b.entra.i,
  );
  for (const { sale, entra } of candidatos) {
    if (sale.tipo || entra.tipo) continue;
    const origen = porId[sale.cuenta];
    const destino = porId[entra.cuenta];
    if (destino.clase === "tarjeta") {
      // Pago a la tarjeta: los gastos ya están en la tarjeta. Ninguno de los dos cuenta.
      sale.tipo = entra.tipo = "pago de tarjeta";
    } else if (origen.ambito === "empresa" && destino.ambito === "casa") {
      // DPB → Cesar: ingreso de la casa; la salida de la empresa no es gasto.
      entra.tipo = "ingreso";
      entra.origen = `transferencia de ${origen.titular}`;
      sale.tipo = "entre mis cuentas";
    } else {
      sale.tipo = entra.tipo = "entre mis cuentas";
    }
    sale.par = entra.i;
    entra.par = sale.i;
  }

  // 2) Ingresos por patrón (alquileres…), 3) gastos por regla, 4) el resto queda por clasificar.
  for (const m of ms.filter((x) => !x.tipo)) {
    const d = norm(m.descripcion);
    if (m.monto > 0 && cobrados.has(claveMov(m))) {
      // Lo que ya se cruzó con una factura vive en Cobros; no se suma otra vez como ingreso.
      m.tipo = "cobro de empresa";
      continue;
    }
    if (m.monto > 0) {
      const ing = ingresos.find((r) => d.includes(norm(r.patron)));
      m.tipo = "ingreso";
      m.origen = ing ? ing.origen : "otros";
      continue;
    }
    const regla = reglas.find((r) => d.includes(norm(r.patron)));
    if (regla)
      Object.assign(m, {
        tipo: "gasto",
        categoria: regla.categoria,
        grupo: regla.grupo,
      });
    else m.tipo = "por clasificar";
  }
  return ms;
}

// ---------- Resumen del mes ---------- prototipo/src/presupuesto.mjs:63-107

export type EstadoCategoria = "Bien" | "Cerca" | "Al tope" | "Pasado";

export function estadoCategoria(
  gastado: number,
  presupuesto: number,
): EstadoCategoria {
  if (!presupuesto) return gastado > 0 ? "Pasado" : "Bien";
  const avance = gastado / presupuesto;
  if (avance > 1) return "Pasado";
  if (gastado === presupuesto) return "Al tope";
  if (avance >= 0.8) return "Cerca";
  return "Bien";
}

export type Fijo = {
  pago: string;
  dia: number;
  cuenta: string;
  patron?: string;
};

export function resumenMes(
  ms: Clasificado[],
  {
    mes,
    vista = "todo",
    cuentas,
    presupuestos,
    fijos = [],
    hoy,
  }: {
    mes: string;
    vista?: "todo" | "casa" | "empresa";
    cuentas: Cuenta[];
    presupuestos: Record<string, number>;
    fijos?: Fijo[];
    hoy: () => string;
  },
) {
  const porId = Object.fromEntries(cuentas.map((c) => [c.id, c]));
  const delMes = ms.filter(
    (m) =>
      m.fecha.startsWith(mes) &&
      (vista === "todo" || porId[m.cuenta]?.ambito === vista),
  );
  const entro = delMes
    .filter((m) => m.tipo === "ingreso")
    .reduce((s, m) => s + m.monto, 0);
  const gastos = delMes.filter((m) => m.tipo === "gasto");
  const salio = gastos.reduce((s, m) => s - m.monto, 0);
  const categorias = Object.entries(presupuestos).map(
    ([categoria, presupuesto]) => {
      const gastado = gastos
        .filter((g) => g.categoria === categoria)
        .reduce((s, g) => s - g.monto, 0);
      return {
        categoria,
        presupuesto,
        gastado,
        avance: presupuesto ? Math.round((gastado / presupuesto) * 100) : null,
        estado: estadoCategoria(gastado, presupuesto),
      };
    },
  );
  // Orden fijo de «de dónde entró»: transferencias de las empresas, luego por patrón, «otros» al final.
  const rango = (o = "") =>
    o.startsWith("transferencia") ? 0 : o === "otros" ? 2 : 1;
  const origenes: Record<string, number> = {};
  const ingresosMes = delMes
    .filter((x) => x.tipo === "ingreso")
    .sort((a, b) => rango(a.origen) - rango(b.origen));
  for (const m of ingresosMes)
    origenes[m.origen!] = (origenes[m.origen!] ?? 0) + m.monto;
  const pagosFijos = fijos.map((f) => {
    // KF-17: cada palabra del patrón aparece, en cualquier orden. El banco
    // escribe «ENSA FACTURA LUZ» y el pago se llama «Luz ENSA»; la tabla
    // pagos_fijos no tiene columna de patrón. Con un patrón de una palabra
    // (el del prototipo) es lo mismo que antes.
    const palabras = norm(f.patron ?? f.pago)
      .split(/\s+/)
      .filter(Boolean);
    const visto = delMes.find(
      (m) =>
        m.cuenta === f.cuenta &&
        m.monto < 0 &&
        palabras.every((p) => norm(m.descripcion).includes(p)),
    );
    const vencido = `${mes}-${String(f.dia).padStart(2, "0")}` < hoy();
    return {
      ...f,
      estado: visto ? "Pagado" : vencido ? "Atrasado" : "Por pagar",
    };
  });
  return {
    mes,
    vista,
    entro,
    salio,
    balance: entro - salio,
    porClasificar: delMes.filter((m) => m.tipo === "por clasificar").length,
    categorias,
    origenes,
    pagosFijos,
  };
}

// ---------- Semillas (nuevo en KF-15) ----------

/**
 * Excel PRESUPUESTO: categorías en columnas, una fila por movimiento con su
 * origen. En el de Cesar (06 CASH FLOW/…/PRESUPUESTO aaaammdd.xlsx) hay una
 * hoja por mes con «Item | Fecha | Descripcion | categorías…» debajo de una
 * fila de totales, y una hoja BASE sin esa tabla. Se leen todas las hojas que
 * tienen la tabla. Los montos de cada categoría salen de una fila
 * «Presupuesto» si existe; si no, quedan en null y se ponen en la app.
 * Una fila con monto y sin fecha no tumba el archivo: va a sinFecha y no se
 * siembra. Un texto en una columna de categoría no es un monto.
 */
export const COLUMNAS_PRESUPUESTO = ["Fecha", "Origen"];
const ORIGEN = ["origen", "descripcion"];
const NO_CATEGORIA = ["item", "fecha", ...ORIGEN];
// KF-32: el Excel real trae «Cuenta / Tarjeta» y «Nota / revisar» al final;
// son texto, no categorías. La cuenta se guarda en cada movimiento.
const esCuenta = (t: unknown) => norm(t).startsWith("cuenta");
const noEsCategoria = (t: string) =>
  NO_CATEGORIA.includes(norm(t)) ||
  norm(t).startsWith("total") ||
  esCuenta(t) ||
  norm(t).startsWith("nota");
/** Una hoja que es lista (Fecha, Cuenta, Monto, Tipo), como EXCLUIDOS. */
const esLista = (titulos: unknown[]) =>
  ["monto", "tipo"].every((c) => titulos.some((t) => norm(t) === c));

export type SemillaPresupuesto = {
  /** Monto mensual de cada categoría en centavos; null si el Excel no lo trae. */
  categorias: { nombre: string; monto: number | null }[];
  movimientos: {
    hoja: string;
    fecha: string;
    origen: string;
    categoria: string;
    monto: number;
    /** «Cuenta / Tarjeta» de la fila, si el Excel trae esa columna (KF-32). */
    cuenta?: string;
  }[];
  /** Filas con monto pero sin fecha válida: se avisan y no se siembran. */
  sinFecha: { hoja: string; fila: number; origen: string }[];
};

/** Número o texto numérico → centavos; cualquier otro texto → 0. */
function montoCelda(v: unknown): number {
  try {
    return centavos(v);
  } catch {
    return 0;
  }
}

export function leerPresupuestoExcel(
  XLSX: XLSX,
  bytes: Uint8Array,
): SemillaPresupuesto {
  const libro = XLSX.read(bytes, { type: "array", cellDates: true });
  const categorias = new Map<string, number | null>();
  const movimientos: SemillaPresupuesto["movimientos"] = [];
  const sinFecha: SemillaPresupuesto["sinFecha"] = [];
  let vioTabla = false;
  for (const hoja of libro.SheetNames) {
    const filas = XLSX.utils.sheet_to_json<unknown[]>(libro.Sheets[hoja], {
      header: 1,
      raw: true,
      defval: "",
    });
    const iTitulos = filas
      .slice(0, 15)
      .findIndex(
        (f) =>
          f.some((v) => norm(v) === "fecha") &&
          f.some((v) => ORIGEN.includes(norm(v))),
      );
    if (iTitulos < 0 || esLista(filas[iTitulos])) continue;
    vioTabla = true;
    const titulos = filas[iTitulos].map((t) => String(t).trim());
    const iCuenta = titulos.findIndex(esCuenta);
    const iFecha = titulos.findIndex((t) => norm(t) === "fecha");
    const iOrigen = titulos.findIndex((t) => ORIGEN.includes(norm(t)));
    const cats = titulos
      .map((nombre, i) => ({ nombre, i }))
      .filter((c) => c.nombre !== "" && !noEsCategoria(c.nombre));
    const esTope = (f: unknown[]) =>
      f
        .slice(0, Math.max(iFecha, iOrigen) + 1)
        .some((v) => norm(v) === "presupuesto");
    for (const c of cats)
      if (!categorias.has(c.nombre)) categorias.set(c.nombre, null);
    filas.forEach((f, i) => {
      if (i <= iTitulos) return;
      if (esTope(f)) {
        for (const c of cats) categorias.set(c.nombre, montoCelda(f[c.i]));
        return;
      }
      const conMonto = cats.filter((c) => montoCelda(f[c.i]) !== 0);
      if (!conMonto.length) return; // fila vacía o sin monto
      const origen = String(f[iOrigen]).trim();
      let fecha: string;
      try {
        fecha = fechaCelda(f[iFecha]);
      } catch {
        sinFecha.push({ hoja, fila: i + 1, origen });
        return;
      }
      for (const c of conMonto)
        movimientos.push({
          hoja,
          fecha,
          origen,
          categoria: c.nombre,
          monto: montoCelda(f[c.i]),
          ...(iCuenta < 0 ? {} : { cuenta: String(f[iCuenta]).trim() }),
        });
    });
  }
  if (!vioTabla)
    throw new ErrorLector(
      "presupuesto: ninguna hoja tiene las columnas Fecha y Origen (o Descripción)",
      COLUMNAS_PRESUPUESTO,
    );
  return {
    categorias: [...categorias].map(([nombre, monto]) => ({ nombre, monto })),
    movimientos,
    sinFecha,
  };
}

/** Lista de pagos fijos: pago, día del mes, cuenta; Monto si viene. */
export const COLUMNAS_FIJOS = ["Pago", "Día", "Cuenta"];

export type SemillaFijo = {
  pago: string;
  dia: number;
  cuenta: string;
  monto: number;
};

export function leerFijosExcel(XLSX: XLSX, bytes: Uint8Array): SemillaFijo[] {
  const { titulos, filas } = tablaExcelCruda(
    XLSX,
    bytes,
    COLUMNAS_FIJOS,
    "pagos fijos",
  );
  const col = (n: string) => titulos.findIndex((t) => norm(t) === norm(n));
  const [iPago, iDia, iCuenta, iMonto] = ["Pago", "Día", "Cuenta", "Monto"].map(
    col,
  );
  return filas.map((f) => {
    const pago = String(f[iPago]).trim();
    const dia = Number(f[iDia]);
    if (!Number.isInteger(dia) || dia < 1 || dia > 31)
      throw new ErrorLector(
        `pagos fijos: ${pago} tiene el día ${f[iDia]}; va de 1 a 31`,
        ["Día"],
      );
    return {
      pago,
      dia,
      cuenta: String(f[iCuenta]).trim(),
      monto: iMonto < 0 ? 0 : centavos(f[iMonto]),
    };
  });
}

// ---------- Excel real de Cesar (KF-32) ----------

export type Excluido = {
  fecha: string;
  cuenta: string;
  descripcion: string;
  monto: number;
  tipo: string;
};

/**
 * Hoja-lista de lo que Cesar deja fuera del presupuesto (EXCLUIDOS):
 * «Fecha | Cuenta / Tarjeta | Descripción | Monto | Tipo». Son sus traspasos
 * internos y pagos de tarjeta: lo que la app tiene que dejar neutro.
 */
export function leerExcluidosExcel(XLSX: XLSX, bytes: Uint8Array): Excluido[] {
  const libro = XLSX.read(bytes, { type: "array", cellDates: true });
  const lista: Excluido[] = [];
  for (const hoja of libro.SheetNames) {
    const filas = XLSX.utils.sheet_to_json<unknown[]>(libro.Sheets[hoja], {
      header: 1,
      raw: true,
      defval: "",
    });
    const iTitulos = filas
      .slice(0, 15)
      .findIndex((f) => f.some((v) => norm(v) === "fecha") && esLista(f));
    if (iTitulos < 0) continue;
    const t = filas[iTitulos];
    const col = (pred: (v: unknown) => boolean) => t.findIndex(pred);
    const iFecha = col((v) => norm(v) === "fecha");
    const iCuenta = col(esCuenta);
    const iDesc = col((v) => ORIGEN.includes(norm(v)));
    const iMonto = col((v) => norm(v) === "monto");
    const iTipo = col((v) => norm(v) === "tipo");
    for (const f of filas.slice(iTitulos + 1)) {
      const monto = montoCelda(f[iMonto]);
      if (!monto) continue;
      let fecha: string;
      try {
        fecha = fechaCelda(f[iFecha]);
      } catch {
        continue;
      }
      lista.push({
        fecha,
        cuenta: iCuenta < 0 ? "" : String(f[iCuenta]).trim(),
        descripcion: iDesc < 0 ? "" : String(f[iDesc]).trim(),
        monto,
        tipo: String(f[iTipo]).trim(),
      });
    }
  }
  return lista;
}

export type FijoBase = { grupo: string; pago: string; monto: number };

/**
 * Pagos fijos de la hoja «BASE DE PRESUPUESTO»: bloques de «nombre | monto
 * mensual» separados por una fila en blanco. La primera fila del bloque es su
 * total (grupo); si la segunda también suma el resto, es el grupo y la
 * primera un total mayor. No trae día ni cuenta: eso queda para la app.
 * Las tablas con «Item» a la izquierda (resúmenes) no son pagos.
 */
export function leerFijosBase(XLSX: XLSX, bytes: Uint8Array): FijoBase[] {
  const libro = XLSX.read(bytes, { type: "array", cellDates: true });
  const hoja = libro.SheetNames.find((h) => norm(h).startsWith("base"));
  if (!hoja)
    throw new ErrorLector(
      "pagos fijos: no encontré la hoja BASE DE PRESUPUESTO",
      ["BASE DE PRESUPUESTO"],
    );
  const filas = XLSX.utils.sheet_to_json<unknown[]>(libro.Sheets[hoja], {
    header: 1,
    raw: true,
    defval: "",
  });
  const ancho = Math.max(...filas.map((f) => f.length));
  const esNombre = (v: unknown) => typeof v === "string" && v.trim() !== "";
  const fijos: FijoBase[] = [];
  for (let c = 0; c + 1 < ancho; c++) {
    let bloque: { nombre: string; monto: number }[] = [];
    let resumen = false;
    const cerrar = () => {
      const montos = bloque.map((b) => b.monto);
      const suma = (desde: number) =>
        montos.slice(desde).reduce((s, m) => s + m, 0);
      const cuadra = (i: number) =>
        bloque.length > i + 1 && Math.abs(montos[i] - suma(i + 1)) <= 1;
      const iGrupo = cuadra(0) ? 0 : cuadra(1) ? 1 : -1;
      if (!resumen && iGrupo >= 0)
        for (const b of bloque.slice(iGrupo + 1))
          fijos.push({
            grupo: bloque[iGrupo].nombre,
            pago: b.nombre,
            monto: b.monto,
          });
      bloque = [];
      resumen = false;
    };
    filas.forEach((f) => {
      const [nombre, monto] = [f[c], f[c + 1]];
      if (esNombre(nombre) && typeof monto === "number" && monto > 0) {
        if (!bloque.length && c > 0 && norm(f[c - 1]) === "item")
          resumen = true;
        bloque.push({ nombre: String(nombre).trim(), monto: centavos(monto) });
      } else if (bloque.length) cerrar();
    });
    if (bloque.length) cerrar();
  }
  return fijos;
}
