import { fechaCorta, type Pendiente } from "../expediente/lineaDeTiempo";

export const MINUTA_EN_COLA_NO_ENVIA =
  "Todavía se está ordenando: se podrá enviar cuando la PC la ordene.";
export const SIN_CORREO_CLIENTE =
  "El cliente no tiene contactos con correo. Agrega uno para enviar.";

type ConCorreos = { email_jsonb?: { email: string }[] | null };

/** Los correos de los contactos del cliente, sin repetir y en orden. */
export const destinatarios = (contactos: ConCorreos[] = []) => [
  ...new Set(
    contactos
      .flatMap((c) => c.email_jsonb ?? [])
      .map((e) => e.email?.trim())
      .filter((e): e is string => !!e),
  ),
];

/** Los acuerdos se guardan uno por línea (pc/minuta.mjs). */
export const listaAcuerdos = (acuerdos?: string | null) =>
  (acuerdos ?? "").split("\n").filter(Boolean);

const lineaPendiente = (p: Pendiente) =>
  `- ${p.descripcion} · Responsable: ${p.responsable || "sin responsable"} · Fecha: ${fechaCorta(p.fecha_limite)}`;

/** El correo de la minuta: asunto con el proyecto, acuerdos y pendientes. */
export function armarCorreo({
  proyecto,
  fecha,
  acuerdos,
  pendientes,
}: {
  proyecto: string;
  fecha?: string | null;
  acuerdos?: string | null;
  pendientes: Pendiente[];
}) {
  const a = listaAcuerdos(acuerdos);
  const cuerpo = [
    "Hola:",
    "",
    `Esta es la minuta de la reunión del ${fechaCorta(fecha)} · ${proyecto}.`,
    "",
    "Acuerdos:",
    ...(a.length ? a.map((x) => `- ${x}`) : ["- Sin acuerdos."]),
    "",
    "Pendientes:",
    ...(pendientes.length
      ? pendientes.map(lineaPendiente)
      : ["- Sin pendientes."]),
    "",
    "Saludos.",
  ].join("\n");
  return { asunto: `Minuta · ${proyecto}`, cuerpo };
}

/** mailto según RFC 6068: todo con encodeURIComponent, sin «+». */
export const mailto = (para: string[], asunto: string, cuerpo: string) =>
  `mailto:${para.map(encodeURIComponent).join(",")}?subject=${encodeURIComponent(
    asunto,
  )}&body=${encodeURIComponent(cuerpo)}`;
